CREATE OR REPLACE FUNCTION openpc.admit_identity_envelope_recovery_trust(p_preimage bytea, p_digest bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'control'
 SET row_security TO 'on'
AS $function$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation; old_key control.business_signing_key;
 descriptor jsonb; issuer jsonb; key_row control.business_signing_key; admission bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
  AND openpc.matches_participant(s.participant_id) AND openpc.matches_privacy(s.privacy_domain_id)
  AND s.from_revision=4 AND s.from_state='DISTRIBUTED' AND s.to_state='VERIFIED' AND s.state='COMMITTED';
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR p_digest<>sha256(p_preimage)
  OR step.result->>'trustDigest' IS DISTINCT FROM 'sha256:'||encode(p_digest,'hex') THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-ADMISSION'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=step.participant_id
  AND r.privacy_domain_id=step.privacy_domain_id AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id
  AND r.state='VERIFIED' AND r.revision=5;
 SELECT * INTO STRICT old_key FROM control.business_signing_key k WHERE k.participant_id=step.participant_id
  AND k.privacy_domain_id=step.privacy_domain_id AND k.signer_id=rotation.old_signer_id;
 SELECT a.observation->'descriptor' INTO STRICT descriptor FROM control.identity_envelope_rotation_attempt a
  JOIN control.identity_envelope_rotation_step prepared USING(participant_id,privacy_domain_id,rotation_id,operation_id)
  WHERE prepared.participant_id=step.participant_id AND prepared.privacy_domain_id=step.privacy_domain_id
   AND prepared.rotation_id=step.rotation_id AND prepared.recovery_id=step.recovery_id
   AND prepared.from_revision=2 AND prepared.to_state='PREPARED' AND prepared.state='COMMITTED' AND a.slot='new' AND a.state='OBSERVED';
 issuer:=step.authority_binding#>'{lease,issuer}';
 admission:=sha256(convert_to('pc.identity.envelope-key-recovery-admission.v1','UTF8')||decode('00','hex')||
  convert_to(openpc.signing_canonical_json(step.authority_binding||jsonb_build_object('issuer',issuer,
    'newFingerprint',descriptor->>'fingerprint','newReference',descriptor->>'reference','newVersion',descriptor->>'version')),'UTF8'));
 key_row.participant_id:=step.participant_id;key_row.privacy_domain_id:=step.privacy_domain_id;key_row.signer_id:=descriptor->>'fingerprint';
 key_row.signing_purpose_code:=371;key_row.environment_id:=rotation.environment_id;key_row.public_key_spki_der:=decode(descriptor->>'publicKeySpkiHex','hex');
 key_row.workload_credential_id:=(issuer->>'workloadCredentialId')::uuid;key_row.workload_credential_epoch:=(issuer->>'workloadCredentialEpoch')::numeric;
 key_row.envelope_workload_participant_epoch:=(issuer->>'workloadParticipantEpoch')::numeric;key_row.envelope_workload_principal_epoch:=(issuer->>'workloadPrincipalEpoch')::numeric;
 key_row.key_epoch:=old_key.key_epoch+1;key_row.valid_from_ns:=(descriptor->>'validFromNs')::numeric;key_row.valid_until_ns:=(descriptor->>'validUntilNs')::numeric;
 key_row.admission_kind:='GOVERNED';key_row.admission_reference:='urn:openpc:resource:'||rotation.rotation_id::text;key_row.admission_digest:=admission;
 key_row.secret_class:='SECRET-SIGNING-KEY';key_row.secret_reference:=descriptor->>'reference';key_row.secret_version:=descriptor->>'version';
 key_row.trust_preimage:=p_preimage;key_row.trust_digest:=p_digest;
 PERFORM openpc.check_identity_envelope_recovery_trust_admission(key_row);
 INSERT INTO control.business_signing_key SELECT (key_row).*;
 INSERT INTO control.identity_envelope_signing_grant(participant_id,privacy_domain_id,signer_id,signing_purpose_code,profile_digest)
  VALUES(key_row.participant_id,key_row.privacy_domain_id,key_row.signer_id,371,decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex'));
 INSERT INTO control.business_signing_key_state(participant_id,privacy_domain_id,signer_id,state,row_version,changed_at_ns,change_reference,change_digest)
  VALUES(key_row.participant_id,key_row.privacy_domain_id,key_row.signer_id,'ADMITTED',1,
   floor(extract(epoch from clock_timestamp())*1000000)*1000,key_row.admission_reference,step.evidence_digest);
 RETURN jsonb_build_object('signerId',key_row.signer_id,'trustDigest','sha256:'||encode(key_row.trust_digest,'hex'),'state','ADMITTED');
END $function$

CREATE OR REPLACE FUNCTION openpc.admit_notification_completion_phase(wire bytea, nonce bytea, mac bytea)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0;
BEGIN
 PERFORM openpc.assert_notification_completion_admission_owner();
 IF wire IS NULL OR octet_length(wire) NOT BETWEEN 1 AND 8192 OR nonce IS NULL OR octet_length(nonce)<>32
  OR mac IS NULL OR octet_length(mac)<>32 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.notification_completion_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_NOTIFICATION_COMPLETION_PHASE_ADMISSION_V1','UTF8')||sha256(wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 proof:=convert_from(wire,'UTF8')::jsonb;
 PERFORM openpc.check_notification_completion_phase_proof(proof);
 INSERT INTO control.notification_completion_phase_admission(database_role,transaction_id,backend_pid,
  participant_id,privacy_domain_id,event_id,phase,proof,receipt_binding)
 VALUES(session_user,pg_current_xact_id()::text,pg_backend_pid(),openpc.current_participant_id(),
  openpc.current_privacy_domain_id(),(proof->>'eventId')::uuid,proof->>'phase',proof,nullif(proof->'receiptBinding','null'::jsonb))
 ON CONFLICT(database_role,transaction_id,event_id,phase) DO UPDATE SET proof=excluded.proof,receipt_binding=excluded.receipt_binding
 WHERE notification_completion_phase_admission.participant_id=excluded.participant_id
  AND notification_completion_phase_admission.privacy_domain_id=excluded.privacy_domain_id
  AND notification_completion_phase_admission.backend_pid=excluded.backend_pid
  AND notification_completion_phase_admission.proof->>'installationDigest'=excluded.proof->>'installationDigest'
  AND notification_completion_phase_admission.proof->>'authorityDigest'=excluded.proof->>'authorityDigest'
  AND (notification_completion_phase_admission.receipt_binding IS NULL
   OR notification_completion_phase_admission.receipt_binding=excluded.receipt_binding);
 IF NOT FOUND THEN RAISE EXCEPTION 'NOTIFICATION-COMPLETION-NATIVE-CONFLICT'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.admit_notification_occurrence_metadata(item control.notification)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE bound_preparation_id uuid; dp control.notification_occurrence_preparation%ROWTYPE; op control.notification_occurrence_preparation%ROWTYPE;
BEGIN
 IF openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 bound_preparation_id:=openpc.notification_occurrence_metadata_preparation(item);
 SELECT p.* INTO STRICT dp FROM control.notification_occurrence_preparation p
 WHERE p.participant_id=item.participant_id AND p.privacy_domain_id=item.privacy_domain_id AND p.preparation_id=bound_preparation_id;
 SELECT p.* INTO STRICT op FROM control.notification_occurrence_preparation p
 WHERE p.participant_id=dp.participant_id AND p.privacy_domain_id=dp.privacy_domain_id AND p.key_preparation_id=dp.key_preparation_id AND p.family='NotificationOccurrenceReceiptV1';
 -- Fresh preparation checks bind ACTIVE installed profiles, roles, genuine source,
 -- route, original key/ciphertext/AAD digests and both immutable signed inputs.
 -- Actual peer and current key STATUS admission is held by the application owner
 -- on this same client; this SQL function grants no transferable capability.
 PERFORM openpc.check_notification_occurrence_preparation(op);
 PERFORM openpc.check_notification_occurrence_preparation(dp);
END $function$

CREATE OR REPLACE FUNCTION openpc.append_rotation_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE previous_state text; previous_digest bytea; operation uuid; event uuid; receipt uuid; evidence uuid; preimage bytea; ordinal numeric;
BEGIN
 previous_state:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.state END;
 SELECT history_digest INTO previous_digest FROM control.signing_rotation_history
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND revision=NEW.revision-1;
 IF NEW.revision>1 AND previous_digest IS NULL THEN RAISE EXCEPTION 'DATA-6021-ROTATION-HISTORY-GAP'; END IF;
 IF NEW.state='REQUESTED' THEN operation:=openpc.current_operation_id();
 ELSIF NEW.state='APPROVED' AND OLD.state='REQUESTED' THEN operation:=NEW.approved_operation_id;
 ELSE
  SELECT operation_id INTO STRICT operation FROM control.signing_rotation_command
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id
   AND operation_id=openpc.current_operation_id()
   AND (from_revision=OLD.revision OR (OLD.state='RECOVERING'
    AND openpc.current_action_intent_id()='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' AND from_revision=OLD.recovery_from_revision));
 END IF;
 IF NEW.state<>'REQUESTED' AND NOT (NEW.state='APPROVED' AND OLD.state='REQUESTED') THEN
  SELECT a.event_id,a.attempt_id,a.evidence_record_id,a.receipt_ordinal INTO STRICT event,receipt,evidence,ordinal
  FROM control.signing_rotation_attestation a JOIN control.signing_provider_attempt p USING(attempt_id)
  WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.operation_id=operation
   AND a.rotation_id=NEW.rotation_id AND a.from_revision=OLD.revision AND a.to_state=NEW.state
   AND p.state IN ('OBSERVED','ACCEPTED') AND p.observation->>'outcome'='SUCCEEDED';
  IF ordinal<>1+coalesce((SELECT max(receipt_ordinal) FROM control.signing_rotation_history
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id),0)
  THEN RAISE EXCEPTION 'DATA-6021-ROTATION-RECEIPT-ORDINAL'; END IF;
 END IF;
 preimage:=openpc.rotation_history_preimage(NEW,previous_state,operation,event,receipt,evidence);
 INSERT INTO control.signing_rotation_history(participant_id,privacy_domain_id,rotation_id,revision,prior_state,state,operation_id,
  prior_digest,history_preimage,history_digest,event_id,receipt_id,evidence_id,receipt_namespace,receipt_ordinal)
 VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.rotation_id,NEW.revision,previous_state,NEW.state,operation,
  previous_digest,preimage,sha256(preimage),event,receipt,evidence,
  CASE WHEN receipt IS NULL THEN NULL ELSE 'CONTROL_SIGNING_LIFECYCLE_V1' END,ordinal);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.archive_cose_binding(payload bytea, cose bytea, key_id text, schema_id integer, purpose integer)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE parsed jsonb; header jsonb;
BEGIN
 IF octet_length(payload) NOT BETWEEN 1 AND 65536 OR octet_length(cose) NOT BETWEEN 65 AND 66560
  OR get_byte(cose,0)<>210 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 parsed:=openpc.business_cbor_item(cose,1,0);
 IF (parsed->>'next')::integer IS DISTINCT FROM octet_length(cose) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 parsed:=parsed->'value';
 IF jsonb_typeof(parsed) IS DISTINCT FROM 'array' OR jsonb_array_length(parsed)<>4
  OR parsed->1 IS DISTINCT FROM '{}'::jsonb OR parsed->2 IS DISTINCT FROM openpc.business_bytes(payload)
  OR parsed->3 IS DISTINCT FROM jsonb_build_object('bytes',parsed->3->>'bytes')
  OR coalesce(parsed->3->>'bytes','')!~'^[0-9a-f]{128}$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 header:=openpc.business_cbor(decode(parsed->0->>'bytes','hex'));
 IF header IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),
  '3','application/pc+cbor','4',openpc.business_bytes(convert_to(key_id,'UTF8')),
  '100',schema_id,'101',1,'102',purpose,'103',2) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_notification_delivery_start_atomic_guards()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE table_name text; trigger_name text; function_name text;
BEGIN
 FOREACH table_name IN ARRAY ARRAY['notification_delivery_start','notification_delivery_attempt','notification_delivery_dispatch_intent'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=('control.'||table_name)::regclass AND relrowsecurity AND relforcerowsecurity)
  THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
  trigger_name:=table_name||'_atomic_guard'; function_name:='openpc.guard_'||table_name||'_atomic()';
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=trigger_name AND tgtype=7 AND tgenabled IN ('O','A') AND tgfoid=function_name::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=table_name||'_atomic_immutable' AND tgtype=CASE WHEN table_name='notification_delivery_dispatch_intent' THEN 42 ELSE 58 END AND tgenabled IN ('O','A') AND tgfoid='openpc.deny_notification_delivery_start_atomic_mutation()'::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=table_name||'_complete' AND tgtype=CASE WHEN table_name='notification_delivery_dispatch_intent' THEN 21 ELSE 5 END AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred AND tgfoid='openpc.guard_notification_delivery_start_complete()'::regprocedure)
  THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_dispatch_intent'::regclass AND tgname='notification_delivery_dispatch_claim_guard' AND tgtype=19 AND tgenabled IN ('O','A') AND tgfoid='openpc.guard_notification_delivery_dispatch_claim()'::regprocedure) THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery'::regclass AND tgname='notification_delivery_start_complete' AND tgtype=17 AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred AND tgfoid='openpc.guard_notification_delivery_start_complete()'::regprocedure)
 THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_notification_receipt(receipt control.audit_occurrence)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE item control.notification%ROWTYPE; before_projection jsonb; after_projection jsonb;
BEGIN
 IF receipt.profile_version<>1 OR receipt.catalog_operation_id NOT IN
  ('CFG-OP-CREATE-NOTIFICATION','CFG-OP-ACKNOWLEDGE-NOTIFICATION')
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-PROFILE'; END IF;
 SELECT * INTO STRICT item FROM control.notification n WHERE n.participant_id=receipt.participant_id
  AND n.privacy_domain_id=receipt.privacy_domain_id AND n.notification_id=receipt.aggregate_id;
 before_projection:=openpc.business_cbor(receipt.before_state_preimage)->8;
 after_projection:=openpc.business_cbor(receipt.after_state_preimage)->8;
 IF receipt.after_existence<>1 OR receipt.after_revision<>item.revision
  OR after_projection IS DISTINCT FROM openpc.notification_business_projection(item)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ACTUAL-STATE'; END IF;
 IF receipt.catalog_operation_id='CFG-OP-CREATE-NOTIFICATION' THEN
  IF receipt.before_existence<>0 OR receipt.before_revision<>0 OR receipt.after_revision<>1
   OR item.state<>'UNREAD' OR item.candidate_digest IS DISTINCT FROM 'sha256:'||encode(receipt.candidate_digest,'hex')
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-CREATE'; END IF;
 ELSE
  IF receipt.before_existence<>1 OR receipt.after_revision<>receipt.before_revision+1
   OR before_projection->>'1' NOT IN ('UNREAD','READ') OR item.state<>'ACKNOWLEDGED'
   OR before_projection-'1' IS DISTINCT FROM after_projection-'1'
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ACKNOWLEDGE'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_protected_remote_checkpoint(v control.protected_proof_checkpoint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE i control.evidence_remote_archive_intent; p control.evidence_archive_profile; r control.evidence_archive_receipt;
BEGIN
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=(v).participant_id
  AND privacy_domain_id=(v).privacy_domain_id AND protected_object_id=(v).object_id AND sink_id=(v).sink_id AND source_kind='PROTECTED_PROOF';
 p:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),i.stream_id);
 IF p.claims->>'sourceKind' IS DISTINCT FROM 'PROTECTED_PROOF' OR p.transport IS DISTINCT FROM i.profile
  OR p.transport_digest IS DISTINCT FROM i.profile_digest OR p.sink_id IS DISTINCT FROM i.sink_id
  OR NOT openpc.protected_remote_checkpoint_valid(v)
  OR NOT openpc.protected_remote_archive_covers(i.participant_id,i.privacy_domain_id,i.protected_object_id,i.sink_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT r FROM control.evidence_archive_receipt WHERE participant_id=(v).participant_id
  AND privacy_domain_id=(v).privacy_domain_id AND receipt_digest=(v).receipt_digest;
 IF EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer WHERE newer.participant_id=i.participant_id
  AND newer.privacy_domain_id=i.privacy_domain_id AND newer.intent_id=i.intent_id
  AND (newer.binding->'protection'->>'revision')::numeric>(openpc.business_cbor(r.payload)->>'13')::numeric)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.require_archive_commit_nonce(r);
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_remote_archive_checkpoint(v control.evidence_checkpoint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r control.evidence_archive_receipt; a control.evidence_remote_archive_attempt;
 i control.evidence_remote_archive_intent; p control.evidence_archive_profile; s control.evidence_segment; expected jsonb;
BEGIN
 p:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),(v).stream_id);
 SELECT * INTO STRICT r FROM control.evidence_archive_receipt WHERE participant_id=(v).participant_id
  AND privacy_domain_id=(v).privacy_domain_id AND receipt_digest=(v).receipt_digest;
 SELECT * INTO STRICT a FROM control.evidence_remote_archive_attempt WHERE participant_id=r.participant_id
  AND privacy_domain_id=r.privacy_domain_id AND attempt_id=r.attempt_id AND intent_id=r.intent_id AND state='OBSERVED';
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=r.participant_id
  AND privacy_domain_id=r.privacy_domain_id AND intent_id=r.intent_id;
 SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=i.participant_id
  AND privacy_domain_id=i.privacy_domain_id AND stream_id=i.stream_id AND segment_id=i.segment_id;
 expected:=jsonb_build_object('kind','SIGNED_REMOTE_ARCHIVE_V1','receiptId',r.receipt_id::text,
  'receiptDigest',r.receipt_digest,'profileDigest',r.profile_digest,'assurance','REMOTE_INTERFACE_VERIFIED',
  'providerQualification','NOT_ESTABLISHED');
 IF (v).receipt IS DISTINCT FROM expected OR (v).sink_id<>i.sink_id OR (v).stream_id<>i.stream_id
  OR (v).segment_id<>i.segment_id OR (v).object_digest<>s.object_digest OR (v).through_sequence<>s.through_sequence
  OR i.profile_digest<>p.transport_digest OR i.profile IS DISTINCT FROM p.transport OR i.sink_id<>p.sink_id
  OR a.binding->'protection'->'rules' IS DISTINCT FROM openpc.remote_archive_rules(s)
  OR NOT openpc.remote_archive_covers(s.participant_id,s.privacy_domain_id,s.stream_id,s.segment_id,i.sink_id)
  OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer WHERE newer.participant_id=i.participant_id
   AND newer.privacy_domain_id=i.privacy_domain_id AND newer.intent_id=i.intent_id
   AND (newer.binding->'protection'->>'revision')::numeric>(a.binding->'protection'->>'revision')::numeric)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.require_archive_commit_nonce(r);
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_request_context(p_require_privacy boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'openpc'
AS $function$
DECLARE mode text;
BEGIN
  mode := current_setting('openpc.context_mode', true);
  IF current_setting('openpc.context_scope', true) <> 'TRANSACTION_LOCAL' OR mode NOT IN ('PARTICIPANT', 'PLATFORM') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6001-CONTEXT-INVALID';
  END IF;
  PERFORM openpc.current_participant_id();
  PERFORM openpc.current_operation_id();
  PERFORM openpc.current_action_intent_id();
  IF p_require_privacy THEN PERFORM openpc.current_privacy_domain_id(); END IF;
  IF mode = 'PLATFORM' AND NOT (
    current_user = 'openpc_control_platform_runtime'
    OR pg_has_role(current_user, 'openpc_control_platform_runtime', 'MEMBER')
    OR pg_has_role(current_user, 'openpc_control_migrator', 'MEMBER')
    OR pg_has_role(current_user, 'openpc_control_maintenance', 'MEMBER')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6002-PLATFORM-CONTEXT-FORBIDDEN';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_source_import(input control.runtime_configuration_input)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE s control.runtime_artifact_source; secret bytea; wire bytea; nonce bytea; mac bytea;
 expected bytea; different integer:=0; document jsonb; pending jsonb; root jsonb; installation jsonb;
 wire_text text:=current_setting('openpc.runtime_source_import_wire',true);
 nonce_text text:=current_setting('openpc.runtime_source_import_nonce',true);
 mac_text text:=current_setting('openpc.runtime_source_import_mac',true);
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF input.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR input.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
  AND privacy_domain_id=input.privacy_domain_id AND custody_root IS NOT NULL) THEN RETURN; END IF;
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
  AND privacy_domain_id=input.privacy_domain_id;
 IF s.database_role<>session_user OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-PROVIDER_PROFILES_READ_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('session_replication_role')<>'origin'
  OR coalesce(length(wire_text),0) NOT BETWEEN 2 AND 16384
  OR coalesce(nonce_text,'') !~ '^[0-9a-f]{64}$' OR coalesce(mac_text,'') !~ '^[0-9a-f]{64}$'
  OR wire_text !~ '^[0-9a-f]+$' OR length(wire_text)%2<>0
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 wire:=decode(wire_text,'hex'); nonce:=decode(nonce_text,'hex'); mac:=decode(mac_text,'hex');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key
  WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_SOURCE_IMPORT_V1'||pg_current_xact_id()::text
  ||encode(sha256(wire),'hex'),'UTF8')||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 document:=convert_from(wire,'UTF8')::jsonb;
 pending:=document->'pending'->'claims'; root:=document->'root'->'claims';
 installation:=jsonb_build_object('participant_id',s.participant_id::text,'privacy_domain_id',s.privacy_domain_id::text,
  'source_owner_id',s.source_owner_id::text,'source_file_binding',encode(s.source_file_binding,'hex'));
 IF document IS DISTINCT FROM jsonb_build_object('pending',document->'pending','root',document->'root')
  OR document->'pending'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-history:v1'
  OR document->'root'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-root:v1'
  OR pending->'installation' IS DISTINCT FROM installation OR root->'installation' IS DISTINCT FROM installation
  OR pending->'version' IS DISTINCT FROM '1'::jsonb OR root->'version' IS DISTINCT FROM '1'::jsonb
  OR root->'binding' IS DISTINCT FROM s.custody_root
  OR pending->'observation' IS DISTINCT FROM jsonb_build_object('ImportPending',jsonb_build_object(
   'input_id',input.runtime_configuration_input_id::text,'module_installation_id',input.module_installation_id::text,
   'module_configuration_generation_id',input.module_configuration_generation_id::text,
   'configuration_digest',encode(input.configuration_digest,'hex')))
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_runtime_target_disposition_owner()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF current_setting('session_replication_role')<>'origin' OR current_setting('row_security')<>'on'
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.runtime_unsigned_withdrawal_recoverable(uuid,bigint,text)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; abandoned control.runtime_target_disposition_admission;
 previous control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 failed control.configuration_work; generation control.runtime_configuration_generation; payload bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 IF target IS NULL OR wanted_revision IS NULL OR wanted_revision<2 OR wanted_digest IS NULL
  OR openpc.current_action_intent_id() NOT IN (''ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'',
   ''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'') THEN RETURN false; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
 THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 SELECT a.* INTO abandoned FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.revision=wanted_revision AND a.admission_digest=wanted_digest FOR SHARE NOWAIT;
 IF NOT FOUND OR abandoned.binding->>''action'' IS DISTINCT FROM ''Withdraw''
  OR abandoned.activation_proof IS NOT NULL OR abandoned.restoration_proof IS NOT NULL
  OR abandoned.binding->''cause''->>''kind'' IS DISTINCT FROM ''Activation''
  OR abandoned.binding->''cause''->''execution_attempt_id'' IS DISTINCT FROM ''null''::jsonb
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery d WHERE d.participant_id=pid
   AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=wanted_revision)
 THEN RETURN false; END IF;
 SELECT a.* INTO previous FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.revision=wanted_revision-1 FOR SHARE NOWAIT;
 IF NOT FOUND OR previous.binding->>''action'' IS DISTINCT FROM ''ConfirmActivation''
  OR previous.binding->''target'' IS DISTINCT FROM abandoned.binding->''target''
  OR previous.binding->''source'' IS DISTINCT FROM abandoned.binding->''source''
  OR abandoned.binding->''previous_revision'' IS DISTINCT FROM to_jsonb(previous.revision)
 THEN RETURN false; END IF;
 SELECT d.* INTO delivery FROM control.runtime_target_disposition_delivery d
  WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
   AND d.revision=previous.revision;
 IF NOT FOUND OR abandoned.binding->>''previous_delivery_digest'' IS DISTINCT FROM substring(delivery.delivery_digest from 8)
  OR NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement k
   WHERE k.participant_id=pid AND k.privacy_domain_id=privacy AND k.runtime_target_id=target
    AND k.delivery_digest=delivery.delivery_digest AND k.claims->>''installed_state''=''ActivationConfirmed'')
 THEN RETURN false; END IF;
 SELECT w.* INTO failed FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id::text=abandoned.binding->''cause''->>''work_id'' FOR SHARE NOWAIT;
 IF NOT FOUND OR abandoned.binding->''cause'' IS DISTINCT FROM jsonb_build_object(''kind'',''Activation'',
  ''work_id'',failed.configuration_work_id::text,''operation_id'',failed.operation_id::text,''execution_attempt_id'',NULL)
  OR failed.state IS DISTINCT FROM ''FAILED'' OR failed.work_kind IS DISTINCT FROM ''RUNTIME_ACTIVATION''
  OR failed.execution_started_at IS NOT NULL OR failed.execution_attempt_id IS NOT NULL
  OR failed.predecessor_digest IS DISTINCT FROM ''sha256:''||(abandoned.binding->''source''->>''capsule_digest'')
  OR failed.configuration_work_id::text=abandoned.binding->''source''->>''original_work_id''
 THEN RETURN false; END IF;
 SELECT g.* INTO generation FROM control.runtime_configuration_generation g
  WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
   AND g.runtime_configuration_generation_id=failed.runtime_configuration_generation_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN false; END IF;
 payload:=openpc.runtime_generation_retry_failure_payload(generation,failed);
 IF NOT EXISTS(SELECT 1 FROM control.outbox_event e JOIN control.mutation_evidence a
  ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
   AND a.operation_id=failed.operation_id AND a.aggregate_id=target
   AND a.action_intent_id=''ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1''
   AND a.catalog_operation_id=''CFG-OP-UPDATE-RUNTIME-TARGET''
   AND a.evidence_role=''AUTHORIZATION_INPUT'' AND a.evidence_format=''IDENTITY_RUNTIME_ASSERTION_3002_2_13''
  JOIN control.idempotency_record i ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
   AND i.operation_id=a.operation_id AND i.input_digest=a.candidate_digest AND i.terminal_state=''COMMITTED''
   AND i.result_payload->>''state''=''FAILED'' AND i.result_payload->>''truthState''=''FAILED''
  WHERE e.participant_id=pid AND e.privacy_domain_id=privacy AND e.event_id=failed.result_event_id
   AND e.aggregate_id=target AND e.aggregate_type=''runtime-targets'' AND e.event_type=''runtime-target.activation-failed.v1''
   AND e.payload_cbor=payload AND e.payload_digest=sha256(payload) AND e.cose_sign1=a.cose_sign1
   AND octet_length(a.cose_sign1)>0 AND a.evidence_digest=sha256(a.evidence_cbor))
  OR EXISTS(SELECT 1 FROM control.runtime_activation_observation o
   WHERE o.configuration_work_id=failed.configuration_work_id OR o.runtime_configuration_generation_id=generation.runtime_configuration_generation_id)
  OR EXISTS(SELECT 1 FROM control.policy_activation_occurrence_target o
   WHERE o.configuration_work_id=failed.configuration_work_id OR o.runtime_configuration_generation_id=generation.runtime_configuration_generation_id)
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission a
   WHERE a.runtime_target_id=target AND (a.binding->''source''->>''original_work_id''=failed.configuration_work_id::text
    OR a.binding->''source''->>''runtime_configuration_generation_id''=generation.runtime_configuration_generation_id::text))
 THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''PC-DATA-6007'';
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.begin_platform_scope_target_withdrawal(uuid,uuid,text,text,bigint)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; principal uuid; identity record; current_target control.runtime_target;
 intent control.platform_scope_replacement; queued control.platform_scope_target_withdrawal;
 original control.configuration_work; observation control.runtime_activation_observation;
 input control.runtime_configuration_input; head control.runtime_target_disposition_admission;
 delivery control.runtime_target_disposition_delivery; original_inputs uuid[]; material jsonb; digest text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner(); PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1''
   OR target IS NULL OR replacement IS NULL OR coalesce(worker,'''')='''' OR wanted_previous IS NULL OR wanted_previous<0
   OR current_setting(''transaction_isolation'')<>''read committed''
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,certificate);
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 SELECT * INTO STRICT intent FROM control.platform_scope_replacement r WHERE r.replacement_id=replacement
   AND r.participant_id=pid AND r.privacy_domain_id=privacy AND r.state=''WITHDRAWING'' AND r.row_version=1;
 PERFORM 1 FROM control.platform_context p WHERE p.platform_context_id=intent.platform_context_id
  AND p.owner_participant_id=pid AND p.state=''ACTIVE'' AND p.authority_epoch=intent.predecessor_epoch
  AND p.row_version=intent.expected_root_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 SELECT * INTO STRICT queued FROM control.platform_scope_target_withdrawal q
  WHERE q.replacement_id=replacement AND q.participant_id=pid AND q.privacy_domain_id=privacy AND q.runtime_target_id=target;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(''module-admission:''||pid::text||'':''||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended(''openpc-policy-generations:''||pid::text||'':''||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
 THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.runtime_target_id=target FOR SHARE;
 IF current_target.active_generation_digest IS DISTINCT FROM queued.source->>''capsuleDigest''
  OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
    AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.state IN(''PENDING'',''LEASED'',''RECONCILING''))
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF FOUND AND head.binding->>''action''=''Withdraw'' AND head.binding->''cause''=jsonb_build_object(''kind'',''Dependency'',
   ''owner'',''Platform'',''resource_id'',intent.replacement_id::text,''operation_id'',intent.prepare_operation_id::text,''revision'',1)
 THEN
