  ''originalReceiptDigest'',proof->''originalReceiptDigest'',''originalTokenDigest'',proof->''originalTokenDigest'') || CASE WHEN proof->>''sourceMode''=''FACT_BOUND''
   THEN jsonb_build_object(''factCustody'',proof->''factCustody'') ELSE ''{}''::jsonb END)
  OR jsonb_typeof(proof->''targetId'') IS DISTINCT FROM ''string''
  OR jsonb_typeof(proof->''workloadId'') IS DISTINCT FROM ''string''
  OR coalesce(proof->>''workloadId'','''') !~ ''^urn:openpc:workload:[A-Za-z0-9:._-]{1,140}$''
  OR jsonb_typeof(proof->''capsuleValidUntilNs'') IS DISTINCT FROM ''string''
  OR coalesce(proof->>''capsuleValidUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
  OR (proof->>''capsuleValidUntilNs'')::numeric>18446744073709551615
  OR (proof->>''capsuleValidUntilNs'')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR EXISTS(SELECT 1 FROM (VALUES(''withdrawalDigest''),(''capsuleDigest''),(''policyGenerationDigest''),
    (''identityManifestDigest''),(''originalReceiptDigest''),(''originalTokenDigest'')) f(name)
    WHERE jsonb_typeof(proof->f.name) IS DISTINCT FROM ''string'' OR coalesce(proof->>f.name,'''') !~ ''^[0-9a-f]{64}$'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-RESTORE-PROOF''; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id(); target:=(proof->>''targetId'')::uuid;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
 THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF head.binding->>''action''<>''Withdraw'' OR head.binding->''cause''->>''kind''<>''Activation''
  OR head.binding->''source''->>''capsule_digest'' IS DISTINCT FROM proof->>''capsuleDigest''
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-RESTORE-HEAD''; END IF;
 SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
  WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
   AND d.revision=head.revision AND d.delivery_digest=''sha256:''||(proof->>''withdrawalDigest'');
 IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.delivery_digest=delivery.delivery_digest AND a.claims->>''installed_state''=''NewUseDenied'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACK-PENDING''; END IF;
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,
  ''sha256:''||(head.binding->''target''->>''certificate_digest''));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 IF head.binding->''target'' IS DISTINCT FROM jsonb_build_object(''participant_id'',pid::text,''privacy_domain_id'',privacy::text,
  ''target_id'',target::text,''credential_id'',identity.credential_id::text,''principal_id'',principal::text,
  ''credential_epoch'',identity.credential_epoch,''principal_epoch'',identity.principal_epoch,
  ''certificate_digest'',head.binding->''target''->>''certificate_digest'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-IDENTITY''; END IF;
 SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(head.binding->''cause''->>''work_id'')::uuid AND w.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(head.binding->''source''->>''original_work_id'')::uuid AND w.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE;
 IF cause.state<>''FAILED'' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
  OR cause.work_kind<>''RUNTIME_ACTIVATION'' OR cause.completed_at IS NULL
  OR cause.operation_id::text IS DISTINCT FROM head.binding->''cause''->>''operation_id''
  OR head.binding->''cause''->''execution_attempt_id'' IS DISTINCT FROM ''null''::jsonb
  OR original.state<>''COMPLETED'' OR original.work_kind<>''RUNTIME_ACTIVATION''
  OR original.policy_generation_digest IS DISTINCT FROM ''sha256:''||(proof->>''policyGenerationDigest'')
  OR original.result_receipt->>''activationReceiptCoseHex'' IS NULL
  OR encode(sha256(decode(original.result_receipt->>''activationReceiptCoseHex'',''hex'')),''hex'') IS DISTINCT FROM proof->>''originalReceiptDigest''
  OR current_target.active_generation_digest IS DISTINCT FROM ''sha256:''||(proof->>''capsuleDigest'')
  OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest OR current_target.state<>''FAILED''
  OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.state IN (''PENDING'',''LEASED'',''RECONCILING''))
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-RESTORE-CAUSE''; END IF;
 PERFORM openpc.lock_runtime_target_restore_sources(target,head.binding->''source'',proof);
 material:=head.binding||jsonb_build_object(''action'',''Restore'',''revision'',head.revision+1,
  ''previous_revision'',head.revision,''previous_delivery_digest'',substring(delivery.delivery_digest from 8));
 digest:=''sha256:''||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object(''binding'',material,''restorationProof'',proof)),''UTF8'')),''hex'');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,restoration_proof,admission_digest)
 VALUES(pid,privacy,target,head.revision+1,material,proof,digest);
 RETURN QUERY SELECT material,digest;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.lock_runtime_target_restore_sources(uuid,jsonb,jsonb)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
BEGIN
 PERFORM openpc.lock_runtime_target_current_sources(target,expected_source,proof,''RESTORE'');
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.guard_runtime_target_disposition_immutable()')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=false
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
   AND p.prosrc='
BEGIN
 RAISE EXCEPTION ''TARGET-DISPOSITION-IMMUTABLE'';
END ')
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['runtime_target_disposition_admission','runtime_target_disposition_delivery','runtime_target_disposition_acknowledgement']) table_name(name)
  WHERE NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.oid=c.relowner
   WHERE c.oid=to_regclass('control.'||table_name.name) AND c.relkind='r' AND NOT c.relispartition
    AND c.relrowsecurity AND c.relforcerowsecurity AND r.rolname='openpc_control_owner'
    AND NOT EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid))
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['openpc_control_runtime','openpc_control_worker','openpc_control_reader']) role(name)
   WHERE has_table_privilege(role.name,'control.'||table_name.name,'INSERT,UPDATE,DELETE,TRUNCATE')
    OR has_any_column_privilege(role.name,'control.'||table_name.name,'INSERT,UPDATE'))
  OR EXISTS(SELECT 1 FROM pg_class c,aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
   WHERE c.oid=to_regclass('control.'||table_name.name) AND a.grantee=0)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass('control.'||table_name.name)
   AND t.tgname='artifact_lifecycle_fence' AND t.tgtype=62 AND t.tgenabled='O' AND NOT t.tgisinternal
   AND t.tgfoid='openpc.guard_runtime_artifact_lifecycle_fence()'::regprocedure
   AND t.tgnargs=0 AND t.tgqual IS NULL AND NOT t.tgdeferrable)
  OR EXISTS(SELECT 1 FROM (VALUES('runtime_target_disposition_immutable',27),('runtime_target_disposition_truncate',34)) required(name,kind)
   WHERE NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass('control.'||table_name.name)
    AND t.tgname=required.name AND t.tgtype=required.kind AND t.tgenabled='O' AND NOT t.tgisinternal
    AND t.tgfoid='openpc.guard_runtime_target_disposition_immutable()'::regprocedure
    AND t.tgnargs=0 AND t.tgqual IS NULL AND NOT t.tgdeferrable)))
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['openpc_control_runtime','openpc_control_worker','openpc_control_reader']) role(name)
  WHERE has_table_privilege(role.name,'control.runtime_target_disposition_key','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
   OR has_any_column_privilege(role.name,'control.runtime_target_disposition_key','SELECT,INSERT,UPDATE'))
 OR NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.oid=c.relowner
  WHERE c.oid='control.runtime_target_disposition_key'::regclass AND c.relkind='r' AND NOT c.relispartition
   AND r.rolname='openpc_control_owner' AND NOT EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid)
   AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee=0))
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-OWNER-UNAVAILABLE'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.assert_workload_renewal_policy_receipt(receipt control.audit_occurrence)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE candidate control.mutation_candidate%ROWTYPE; policy control.workload_renewal_policy%ROWTYPE;
 prior control.workload_renewal_policy%ROWTYPE; projection jsonb; command text;
BEGIN
 IF receipt.aggregate_type<>'workload-renewal-policy' OR receipt.action_intent_id<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR receipt.catalog_operation_id NOT IN ('ID-OP-WORKLOAD-RENEWAL-POLICY-CREATE','ID-OP-WORKLOAD-RENEWAL-POLICY-REVISE',
   'ID-OP-WORKLOAD-RENEWAL-POLICY-SUSPEND','ID-OP-WORKLOAD-RENEWAL-POLICY-REVOKE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 candidate:=openpc.check_governed_configuration_receipt(receipt);
 command:=replace(receipt.catalog_operation_id,'ID-OP-WORKLOAD-RENEWAL-POLICY-','');
 SELECT * INTO STRICT policy FROM control.workload_renewal_policy p WHERE p.participant_id=receipt.participant_id
  AND p.privacy_domain_id=receipt.privacy_domain_id AND p.policy_id=receipt.aggregate_id
  AND p.revision=receipt.after_revision AND p.governance_operation_id=receipt.operation_id;
 IF receipt.after_existence<>1 OR receipt.before_revision<>candidate.expected_revision
  OR receipt.after_revision<>candidate.expected_revision+1
  OR candidate.resource_type<>'participant' OR candidate.operation_class<>'UPDATE'
  OR candidate.candidate_document->>'expectedRevision' IS DISTINCT FROM candidate.expected_revision::text
  OR jsonb_typeof(candidate.candidate_document->'requestId') IS DISTINCT FROM 'string'
  OR coalesce(candidate.candidate_document->>'requestId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR jsonb_typeof(candidate.candidate_document->'reason') IS DISTINCT FROM 'string'
  OR length(candidate.candidate_document->>'reason')<1
  OR length(candidate.candidate_document->>'reason')+(SELECT count(*) FROM regexp_split_to_table(candidate.candidate_document->>'reason','') scalar(character) WHERE ascii(character)>65535)>1024
  OR candidate.candidate_document->>'reason' IS DISTINCT FROM normalize(candidate.candidate_document->>'reason',NFC)
  OR NOT EXISTS(SELECT 1 FROM control.workload_renewal_policy_head h WHERE h.participant_id=policy.participant_id
   AND h.privacy_domain_id=policy.privacy_domain_id AND h.policy_id=policy.policy_id AND h.current_revision=policy.revision
   AND h.state=policy.state AND h.principal_id=policy.principal_id AND h.workload_id=policy.workload_id AND h.row_version=policy.revision)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-CURRENT-REVISION'; END IF;
 IF command IN ('CREATE','REVISE') THEN
  IF candidate.candidate_document IS DISTINCT FROM jsonb_build_object('requestId',candidate.candidate_document->'requestId',
   'expectedRevision',candidate.expected_revision::text,'definition',policy.definition,'reason',candidate.candidate_document->'reason')
   OR policy.state<>'ACTIVE' THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-DEFINITION'; END IF;
 ELSE
  IF candidate.candidate_document IS DISTINCT FROM jsonb_build_object('requestId',candidate.candidate_document->'requestId',
   'expectedRevision',candidate.expected_revision::text,'reason',candidate.candidate_document->'reason')
   OR policy.state<>(CASE command WHEN 'SUSPEND' THEN 'SUSPENDED' ELSE 'REVOKED' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-STOP'; END IF;
 END IF;
 IF command='CREATE' THEN
  IF receipt.before_existence<>0 OR receipt.before_revision<>0 OR policy.revision<>1 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  projection:='{}'::jsonb;
 ELSE
  SELECT * INTO STRICT prior FROM control.workload_renewal_policy p WHERE p.participant_id=policy.participant_id
   AND p.privacy_domain_id=policy.privacy_domain_id AND p.policy_id=policy.policy_id AND p.revision=candidate.expected_revision;
  IF receipt.before_existence<>1 OR prior.state='REVOKED'
   OR (prior.principal_id,prior.workload_id) IS DISTINCT FROM (policy.principal_id,policy.workload_id)
   OR (command='REVISE' AND prior.digest=policy.digest)
   OR (command IN ('SUSPEND','REVOKE') AND prior.definition IS DISTINCT FROM policy.definition)
   OR (command='SUSPEND' AND prior.state<>'ACTIVE') THEN RAISE EXCEPTION 'PC-DATA-6007-RENEWAL-TRANSITION'; END IF;
  projection:=openpc.workload_renewal_policy_projection(prior);
 END IF;
 IF openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM projection
  OR openpc.business_cbor(receipt.after_state_preimage)->8 IS DISTINCT FROM openpc.workload_renewal_policy_projection(policy)
 THEN RAISE EXCEPTION 'DATA-6021-RENEWAL-TYPED-STATE'; END IF;
 PERFORM openpc.check_workload_renewal_policy_ancestors(policy,receipt);
END $function$

CREATE OR REPLACE FUNCTION openpc.begin_fleet_fact_delivery(material bytea, nonce bytea, mac bytea, wanted_profile text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE request jsonb; e jsonb; p uuid; v uuid; event uuid; candidate uuid; generation uuid; lease uuid; kind text;
 n numeric; head numeric; now_ms numeric; until_ms numeric; original bytea;
 profile control.fact_consumer_profile; d control.fleet_fact_delivery;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_DELIVERY_BEGIN_V1');
 e:=request->'event'; lease:=(request->>'leaseId')::uuid;
 p:=(e->>'participantId')::uuid; v:=(e->>'privacyDomainId')::uuid; event:=(e->>'eventId')::uuid;
 candidate:=(e->>'candidateId')::uuid; generation:=(e->>'generationId')::uuid;
 kind:=e->>'factType'; n:=(e->>'sequence')::numeric;
 IF request IS DISTINCT FROM jsonb_build_object('event',e,'leaseId',lease::text)
  OR p IS DISTINCT FROM openpc.current_participant_id() OR v IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR e IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',v::text,'eventId',event::text,
    'candidateId',candidate::text,'generationId',generation::text,'factType',kind,'sequence',n::text,
    'consumerId','LS-FLEET-CONTROL','envelope',e->'envelope','envelopeDigest',e->>'envelopeDigest','dataDigest',e->>'dataDigest')
  OR lease IS NULL OR substring(lease::text from 15 for 1)<>'7'
  OR kind NOT IN ('CONTRACT_STATE_CALL','RELATIONSHIP','EXTERNAL_DECISION') OR n<1 OR n>9223372036854775807
  OR e->>'envelopeDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e->'envelope'),'UTF8')),'hex')
  OR coalesce(e->>'dataDigest','')!~'^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF profile.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type) VALUES(p,v,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor WHERE participant_id=p AND privacy_domain_id=v AND fact_type=kind FOR UPDATE;
 IF n<=head THEN
  IF EXISTS(SELECT 1 FROM control.fleet_fact_admission_inbox i WHERE i.participant_id=p AND i.privacy_domain_id=v
    AND i.event_id=event AND i.candidate_id=candidate AND i.generation_id=generation AND i.fact_type=kind AND i.sequence=n
    AND convert_from(i.material,'UTF8')::jsonb->'envelope'=e->'envelope')
  THEN RETURN jsonb_build_object('state','COMMITTED'); END IF;
  RAISE EXCEPTION 'PC-DATA-6007';
 END IF;
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 original:=convert_to(openpc.signing_canonical_json(e),'UTF8');
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 INSERT INTO control.fleet_fact_delivery(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,fact_type,sequence,
  material,material_digest,initial_profile_digest,maximum_attempts,initial_backoff_ms,maximum_backoff_ms,next_attempt_ms)
 VALUES(p,v,event,candidate,generation,kind,n,original,sha256(original),wanted_profile,
  (profile.claims->>'maximumAttempts')::integer,(profile.claims->>'initialBackoffMs')::integer,
  (profile.claims->>'maximumBackoffMs')::integer,now_ms) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=v AND event_id=event FOR UPDATE;
 IF d.material IS DISTINCT FROM original THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
 IF d.state='LEASED' THEN
  IF d.lease_until_ms<=now_ms THEN
   PERFORM openpc.close_fleet_delivery_lease(event,d.lease_id,'LEASE_EXPIRED','PC-DATA-6005');
   SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
  ELSIF d.lease_id=lease THEN
   RETURN jsonb_build_object('state','LEASED','leaseId',lease::text,'leaseUntilMs',d.lease_until_ms::text);
  ELSE RETURN jsonb_build_object('state','BUSY'); END IF;
 END IF;
 IF d.state='WAITING' AND (profile.claims->>'maximumAttempts')::integer<d.maximum_attempts THEN
  UPDATE control.fleet_fact_delivery SET maximum_attempts=greatest(d.failed_attempts,(profile.claims->>'maximumAttempts')::integer),
   state=CASE WHEN d.failed_attempts>=(profile.claims->>'maximumAttempts')::integer THEN 'EXHAUSTED' ELSE 'WAITING' END
   WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
  SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
 END IF;
 IF d.state IN ('EXHAUSTED','QUARANTINED','COMMITTED') THEN RETURN jsonb_build_object('state',d.state); END IF;
 IF d.next_attempt_ms>now_ms THEN RETURN jsonb_build_object('state','WAITING','nextAttemptMs',d.next_attempt_ms::text); END IF;
 until_ms:=least(now_ms+30000,(profile.claims->>'validUntilMs')::numeric);
 INSERT INTO control.fleet_fact_delivery_attempt(participant_id,privacy_domain_id,event_id,lease_generation,lease_id,profile_digest,started_at_ms,lease_until_ms)
 VALUES(p,v,event,d.lease_generation+1,lease,wanted_profile,now_ms,until_ms);
 UPDATE control.fleet_fact_delivery SET state='LEASED',lease_id=lease,lease_until_ms=until_ms,lease_generation=d.lease_generation+1
 WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
 RETURN jsonb_build_object('state','LEASED','leaseId',lease::text,'leaseUntilMs',until_ms::text);
END $function$

CREATE OR REPLACE FUNCTION openpc.begin_platform_scope_target_withdrawal(target uuid, replacement uuid, worker text, certificate text, wanted_previous bigint)
 RETURNS TABLE(binding jsonb, admission_digest text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE pid uuid; privacy uuid; principal uuid; identity record; current_target control.runtime_target;
 intent control.platform_scope_replacement; queued control.platform_scope_target_withdrawal;
 original control.configuration_work; observation control.runtime_activation_observation;
 input control.runtime_configuration_input; head control.runtime_target_disposition_admission;
 delivery control.runtime_target_disposition_delivery; original_inputs uuid[]; material jsonb; digest text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner(); PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
   OR target IS NULL OR replacement IS NULL OR coalesce(worker,'')='' OR wanted_previous IS NULL OR wanted_previous<0
   OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,certificate);
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 SELECT * INTO STRICT intent FROM control.platform_scope_replacement r WHERE r.replacement_id=replacement
   AND r.participant_id=pid AND r.privacy_domain_id=privacy AND r.state='WITHDRAWING' AND r.row_version=1;
 PERFORM 1 FROM control.platform_context p WHERE p.platform_context_id=intent.platform_context_id
  AND p.owner_participant_id=pid AND p.state='ACTIVE' AND p.authority_epoch=intent.predecessor_epoch
  AND p.row_version=intent.expected_root_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAUSE-UNAVAILABLE'; END IF;
 SELECT * INTO STRICT queued FROM control.platform_scope_target_withdrawal q
  WHERE q.replacement_id=replacement AND q.participant_id=pid AND q.privacy_domain_id=privacy AND q.runtime_target_id=target;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.runtime_target_id=target FOR SHARE;
 IF current_target.active_generation_digest IS DISTINCT FROM queued.source->>'capsuleDigest'
  OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
    AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN('PENDING','LEASED','RECONCILING'))
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAUSE-UNAVAILABLE'; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF FOUND AND head.binding->>'action'='Withdraw' AND head.binding->'cause'=jsonb_build_object('kind','Dependency',
   'owner','Platform','resource_id',intent.replacement_id::text,'operation_id',intent.prepare_operation_id::text,'revision',1)
 THEN
  IF wanted_previous<>head.revision-1 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
  RETURN QUERY SELECT head.binding,head.admission_digest; RETURN;
 END IF;
 IF coalesce(head.revision,0)<>wanted_previous THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
 IF head.revision IS NOT NULL THEN
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d WHERE d.participant_id=pid
   AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=head.revision;
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a WHERE a.participant_id=pid
    AND a.privacy_domain_id=privacy AND a.runtime_target_id=target AND a.delivery_digest=delivery.delivery_digest)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-PENDING'; END IF;
 END IF;
 SELECT * INTO STRICT observation FROM control.runtime_activation_observation o WHERE o.participant_id=pid
  AND o.privacy_domain_id=privacy AND o.runtime_target_id=target AND o.capsule_digest=current_target.active_generation_digest
  AND o.configuration_work_id=(queued.source->>'originalWorkId')::uuid
  AND o.execution_attempt_id=(queued.source->>'originalAttemptId')::uuid
  AND o.activation_receipt_digest=queued.source->>'activationReceiptDigest';
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=observation.configuration_work_id AND w.runtime_target_id=target
  AND w.operation_id=observation.operation_id AND w.execution_attempt_id=observation.execution_attempt_id
  AND w.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
  AND w.generation_digest=observation.generation_digest AND w.xds_version_digest=observation.xds_version_digest
  AND w.state='COMPLETED' AND w.work_kind='RUNTIME_ACTIVATION' AND w.execution_started_at IS NOT NULL
  AND w.result_receipt_digest=observation.activation_receipt_digest FOR SHARE;
 SELECT array_agg(i.runtime_configuration_input_id) INTO original_inputs FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy AND i.configuration_digest=decode(substring(original.configuration_digest from 8),'hex');
 IF coalesce(cardinality(original_inputs),0)<>1 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-INPUT-CARDINALITY'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
  AND i.runtime_configuration_input_id=original_inputs[1] FOR SHARE;
 material:=jsonb_build_object('version',1,'action','Withdraw','revision',wanted_previous+1,
  'previous_revision',wanted_previous,'previous_delivery_digest',substring(delivery.delivery_digest from 8),
  'target',jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,'target_id',target::text,
    'credential_id',identity.credential_id::text,'principal_id',principal::text,'credential_epoch',identity.credential_epoch,
    'principal_epoch',identity.principal_epoch,'certificate_digest',substring(certificate from 8)),
  'source',jsonb_build_object('runtime_configuration_input_id',input.runtime_configuration_input_id::text,
    'configuration_digest',encode(input.configuration_digest,'hex'),'module_installation_id',input.module_installation_id::text,
    'module_configuration_generation_id',input.module_configuration_generation_id::text,
    'runtime_configuration_generation_id',original.runtime_configuration_generation_id::text,
    'capsule_digest',substring(observation.capsule_digest from 8),'xds_version_digest',substring(observation.xds_version_digest from 8),
    'predecessor_capsule_digest',substring(original.predecessor_digest from 8),
    'original_work_id',original.configuration_work_id::text,'original_operation_id',original.operation_id::text,
    'original_execution_attempt_id',original.execution_attempt_id::text),
  'cause',jsonb_build_object('kind','Dependency','owner','Platform','resource_id',intent.replacement_id::text,
    'operation_id',intent.prepare_operation_id::text,'revision',1));
 IF head.revision IS NOT NULL AND head.binding->'target' IS DISTINCT FROM material->'target' THEN
  IF openpc.runtime_discovery_credential_predecessor(target,certificate,material->'source') IS DISTINCT FROM head.binding->'target'
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CREDENTIAL-SUCCESSOR'; END IF;
 END IF;
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(material),'UTF8')),'hex');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,admission_digest)
 VALUES(pid,privacy,target,wanted_previous+1,material,digest);
 RETURN QUERY SELECT material,digest;
END $function$

CREATE OR REPLACE FUNCTION openpc.begin_runtime_target_activation_confirmation(proof_wire bytea, nonce bytea, mac bytea)
 RETURNS TABLE(binding jsonb, admission_digest text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0; pid uuid; privacy uuid; target uuid;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 original control.configuration_work; input control.runtime_configuration_input;
 current_target control.runtime_target; source jsonb; identity jsonb; authority record; principal uuid;
 material jsonb; digest text; next_revision bigint; previous_digest text; occurrence uuid;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR proof_wire IS NULL OR octet_length(proof_wire) NOT BETWEEN 1 AND 8192
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_ACTIVATION_ADMISSION_V1','UTF8')||sha256(proof_wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 proof:=convert_from(proof_wire,'UTF8')::jsonb;
 IF proof IS DISTINCT FROM (jsonb_build_object('version',1,'transactionId',pg_current_xact_id()::text,
  'targetId',proof->'targetId','source',proof->'source','target',proof->'target',
  'capsuleDigest',proof->'capsuleDigest','capsuleValidUntilNs',proof->'capsuleValidUntilNs',
  'policyGenerationDigest',proof->'policyGenerationDigest','workloadId',proof->'workloadId',
  'identityManifestDigest',proof->'identityManifestDigest','sourceMode',proof->'sourceMode',
  'originalReceiptDigest',proof->'originalReceiptDigest','originalTokenDigest',proof->'originalTokenDigest',
  'occurrenceId',proof->'occurrenceId') || CASE WHEN proof->>'sourceMode'='FACT_BOUND'
   THEN jsonb_build_object('factCustody',proof->'factCustody') ELSE '{}'::jsonb END)
  OR jsonb_typeof(proof->'source') IS DISTINCT FROM 'object'
  OR jsonb_typeof(proof->'target') IS DISTINCT FROM 'object'
  OR coalesce(proof->>'workloadId','') !~ '^urn:openpc:workload:[A-Za-z0-9:._-]{1,140}$'
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR EXISTS(SELECT 1 FROM (VALUES('capsuleDigest'),('policyGenerationDigest'),('identityManifestDigest'),
   ('originalReceiptDigest'),('originalTokenDigest')) f(name)
   WHERE jsonb_typeof(proof->f.name) IS DISTINCT FROM 'string' OR coalesce(proof->>f.name,'') !~ '^[0-9a-f]{64}$')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-PROOF'; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id(); target:=(proof->>'targetId')::uuid;
 source:=proof->'source'; identity:=proof->'target';
 PERFORM openpc.lock_runtime_target_current_sources(target,source,proof,'CONFIRM');
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,'sha256:'||(identity->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF identity IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',authority.credential_id::text,'principal_id',principal::text,
  'credential_epoch',authority.credential_epoch,'principal_epoch',authority.principal_epoch,
  'certificate_digest',identity->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(source->>'original_work_id')::uuid AND w.runtime_target_id=target FOR SHARE NOWAIT;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
  AND i.runtime_configuration_input_id=(source->>'runtime_configuration_input_id')::uuid FOR SHARE NOWAIT;
 IF source IS DISTINCT FROM jsonb_build_object('runtime_configuration_input_id',input.runtime_configuration_input_id::text,
  'configuration_digest',encode(input.configuration_digest,'hex'),'module_installation_id',input.module_installation_id::text,
  'module_configuration_generation_id',input.module_configuration_generation_id::text,
  'runtime_configuration_generation_id',original.runtime_configuration_generation_id::text,
  'capsule_digest',proof->>'capsuleDigest','xds_version_digest',substring(original.xds_version_digest from 8),
  'predecessor_capsule_digest',substring(original.predecessor_digest from 8),'original_work_id',original.configuration_work_id::text,
  'original_operation_id',original.operation_id::text,'original_execution_attempt_id',original.execution_attempt_id::text)
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-SOURCE'; END IF;
 SELECT ot.activation_occurrence_id INTO occurrence FROM control.policy_activation_occurrence_target ot
  WHERE ot.participant_id=pid AND ot.privacy_domain_id=privacy AND ot.configuration_work_id=original.configuration_work_id;
 IF proof->>'occurrenceId' IS DISTINCT FROM coalesce(occurrence,original.configuration_work_id)::text
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-OCCURRENCE'; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF NOT coalesce(((original.state='COMPLETED' AND current_target.active_generation_digest='sha256:'||(proof->>'capsuleDigest'))
  OR (original.state IN ('LEASED','RECONCILING') AND openpc.runtime_work_predecessor_matches(original.configuration_work_id)
   AND current_target.desired_generation_digest=original.generation_digest)),false)
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-TARGET'; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF NOT FOUND THEN
  IF original.predecessor_digest IS NOT NULL THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-PREDECESSOR'; END IF;
  next_revision:=1; previous_digest:=NULL;
 ELSE
  IF head.binding->>'action' IS DISTINCT FROM 'Withdraw'
   OR (head.binding->'cause'->>'kind' IN ('Activation','UnsignedWithdrawalRecovery')) IS NOT TRUE
   OR head.binding->'cause'->>'work_id' IS DISTINCT FROM original.configuration_work_id::text
   OR head.binding->'cause'->>'operation_id' IS DISTINCT FROM original.operation_id::text
   OR (head.binding->'cause'->>'execution_attempt_id' IS NOT NULL
    AND head.binding->'cause'->>'execution_attempt_id' IS DISTINCT FROM original.execution_attempt_id::text)
   OR original.predecessor_digest IS DISTINCT FROM 'sha256:'||(head.binding->'source'->>'capsule_digest')
   OR head.binding->'source'->>'capsule_digest' IS NOT DISTINCT FROM proof->>'capsuleDigest'
   OR head.binding->'source'->>'original_work_id' IS NOT DISTINCT FROM original.configuration_work_id::text
   OR head.binding->'target' IS DISTINCT FROM identity
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-PREDECESSOR'; END IF;
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=head.revision;
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest AND a.claims->>'installed_state'='NewUseDenied')
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-PENDING'; END IF;
  next_revision:=head.revision+1; previous_digest:=substring(delivery.delivery_digest from 8);
 END IF;
 material:=jsonb_build_object('version',1,'target',identity,'source',source,'action','ConfirmActivation',
  'cause',jsonb_build_object('kind','Activation','work_id',original.configuration_work_id::text,
   'operation_id',original.operation_id::text,'execution_attempt_id',original.execution_attempt_id::text),
  'revision',next_revision,'previous_revision',next_revision-1,'previous_delivery_digest',previous_digest);
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('binding',material,'activationProof',proof)),'UTF8')),'hex');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,activation_proof,admission_digest)
 VALUES(pid,privacy,target,next_revision,material,proof,digest);
 RETURN QUERY SELECT material,digest;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $function$

CREATE OR REPLACE FUNCTION openpc.begin_runtime_target_unstarted_restore(proof_wire bytea, nonce bytea, mac bytea)
 RETURNS TABLE(binding jsonb, admission_digest text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0; pid uuid; privacy uuid; target uuid;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 cause control.configuration_work; original control.configuration_work; current_target control.runtime_target;
 material jsonb; digest text; identity record; principal uuid;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR proof_wire IS NULL OR octet_length(proof_wire) NOT BETWEEN 1 AND 8192
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_RESTORE_ADMISSION_V1','UTF8')||sha256(proof_wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 proof:=convert_from(proof_wire,'UTF8')::jsonb;
 IF proof IS DISTINCT FROM (jsonb_build_object('version',1,'transactionId',pg_current_xact_id()::text,
  'targetId',proof->'targetId','withdrawalDigest',proof->'withdrawalDigest',
  'capsuleDigest',proof->'capsuleDigest','capsuleValidUntilNs',proof->'capsuleValidUntilNs',
  'policyGenerationDigest',proof->'policyGenerationDigest','workloadId',proof->'workloadId',
  'identityManifestDigest',proof->'identityManifestDigest','sourceMode',proof->'sourceMode',
  'originalReceiptDigest',proof->'originalReceiptDigest','originalTokenDigest',proof->'originalTokenDigest') || CASE WHEN proof->>'sourceMode'='FACT_BOUND'
   THEN jsonb_build_object('factCustody',proof->'factCustody') ELSE '{}'::jsonb END)
  OR jsonb_typeof(proof->'targetId') IS DISTINCT FROM 'string'
  OR jsonb_typeof(proof->'workloadId') IS DISTINCT FROM 'string'
  OR coalesce(proof->>'workloadId','') !~ '^urn:openpc:workload:[A-Za-z0-9:._-]{1,140}$'
  OR jsonb_typeof(proof->'capsuleValidUntilNs') IS DISTINCT FROM 'string'
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR EXISTS(SELECT 1 FROM (VALUES('withdrawalDigest'),('capsuleDigest'),('policyGenerationDigest'),
    ('identityManifestDigest'),('originalReceiptDigest'),('originalTokenDigest')) f(name)
    WHERE jsonb_typeof(proof->f.name) IS DISTINCT FROM 'string' OR coalesce(proof->>f.name,'') !~ '^[0-9a-f]{64}$')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-PROOF'; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id(); target:=(proof->>'targetId')::uuid;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF head.binding->>'action'<>'Withdraw' OR head.binding->'cause'->>'kind'<>'Activation'
  OR head.binding->'source'->>'capsule_digest' IS DISTINCT FROM proof->>'capsuleDigest'
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-HEAD'; END IF;
 SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
  WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
   AND d.revision=head.revision AND d.delivery_digest='sha256:'||(proof->>'withdrawalDigest');
 IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.delivery_digest=delivery.delivery_digest AND a.claims->>'installed_state'='NewUseDenied')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-PENDING'; END IF;
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,
  'sha256:'||(head.binding->'target'->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 IF head.binding->'target' IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',identity.credential_id::text,'principal_id',principal::text,
  'credential_epoch',identity.credential_epoch,'principal_epoch',identity.principal_epoch,
  'certificate_digest',head.binding->'target'->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(head.binding->'cause'->>'work_id')::uuid AND w.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(head.binding->'source'->>'original_work_id')::uuid AND w.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE;
 IF cause.state<>'FAILED' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
  OR cause.work_kind<>'RUNTIME_ACTIVATION' OR cause.completed_at IS NULL
  OR cause.operation_id::text IS DISTINCT FROM head.binding->'cause'->>'operation_id'
  OR head.binding->'cause'->'execution_attempt_id' IS DISTINCT FROM 'null'::jsonb
  OR original.state<>'COMPLETED' OR original.work_kind<>'RUNTIME_ACTIVATION'
  OR original.policy_generation_digest IS DISTINCT FROM 'sha256:'||(proof->>'policyGenerationDigest')
  OR original.result_receipt->>'activationReceiptCoseHex' IS NULL
  OR encode(sha256(decode(original.result_receipt->>'activationReceiptCoseHex','hex')),'hex') IS DISTINCT FROM proof->>'originalReceiptDigest'
  OR current_target.active_generation_digest IS DISTINCT FROM 'sha256:'||(proof->>'capsuleDigest')
  OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest OR current_target.state<>'FAILED'
  OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN ('PENDING','LEASED','RECONCILING'))
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-CAUSE'; END IF;
 PERFORM openpc.lock_runtime_target_restore_sources(target,head.binding->'source',proof);
 material:=head.binding||jsonb_build_object('action','Restore','revision',head.revision+1,
  'previous_revision',head.revision,'previous_delivery_digest',substring(delivery.delivery_digest from 8));
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('binding',material,'restorationProof',proof)),'UTF8')),'hex');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,restoration_proof,admission_digest)
 VALUES(pid,privacy,target,head.revision+1,material,proof,digest);
 RETURN QUERY SELECT material,digest;
END $function$

CREATE OR REPLACE FUNCTION openpc.business_cbor(data bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE decoded jsonb;
BEGIN
  IF octet_length(data)>65536 THEN RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR'; END IF;
  decoded:=openpc.business_cbor_item(data,0,0);
  IF (decoded->>'next')::integer<>octet_length(data) THEN RAISE EXCEPTION 'DATA-6021-TRAILING-BUSINESS-CBOR'; END IF;
  RETURN decoded->'value';
END $function$

CREATE OR REPLACE FUNCTION openpc.business_cbor_item(data bytea, byte_offset integer, depth integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  initial integer; major integer; additional integer; width integer; cursor integer;
  argument numeric := 0; value jsonb; child jsonb; key_item jsonb; key_number numeric;
  previous_key numeric := -1; i integer; bytes bytea; decoded text;
BEGIN
  IF octet_length(data)>66560 OR byte_offset<0 OR byte_offset>=octet_length(data) OR depth>8 THEN
    RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR';
  END IF;
  initial:=get_byte(data,byte_offset); major:=initial/32; additional:=initial%32; cursor:=byte_offset+1;
  IF additional<24 THEN argument:=additional;
  ELSE
    width:=CASE additional WHEN 24 THEN 1 WHEN 25 THEN 2 WHEN 26 THEN 4 WHEN 27 THEN 8 ELSE 0 END;
    IF width=0 OR cursor+width>octet_length(data) THEN RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR'; END IF;
    FOR i IN 0..width-1 LOOP argument:=argument*256+get_byte(data,cursor+i); END LOOP;
    cursor:=cursor+width;
    IF (width=1 AND argument<24) OR (width=2 AND argument<=255) OR
       (width=4 AND argument<=65535) OR (width=8 AND argument<=4294967295) THEN
      RAISE EXCEPTION 'DATA-6021-NONCANONICAL-BUSINESS-CBOR';
    END IF;
  END IF;
  CASE major
    WHEN 0 THEN value:=to_jsonb(argument);
    WHEN 1 THEN value:=to_jsonb(-1-argument);
    WHEN 2,3 THEN
      IF argument>65536 OR cursor+argument>octet_length(data) THEN RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR'; END IF;
      bytes:=substring(data FROM cursor+1 FOR argument::integer); cursor:=cursor+argument::integer;
      IF major=2 THEN value:=jsonb_build_object('bytes',encode(bytes,'hex'));
      ELSE
        decoded:=convert_from(bytes,'UTF8');
        IF normalize(decoded,NFC)<>decoded OR convert_to(decoded,'UTF8')<>bytes THEN
          RAISE EXCEPTION 'DATA-6021-NONCANONICAL-BUSINESS-CBOR';
        END IF;
        value:=to_jsonb(decoded);
      END IF;
    WHEN 4 THEN
      IF argument>256 THEN RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR'; END IF;
      value:='[]'::jsonb;
      FOR i IN 1..argument::integer LOOP
        child:=openpc.business_cbor_item(data,cursor,depth+1);
        value:=value||jsonb_build_array(child->'value'); cursor:=(child->>'next')::integer;
      END LOOP;
    WHEN 5 THEN
      IF argument>256 THEN RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR'; END IF;
      value:='{}'::jsonb;
      FOR i IN 1..argument::integer LOOP
        IF cursor>=octet_length(data) OR get_byte(data,cursor)/32<>0 THEN
          RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR-MAP-KEY';
        END IF;
        key_item:=openpc.business_cbor_item(data,cursor,depth+1); key_number:=(key_item->>'value')::numeric;
        IF key_number<=previous_key OR key_number>4294967295 THEN RAISE EXCEPTION 'DATA-6021-NONCANONICAL-BUSINESS-CBOR-MAP'; END IF;
        previous_key:=key_number; cursor:=(key_item->>'next')::integer;
        child:=openpc.business_cbor_item(data,cursor,depth+1);
        value:=value||jsonb_build_object(key_number::text,child->'value'); cursor:=(child->>'next')::integer;
      END LOOP;
    ELSE RAISE EXCEPTION 'DATA-6021-INVALID-BUSINESS-CBOR-TYPE';
  END CASE;
  RETURN jsonb_build_object('value',value,'next',cursor);
END $function$

CREATE OR REPLACE FUNCTION openpc.business_request_digest(binding text[])
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE preimage bytea:=convert_to('pc.control.configuration-request.v1','UTF8')||decode('00','hex'); value text; bytes bytea;
BEGIN
 IF cardinality(binding)<>10 THEN RAISE EXCEPTION 'DATA-6021-REQUEST-BINDING'; END IF;
 FOREACH value IN ARRAY binding LOOP
  IF value IS NULL OR octet_length(value) NOT BETWEEN 1 AND 256 OR normalize(value,NFC)<>value THEN
    RAISE EXCEPTION 'DATA-6021-REQUEST-BINDING'; END IF;
  bytes:=convert_to(value,'UTF8');preimage:=preimage||int4send(octet_length(bytes))||bytes;
 END LOOP;
 RETURN sha256(preimage);
END $function$

CREATE OR REPLACE FUNCTION openpc.candidate_archive_coverage(pid uuid, privacy uuid, stream text, record_ref text, sinks text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a control.evidence_candidate_archive; object record; checkpoint control.evidence_checkpoint;
 sink text; receipts jsonb; objects jsonb:='[]'; original_count integer; pending jsonb;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR sinks IS NULL OR cardinality(sinks) NOT BETWEEN 1 AND 8 OR array_position(sinks,NULL) IS NOT NULL
  OR cardinality(sinks)<>(SELECT count(DISTINCT value) FROM unnest(sinks) value)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.evidence_candidate_archive WHERE participant_id=pid
  AND privacy_domain_id=privacy AND stream_id=stream AND record_id=record_ref;
 pending:=jsonb_build_object('state','PENDING','authority','NONE','manifestDigest',a.manifest_digest);
 SELECT count(*) INTO original_count FROM control.evidence_candidate_archive_part part
  JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  WHERE part.participant_id=pid AND part.privacy_domain_id=privacy AND part.stream_id=stream AND part.manifest_record_id=record_ref;
 IF original_count<>jsonb_array_length(a.manifest->'chunks')+1 THEN RETURN pending; END IF;
 FOR object IN SELECT DISTINCT s.segment_id,s.object_digest,s.first_sequence,s.through_sequence
  FROM control.evidence_candidate_archive_part part JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE part.participant_id=pid AND part.privacy_domain_id=privacy AND part.stream_id=stream AND part.manifest_record_id=record_ref
  ORDER BY s.first_sequence LOOP
  receipts:='[]';
  FOREACH sink IN ARRAY sinks LOOP
   SELECT * INTO checkpoint FROM control.evidence_checkpoint c WHERE c.participant_id=pid AND c.privacy_domain_id=privacy
    AND c.stream_id=stream AND c.segment_id=object.segment_id AND c.object_digest=object.object_digest
    AND c.through_sequence=object.through_sequence AND c.sink_id=sink;
   IF NOT FOUND THEN RETURN pending; END IF;
   IF checkpoint.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1' THEN
    IF NOT openpc.remote_archive_covers(pid,privacy,stream,object.segment_id,sink) THEN RETURN pending; END IF;
   ELSIF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=pid
     AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=privacy)
     AND openpc.evidence_hold_requires_coverage(h,stream,object.segment_id)
     AND NOT EXISTS(SELECT 1 FROM control.evidence_hold_coverage c WHERE c.participant_id=pid AND c.privacy_domain_id=privacy
       AND c.retention_hold_id=h.retention_hold_id AND c.hold_revision=h.revision AND c.stream_id=stream
       AND c.segment_id=object.segment_id AND c.object_digest=object.object_digest AND c.sink_id=sink))
   THEN RETURN pending; END IF;
   receipts:=receipts||jsonb_build_array(jsonb_build_object('sinkId',sink,'checkpointDigest',checkpoint.checkpoint_digest,'receiptDigest',checkpoint.receipt_digest));
  END LOOP;
  objects:=objects||jsonb_build_array(jsonb_build_object('segmentId',object.segment_id::text,'objectDigest',object.object_digest,
   'firstSequence',object.first_sequence::text,'throughSequence',object.through_sequence::text,'sinkReceipts',receipts));
 END LOOP;
 IF jsonb_array_length(objects)=0 THEN RETURN pending; END IF;
 RETURN jsonb_build_object('state','COMPLETE','authority','NONE','manifestDigest',a.manifest_digest,'segments',objects);
END $function$

CREATE OR REPLACE FUNCTION openpc.candidate_retirement_source_binding(policy_id uuid, selection_wire bytea, record_refs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 rule control.retention_policy; selection jsonb; selected jsonb; ref jsonb; a control.evidence_candidate_archive;
 actual record; archived record; checkpoint record; identity jsonb; sinks jsonb; chosen text[];
 refs jsonb:='[]'; manifest jsonb:='[]'; acknowledgements jsonb:='[]';
 row_index integer:=0; eligible_ms numeric:=0; ack_ms numeric; latest numeric;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF octet_length(selection_wire) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 selection:=convert_from(selection_wire,'UTF8')::jsonb;
 IF selection->>'class' IS DISTINCT FROM 'CANDIDATE_PROJECTION'
  OR jsonb_typeof(selection->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(selection->'rows') NOT BETWEEN 1 AND 256
  OR jsonb_typeof(record_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(record_refs)<>jsonb_array_length(selection->'rows') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT rule FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d
  AND retention_policy_id=policy_id AND data_class='CANDIDATE_PROJECTION' AND deletion_mode='PROJECTION_DELETE' AND active_until IS NULL;
 FOR selected IN SELECT value FROM jsonb_array_elements(selection->'rows') LOOP
  ref:=record_refs->row_index;
  IF ref IS DISTINCT FROM jsonb_build_object('candidateId',selected->>'candidate_id','evidenceId',ref->>'evidenceId')
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT c.evidence_id,c.stream_id,c.record_id,c.sequence,c.receipt_digest,c.occurred_at,
   s.segment_id,s.object_digest,s.first_sequence,s.through_sequence,s.admitted_at INTO STRICT actual
   FROM control.evidence_catalogue c JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_stream h USING(participant_id,privacy_domain_id,stream_id)
   WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.evidence_id=(ref->>'evidenceId')::uuid
    AND c.source_format='OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1' AND c.evidence_class='EFFECT'
    AND c.sequence BETWEEN s.first_sequence AND s.through_sequence AND h.last_sequence>=s.through_sequence;
  SELECT * INTO STRICT a FROM control.evidence_candidate_archive WHERE participant_id=p AND privacy_domain_id=d
   AND stream_id=actual.stream_id AND record_id=actual.record_id AND candidate_id=(selected->>'candidate_id')::uuid;
  identity:=a.manifest->'identity';
  IF actual.receipt_digest IS DISTINCT FROM a.manifest_digest
   OR a.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex')
   OR identity->>'participantId' IS DISTINCT FROM p::text OR identity->>'privacyDomainId' IS DISTINCT FROM d::text
   OR identity->>'candidateId' IS DISTINCT FROM selected->>'candidate_id'
   OR identity->>'sourceProfileId' IS DISTINCT FROM selection#>>'{source,profile_id}'
   OR identity->>'generationId' IS DISTINCT FROM selection#>>'{source,generation_id}'
   OR identity->>'partitionId' IS DISTINCT FROM selection#>>'{source,partition_id}'
   OR identity->>'publicationDigest' IS DISTINCT FROM 'sha256:'||(selection#>>'{source,identity_digest}')
   OR identity->>'candidateFeedSequence' IS DISTINCT FROM selected->>'candidate_feed_sequence'
   OR identity->>'payloadDigest' IS DISTINCT FROM 'sha256:'||(selected->>'payload_digest')
   OR identity->>'payloadBytes' IS DISTINCT FROM selected->>'payload_bytes'
   OR identity->>'checkpointDigest' IS DISTINCT FROM 'sha256:'||(selected->>'checkpoint_digest')
  THEN RAISE EXCEPTION 'PC-DATA-6007-SOURCE'; END IF;
  -- Zero remote quorum still requires a complete original archive checkpoint
  -- chain, just as the Fact owner requires its original checkpoint. No storage
  -- retention deadline is shortened by retiring the native projection.
  chosen:=ARRAY[]::text[]; sinks:='[]';
  FOR checkpoint IN SELECT c.* FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d
   AND c.stream_id=actual.stream_id AND c.segment_id=actual.segment_id AND c.object_digest=actual.object_digest
   AND c.through_sequence=actual.through_sequence ORDER BY c.acknowledged_at,c.sink_id LOOP
   IF openpc.candidate_archive_coverage(p,d,actual.stream_id,actual.record_id,ARRAY[checkpoint.sink_id])->>'state'='COMPLETE' THEN
    chosen:=array_append(chosen,checkpoint.sink_id);
    sinks:=sinks||jsonb_build_array(jsonb_build_object('sinkId',checkpoint.sink_id,'checkpointDigest',checkpoint.checkpoint_digest,
     'receiptDigest',checkpoint.receipt_digest,'acknowledgedAtMicros',floor(extract(epoch from checkpoint.acknowledged_at)*1000000)::text));
    EXIT WHEN cardinality(chosen)=greatest(1,rule.sink_quorum);
   END IF;
  END LOOP;
  IF cardinality(chosen)<>greatest(1,rule.sink_quorum) THEN RAISE EXCEPTION 'PC-DATA-6007-SINK-QUORUM'; END IF;
  FOR archived IN SELECT DISTINCT c.occurred_at,s.segment_id,s.object_digest,s.through_sequence,s.admitted_at
   FROM control.evidence_candidate_archive_part part JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
   JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE part.participant_id=p AND part.privacy_domain_id=d AND part.stream_id=actual.stream_id AND part.manifest_record_id=actual.record_id LOOP
   IF EXISTS(SELECT 1 FROM control.retention_hold hold WHERE hold.participant_id=p
    AND (hold.selector_type='PARTICIPANT' OR hold.privacy_domain_id=d) AND hold.state='ACTIVE'
    AND openpc.evidence_hold_matches(hold.selector,p,d,actual.stream_id,archived.segment_id))
    THEN RAISE EXCEPTION 'PC-DATA-6007-ACTIVE-HOLD'; END IF;
   SELECT max(ceil(extract(epoch from c.acknowledged_at)*1000)) INTO ack_ms FROM control.evidence_checkpoint c
    WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.stream_id=actual.stream_id
     AND c.segment_id=archived.segment_id AND c.object_digest=archived.object_digest AND c.through_sequence=archived.through_sequence
     AND c.sink_id=ANY(chosen);
   latest:=greatest(ceil(extract(epoch from archived.occurred_at)*1000)+rule.retention_period_ms,
    greatest(ack_ms,ceil(extract(epoch from archived.admitted_at)*1000))+rule.local_grace_ms);
   eligible_ms:=greatest(eligible_ms,latest);
  END LOOP;
  refs:=refs||jsonb_build_array(ref);
  manifest:=manifest||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id',
   'evidenceId',actual.evidence_id::text,'streamId',actual.stream_id,'recordId',actual.record_id,
   'sequence',actual.sequence::text,'recordDigest',actual.receipt_digest,'segmentId',actual.segment_id::text,'objectDigest',actual.object_digest));
  acknowledgements:=acknowledgements||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id','sinkReceipts',sinks));
  row_index:=row_index+1;
 END LOOP;
 IF eligible_ms>floor(extract(epoch from clock_timestamp())*1000) OR eligible_ms>9223372036854775807
  THEN RAISE EXCEPTION 'PC-DATA-6007-RETENTION'; END IF;
 RETURN jsonb_build_object('version','OPENPC_STORE_RETIREMENT_SOURCE_V1','selectionWireHex',encode(selection_wire,'hex'),
  'recordRefs',refs,'manifest',manifest,'acknowledgements',acknowledgements,
  'archiveManifestDigest',encode(sha256(convert_to(openpc.signing_canonical_json(manifest),'UTF8')),'hex'),
  'archiveAcknowledgementDigest',encode(sha256(convert_to(openpc.signing_canonical_json(acknowledgements),'UTF8')),'hex'),
  'retentionNotBeforeMs',eligible_ms::text,'lifecycleRevision',openpc.store_retirement_lifecycle_revision(p,d)::text);
END $function$

CREATE OR REPLACE FUNCTION openpc.capture_runtime_artifact_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE job control.deletion_job;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'runtime_configuration_input' OR TG_OP<>'DELETE'
  OR TG_LEVEL<>'ROW' OR TG_WHEN<>'BEFORE' OR pg_trigger_depth()<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF OLD.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR OLD.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=OLD.participant_id AND privacy_domain_id=OLD.privacy_domain_id
  AND operation_id=openpc.current_operation_id() AND target_database='openpc_control' AND target_data_class='RUNTIME_ARTIFACT'
  AND state='EXECUTING' AND revision=0 AND external_attempt_state='NOT_STARTED';
 IF OLD.selected OR OLD.configuration_digest IS DISTINCT FROM sha256(OLD.configuration_cbor)
  OR octet_length(OLD.configuration_cbor) NOT BETWEEN 1 AND 4194304
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-SOURCE'; END IF;
 PERFORM openpc.assert_runtime_artifact_retirement_owner('eligibility');
 PERFORM openpc.assert_runtime_artifact_retirement_eligible(job,OLD);
 INSERT INTO control.runtime_artifact_retirement(deletion_job_id,participant_id,privacy_domain_id,runtime_configuration_input_id,
  module_installation_id,module_configuration_generation_id,configuration_digest,configuration_bytes,resource_bindings_digest,source_created_at,retirement_digest)
 VALUES(job.deletion_job_id,OLD.participant_id,OLD.privacy_domain_id,OLD.runtime_configuration_input_id,OLD.module_installation_id,
  OLD.module_configuration_generation_id,'sha256:'||encode(OLD.configuration_digest,'hex'),octet_length(OLD.configuration_cbor),
  'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(OLD.resource_bindings),'UTF8')),'hex'),OLD.created_at,'');
 RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_evidence_export_publication_pair()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE completion control.evidence_export_completion%ROWTYPE; event control.outbox_event%ROWTYPE;
BEGIN
 SELECT * INTO STRICT completion FROM control.evidence_export_completion
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT * INTO STRICT event FROM control.outbox_event
 WHERE participant_id=completion.participant_id AND privacy_domain_id=completion.privacy_domain_id AND event_id=completion.event_id;
 IF completion.state<>'PUBLISHED' THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PUBLICATION-INCOMPLETE'; END IF;
 PERFORM openpc.check_evidence_export_completion_event(event);
 RETURN NULL;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PUBLICATION-INCOMPLETE';
END $function$

CREATE OR REPLACE FUNCTION openpc.check_module_initial_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE operation uuid; receipt control.audit_occurrence%ROWTYPE;
BEGIN
 SELECT lifecycle_operation_id INTO STRICT operation FROM control.module_installation
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
    AND module_installation_id=NEW.module_installation_id;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=operation AND aggregate_id=NEW.module_installation_id
  AND aggregate_type='module-registration' AND catalog_operation_id IN ('MOD-OP-INSTALL','MOD-OP-ENABLE','MOD-OP-DISABLE');
 PERFORM openpc.check_module_lifecycle_state(receipt);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_module_lifecycle_state(receipt control.audit_occurrence)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE installation control.module_installation%ROWTYPE; version control.module_version%ROWTYPE;
 configuration control.module_configuration_generation%ROWTYPE; evaluation control.module_lifecycle_evaluation%ROWTYPE;
 prior control.audit_occurrence%ROWTYPE; candidate control.mutation_candidate%ROWTYPE; projection jsonb;
 enabled boolean:=receipt.catalog_operation_id='MOD-OP-ENABLE';
 disabled boolean:=receipt.catalog_operation_id='MOD-OP-DISABLE';
 binding bytea; value text; bytes bytea;
BEGIN
 IF receipt.catalog_operation_id NOT IN ('MOD-OP-INSTALL','MOD-OP-ENABLE','MOD-OP-DISABLE') OR receipt.before_existence<>1
  OR receipt.after_existence<>1 OR receipt.after_revision<>receipt.before_revision+1
 THEN RAISE EXCEPTION 'DATA-6021-MODULE-LIFECYCLE'; END IF;
 SELECT * INTO STRICT installation FROM control.module_installation m WHERE m.participant_id=receipt.participant_id
  AND m.privacy_domain_id=receipt.privacy_domain_id AND m.module_installation_id=receipt.aggregate_id
  AND m.aggregate_version=receipt.after_revision AND m.lifecycle_operation_id=receipt.operation_id;
 SELECT * INTO STRICT version FROM control.module_version WHERE module_version_id=installation.module_version_id;
 SELECT * INTO STRICT configuration FROM control.module_configuration_generation c
  WHERE c.participant_id=receipt.participant_id AND c.privacy_domain_id=receipt.privacy_domain_id
   AND c.module_installation_id=receipt.aggregate_id AND c.generation=1;
 SELECT * INTO STRICT evaluation FROM control.module_lifecycle_evaluation e
  WHERE e.participant_id=receipt.participant_id AND e.privacy_domain_id=receipt.privacy_domain_id
   AND e.operation_id=receipt.operation_id AND e.module_installation_id=receipt.aggregate_id
   AND e.revision=receipt.after_revision AND e.result_digest=installation.lifecycle_evaluation_digest
   AND e.result_digest=sha256(e.result_cbor);
 SELECT * INTO STRICT prior FROM control.audit_occurrence a WHERE a.participant_id=receipt.participant_id
  AND a.privacy_domain_id=receipt.privacy_domain_id AND a.aggregate_type=receipt.aggregate_type
  AND a.aggregate_id=receipt.aggregate_id AND a.after_revision=receipt.before_revision
  AND ((disabled AND a.catalog_operation_id='MOD-OP-ENABLE')
    OR (enabled AND a.catalog_operation_id IN ('MOD-OP-INSTALL','MOD-OP-DISABLE'))
    OR (NOT enabled AND NOT disabled AND a.catalog_operation_id='MOD-OP-REGISTER'));
 SELECT * INTO STRICT candidate FROM control.mutation_candidate c WHERE c.participant_id=receipt.participant_id
  AND c.privacy_domain_id=receipt.privacy_domain_id AND c.consumed_operation_id=receipt.operation_id
  AND c.catalog_operation_id=receipt.catalog_operation_id AND c.state='CONSUMED'
  AND c.resource_id=receipt.aggregate_id AND c.expected_revision=receipt.before_revision;
 IF disabled THEN
  -- Same framed transport descriptor as moduleDisableReplacementDigest; SQL
  -- verifies the admitted candidate against authoritative unchanged state.
  binding:=convert_to('pc.control.module-disable.v1','UTF8')||decode('00','hex');
  FOREACH value IN ARRAY ARRAY['MOD-OP-DISABLE','urn:openpc:resource:'||receipt.aggregate_id::text,
    receipt.before_revision::text,'sha256:'||encode(version.manifest_digest,'hex')] LOOP
   bytes:=convert_to(value,'UTF8'); binding:=binding||int4send(octet_length(bytes))||bytes;
  END LOOP;
  IF candidate.candidate_document->>'replacementDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(binding),'hex')
    OR candidate.candidate_document->>'expectedRevision' IS DISTINCT FROM receipt.before_revision::text
    OR candidate.candidate_document->>'actionIntentId' IS DISTINCT FROM 'ACT-MODULES_UPDATE_RESOURCE-V1'
    OR candidate.candidate_document-ARRAY['actionIntentId','actionIntentDigest','expectedRevision','replacementDigest','reason']<>'{}'::jsonb
  THEN RAISE EXCEPTION 'DATA-6021-MODULE-DISABLE-BINDING'; END IF;
 END IF;
 IF installation.state::text<>(CASE WHEN enabled THEN 'ENABLED' ELSE 'INSTALLED_DISABLED' END)
  OR configuration.active<>enabled OR installation.desired_manifest_digest<>version.manifest_digest
  OR installation.active_manifest_digest IS DISTINCT FROM (CASE WHEN enabled THEN version.manifest_digest ELSE NULL END)
  OR openpc.business_cbor(prior.after_state_preimage)->8 IS DISTINCT FROM openpc.business_cbor(receipt.before_state_preimage)->8
  OR installation.authority_epoch::text IS DISTINCT FROM (convert_from(receipt.authority_snapshot,'UTF8')::jsonb->'authorities'->0->>'authorityEpoch')
  OR installation.delegation_epoch::text IS DISTINCT FROM (convert_from(receipt.authority_snapshot,'UTF8')::jsonb->'authorities'->0->>'delegationEpoch')
  OR (NOT disabled AND (candidate.candidate_document->>'targetRef' IS DISTINCT FROM 'urn:openpc:resource:'||receipt.aggregate_id::text
  OR candidate.candidate_document->>'inputDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'targetRef','urn:openpc:resource:'||receipt.aggregate_id::text,'expectedRevision',receipt.before_revision::text,
   'manifestDigest','sha256:'||encode(version.manifest_digest,'hex'))),'UTF8')),'hex')))
 THEN RAISE EXCEPTION 'DATA-6021-MODULE-LIFECYCLE-BINDING'; END IF;
 projection:=jsonb_build_object('0',version.module_id,'1',version.semantic_version,'2',openpc.business_bytes(version.manifest_digest),
  '3',openpc.business_bytes(installation.admission_dependency_digest),'4',openpc.business_bytes(configuration.configuration_digest),
  '5',installation.state::text,'6',CASE WHEN enabled THEN 1 ELSE 0 END,'7',1,'8',CASE WHEN enabled THEN 1 ELSE 0 END,
  '9',openpc.business_bytes(evaluation.result_digest));
 IF enabled THEN projection:=projection||jsonb_build_object('10',openpc.business_bytes(version.manifest_digest)); END IF;
 IF projection IS DISTINCT FROM openpc.business_cbor(receipt.after_state_preimage)->8
  OR (projection-'5'-'6'-'8'-'9'-'10') IS DISTINCT FROM
     ((openpc.business_cbor(prior.after_state_preimage)->8)-'5'-'6'-'8'-'9'-'10')
 THEN RAISE EXCEPTION 'DATA-6021-MODULE-LIFECYCLE-PROJECTION'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_cancellation_signing_current(item control.notification_cancellation_signing)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d control.notification_delivery%ROWTYPE;signer control.notification_receipt_signer_installation%ROWTYPE;now_ms numeric;lock_name text;wm jsonb;
 t jsonb:=item.preparation->'input';r jsonb:=t->'receipt';b jsonb:=t->'before';n jsonb:=t->'after';expected jsonb;
 s control.notification_delivery_start%ROWTYPE;claim control.notification_delivery_dispatch_intent%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 PERFORM openpc.check_notification_cancellation_signing_original(item);
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id FOR UPDATE;
 IF jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest) IS DISTINCT FROM item.preparation->'input'->'before' OR d.cancel_requested OR d.state NOT IN ('PENDING','RETRY_WAIT','STARTED','AMBIGUOUS')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-STALE'; END IF;
  IF (b->>'state' IN ('PENDING','RETRY_WAIT','STARTED','AMBIGUOUS')) IS DISTINCT FROM true OR b->'cancelRequested' IS DISTINCT FROM 'false'::jsonb
 OR b->>'revision' IS DISTINCT FROM (r->>'deliveryRevision')::numeric::text OR n->>'revision' IS DISTINCT FROM ((r->>'deliveryRevision')::numeric+1)::text
 OR b->>'deliveryRequestOperationId' IS DISTINCT FROM (t->>'sourceOperationId')::uuid::text OR b->>'payloadDigest' IS DISTINCT FROM (r->>'payloadDigest')
 OR b->>'participantId' IS DISTINCT FROM item.participant_id::text OR b->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR b->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 OR n-ARRAY['revision','state','cancelRequested','nextAttemptAtMs'] IS DISTINCT FROM b-ARRAY['revision','state','cancelRequested','nextAttemptAtMs']
 OR n->'cancelRequested' IS DISTINCT FROM 'true'::jsonb OR n->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb
 OR n->>'state' IS DISTINCT FROM (CASE WHEN b->>'state' IN ('PENDING','RETRY_WAIT') THEN 'CANCELLED' ELSE b->>'state' END)
 OR r->>'beforeDeliveryState' IS DISTINCT FROM b->>'state' OR r->>'afterDeliveryState' IS DISTINCT FROM n->>'state' OR r->'attemptCount' IS DISTINCT FROM b->'attemptCount'
 OR r->>'disposition' IS DISTINCT FROM (CASE WHEN b->>'state'='PENDING' THEN 'CANCELLED_BEFORE_START' WHEN b->>'state'='RETRY_WAIT' THEN 'PREVENT_LATER_ATTEMPTS' ELSE 'RECONCILE_ORIGINAL' END)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-TRANSITION'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',b->>'revision','projection',b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'beforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',n->>'revision','projection',n-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 IF b->>'state'='PENDING' THEN
  IF b->'attemptCount' IS DISTINCT FROM '0'::jsonb OR t->'originalStart' IS DISTINCT FROM 'null'::jsonb OR t->'originalClaim' IS DISTINCT FROM 'null'::jsonb
   OR EXISTS(SELECT 1 FROM control.notification_delivery_attempt WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id)
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 ELSE
  SELECT * INTO STRICT s FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=(t->'originalStart'->'receipt'->>'operationId')::uuid;
  PERFORM openpc.check_notification_delivery_start_original(s);
  SELECT * INTO STRICT claim FROM control.notification_delivery_dispatch_intent WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND operation_id=s.operation_id;
  PERFORM openpc.check_notification_delivery_dispatch_intent_original(claim);
  IF t->'originalStart' IS DISTINCT FROM s.transition OR s.notification_occurrence_id<>item.notification_occurrence_id OR s.payload_digest<>(r->>'payloadDigest')
   OR t->'originalClaim' IS DISTINCT FROM jsonb_build_object('state',claim.state,'claimToken',claim.claim_token,'claimedAtMs',claim.claimed_at_ms)
   OR s.transition->'attempt'->'attemptNumber' IS DISTINCT FROM b->'attemptCount' OR s.transition->'attempt'->'startedAtMs' IS DISTINCT FROM b->'lastStartedAtMs'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 END IF;
 IF b->>'state'='RETRY_WAIT' THEN
  SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
   AND notification_occurrence_id=item.notification_occurrence_id AND start_operation_id=s.operation_id AND attempt_id=s.attempt_id;
  PERFORM openpc.check_notification_outcome_publication_original(o.operation_id);
  IF t->'originalOutcome' IS DISTINCT FROM o.transition OR o.transition->'receipt'->>'outcome' IS DISTINCT FROM 'RETRYABLE_NO_EFFECT'
   OR o.transition->'receipt'->>'afterDeliveryState' IS DISTINCT FROM 'RETRY_WAIT' OR claim.state<>'CLAIMED'
   OR (b->>'revision')::numeric<o.delivery_revision+1 OR (b->>'attemptLimit')::numeric>(o.transition->'receipt'->>'attemptLimit')::numeric
   OR (r->>'recordedAtMs')::numeric<(o.transition->'receipt'->>'recordedAtMs')::numeric
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-LINEAGE'; END IF;
  expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',(o.delivery_revision+1)::text,
   'projection',(b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest'])||jsonb_build_object('attemptLimit',o.transition->'receipt'->'attemptLimit'));
  IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM o.transition->'receipt'->>'afterStateDigest'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-STATE'; END IF;
 ELSIF t ? 'originalOutcome' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-UNEXPECTED-OUTCOME'; END IF;
 IF r->>'recordedAtMs' IS NULL OR r->>'workerProfileDigest' IS NULL THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-BINDING'; END IF;
 lock_name:='notification-receipt-signer:'||item.participant_id::text||':'||item.privacy_domain_id::text;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ShareLock'
 AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-FENCE'; END IF;
 SELECT * INTO STRICT signer FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest AND state='ACTIVE';
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 SELECT openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex')) INTO STRICT wm FROM control.installed_notification_worker
 WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 IF now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric OR now_ms*1000000<(signer.trust->>'validFromNs')::numeric OR now_ms*1000000>=(signer.trust->>'validUntilNs')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_worker w JOIN control.credential c ON c.participant_id=w.participant_id AND c.credential_id=w.workload_credential_id
   JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
   WHERE w.participant_id=item.participant_id AND w.privacy_domain_id=item.privacy_domain_id AND w.installation_digest=signer.worker_installation_digest AND w.state='ACTIVE'
    AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=signer.trust->>'workloadEpoch'
    AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND p.state='ACTIVE' AND p.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-AUTHORITY'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_disposition_signed(event uuid, t jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s control.notification_completion_disposition_signing%ROWTYPE;m jsonb;r jsonb;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 PERFORM openpc.check_notification_completion_signing_preparation(event,s.preparation);
 PERFORM openpc.check_notification_completion_signing_observation(event,s.observation);
 m:=openpc.business_cbor(decode(s.preparation->'request'->>'payloadHex','hex'));r:=jsonb_build_object('environmentId',m->'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'operationId',(m->'5'->>'bytes')::uuid::text,'sourceEventId',(m->'6'->>'bytes')::uuid::text,'sourceEnvelopeDigest','sha256:'||(m->'7'->>'bytes'),'sourceDataDigest','sha256:'||(m->'8'->>'bytes'),'sourcePartitionDigest','sha256:'||(m->'9'->>'bytes'),'producerTrustDigest','sha256:'||(m->'10'->>'bytes'),'sourceReceiptDigest','sha256:'||(m->'11'->>'bytes'),'initialWorkerInstallationDigest','sha256:'||(m->'12'->>'bytes'),'initialWorkerProfileDigest','sha256:'||(m->'13'->>'bytes'),'workerInstallationDigest','sha256:'||(m->'14'->>'bytes'),'workerProfileDigest','sha256:'||(m->'15'->>'bytes'),'authoritySnapshotDigest','sha256:'||(m->'16'->>'bytes'),'attemptChainDigest','sha256:'||(m->'17'->>'bytes'),'attemptCount',(m->>'18')::numeric,'attemptLimit',(m->>'19')::numeric,'initialAttemptLimit',(m->>'20')::numeric,'initialBackoffMs',(m->>'21')::numeric,'maximumBackoffMs',(m->>'22')::numeric,'signerInstallationDigest','sha256:'||(m->'23'->>'bytes'),'disposition',CASE m->>'24' WHEN '1' THEN 'ADMITTED' WHEN '2' THEN 'QUARANTINED' ELSE NULL END,'safeProblem',CASE m->>'25' WHEN '0' THEN 'NONE' WHEN '1' THEN 'PC-OPS-9001' ELSE NULL END,'workItemKind',CASE m->>'26' WHEN '0' THEN 'NONE' WHEN '1' THEN 'DELIVERY_FAILURE' WHEN '2' THEN 'REMEDIATION' ELSE NULL END,'workItemId',(m->'27'->>'bytes')::uuid::text,'beforeStateDigest','sha256:'||(m->'28'->>'bytes'),'afterStateDigest','sha256:'||(m->'29'->>'bytes'),'cursorMode',CASE m->>'30' WHEN '1' THEN 'ADVANCE' WHEN '2' THEN 'HOLD' ELSE NULL END,'recordedAtMs',(m->>'31')::numeric,'signerKeyId','sha256:'||(m->'32'->>'bytes'));
 IF s.state IS DISTINCT FROM 'OBSERVED' OR s.observation->>'outcome' IS DISTINCT FROM 'SIGNED'
 OR t IS DISTINCT FROM jsonb_build_object('schema','pc.notification.completion-disposition.v1','input',s.preparation->'preparation','receipt',r,'payloadHex',s.preparation->'request'->>'payloadHex','coseHex',s.observation->>'coseHex')
 THEN RAISE EXCEPTION 'COMPLETION-DISPOSITION-SIGNED'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_disposition_structure(event uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d control.notification_completion_disposition%ROWTYPE;s control.notification_completion_source%ROWTYPE;
 signing control.notification_completion_disposition_signing%ROWTYPE;e control.outbox_event%ROWTYPE;
 inbox control.notification_source_inbox%ROWTYPE;cursor_row control.notification_source_cursor%ROWTYPE;
 work control.work_item%ROWTYPE;history control.audit_occurrence%ROWTYPE;r jsonb;expected jsonb;partition_key text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 SELECT * INTO STRICT d FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT signing FROM control.notification_completion_disposition_signing WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 -- Existing checker binds original producer outbox, immutable attempt chain,
 -- canonical receipt claims and observed COSE framing. It is NOT crypto proof.
 PERFORM openpc.check_notification_completion_disposition_signed(event,d.transition);
 r:=d.transition->'receipt';partition_key:='urn:openpc:resource:'||e.aggregate_id::text;
 IF d.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(d.transition),'UTF8')
 OR d.transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(d.transition_bytes),'hex')
 OR d.receipt_payload IS DISTINCT FROM decode(d.transition->>'payloadHex','hex') OR d.cose_sign1 IS DISTINCT FROM decode(d.transition->>'coseHex','hex')
 OR r->>'participantId' IS DISTINCT FROM d.participant_id::text OR r->>'privacyDomainId' IS DISTINCT FROM d.privacy_domain_id::text
 OR r->>'sourceEventId' IS DISTINCT FROM event::text OR r->>'receiptId' IS DISTINCT FROM d.receipt_id::text OR r->>'operationId' IS DISTINCT FROM d.operation_id::text
 OR r->>'disposition' IS DISTINCT FROM d.disposition OR signing.state IS DISTINCT FROM 'OBSERVED'
 OR signing.operation_id IS DISTINCT FROM d.operation_id OR signing.signing_attempt_id IS DISTINCT FROM d.receipt_id
 OR signing.observation->>'outcome' IS DISTINCT FROM 'SIGNED' OR signing.observation->>'coseHex' IS DISTINCT FROM encode(d.cose_sign1,'hex')
 OR signing.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signing.preparation),'UTF8')
 OR signing.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(signing.preparation_bytes),'hex')
 OR signing.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signing.observation),'UTF8')
 OR signing.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(signing.observation_bytes),'hex')
 OR s.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source),'UTF8')
 OR s.source_digest IS DISTINCT FROM 'sha256:'||encode(sha256(s.source_bytes),'hex')
 OR s.source->'envelope' IS DISTINCT FROM openpc.notification_completion_source_envelope(e)
 OR s.original_selector IS DISTINCT FROM s.source->'originalSelector'
 OR e.business_sequence IS DISTINCT FROM 1 OR e.aggregate_type IS DISTINCT FROM 'notification-occurrence'
 OR e.source IS DISTINCT FROM 'urn:openpc:service:LS-NOTIFICATION'
 THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-STRUCTURE'; END IF;
 SELECT * INTO STRICT inbox FROM control.notification_source_inbox WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
 AND subscription_id='SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1' AND event_id=event;
 IF inbox.source IS DISTINCT FROM e.source OR inbox.partition IS DISTINCT FROM partition_key OR inbox.source_sequence IS DISTINCT FROM e.business_sequence
 OR inbox.data_digest IS DISTINCT FROM s.source->'reference'->>'dataDigest' OR inbox.data_digest IS DISTINCT FROM r->>'sourceDataDigest'
 OR inbox.envelope IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source->'envelope'),'UTF8')
 OR inbox.envelope_digest IS DISTINCT FROM 'sha256:'||encode(sha256(inbox.envelope),'hex') OR inbox.envelope_digest IS DISTINCT FROM r->>'sourceEnvelopeDigest'
 OR inbox.admission_operation_id IS DISTINCT FROM d.operation_id OR inbox.state IS DISTINCT FROM d.disposition
 OR inbox.safe_problem_code IS DISTINCT FROM (CASE d.disposition WHEN 'QUARANTINED' THEN 'PC-OPS-9001' ELSE NULL END)
 THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-INBOX'; END IF;
 IF d.disposition='ADMITTED' THEN
  IF r->>'cursorMode' IS DISTINCT FROM 'ADVANCE' OR r->>'safeProblem' IS DISTINCT FROM 'NONE'
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-ADMITTED'; END IF;
  -- This authentic producer's publication checker preserves an existing failure
  -- WorkItem through its original human transition history; never reset it OPEN.
  PERFORM openpc.check_notification_completion_validated_source(event);
  SELECT * INTO STRICT cursor_row FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND subscription_id=inbox.subscription_id AND source=inbox.source AND partition=inbox.partition;
  IF cursor_row.last_sequence IS DISTINCT FROM inbox.source_sequence OR cursor_row.last_event_id IS DISTINCT FROM event
   OR cursor_row.last_data_digest IS DISTINCT FROM inbox.data_digest OR cursor_row.revision<1
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-CURSOR'; END IF;
  IF EXISTS(SELECT 1 FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id)
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-UNEXPECTED-WORK'; END IF;
 ELSIF d.disposition='QUARANTINED' THEN
  IF r->>'cursorMode' IS DISTINCT FROM 'HOLD' OR r->>'safeProblem' IS DISTINCT FROM 'PC-OPS-9001'
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-QUARANTINE'; END IF;
  -- HOLD permits an absent cursor or its untouched empty initial position.
  IF EXISTS(SELECT 1 FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND subscription_id=inbox.subscription_id AND source=inbox.source AND partition=inbox.partition
   AND (last_sequence<>0 OR last_event_id IS NOT NULL OR last_data_digest IS NOT NULL OR revision<>1))
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-CURSOR-HOLD'; END IF;
  SELECT * INTO STRICT work FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id;
  expected:=openpc.notification_completion_remediation_projection(d);
  IF work.row_version=1 THEN
   IF openpc.work_item_business_projection(work) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-REMEDIATION'; END IF;
  ELSE
   SELECT * INTO STRICT history FROM control.audit_occurrence WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
    AND aggregate_type='work-item' AND aggregate_id=work.work_item_id AND before_revision=1;
   IF history.before_existence<>1 OR history.before_state_digest IS DISTINCT FROM sha256(history.before_state_preimage)
    OR history.receipt_digest IS DISTINCT FROM sha256(history.receipt_cbor)
    OR openpc.business_cbor(history.receipt_cbor)->'18' IS DISTINCT FROM jsonb_build_object('0',1,'1',1,'2',openpc.business_bytes(history.before_state_digest))
    OR openpc.business_cbor(history.before_state_preimage)->8 IS DISTINCT FROM expected
   THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-REMEDIATION-HISTORY'; END IF;
  END IF;
 ELSE RAISE EXCEPTION 'COMPLETION-ORIGINAL-DISPOSITION'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_phase_source(event uuid, phase text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE binding record; current_worker control.installed_notification_completion_worker%ROWTYPE;
 original control.notification_delivery_outcome%ROWTYPE;producer control.installed_notification_worker%ROWTYPE;producer_profile jsonb;
BEGIN
 SELECT * INTO STRICT binding FROM openpc.notification_completion_phase_binding(event,phase);
 SELECT * INTO STRICT current_worker FROM control.installed_notification_completion_worker WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND installation_digest=binding.installation_digest AND state='ACTIVE';
 SELECT * INTO STRICT original FROM control.notification_delivery_outcome WHERE participant_id=current_worker.participant_id
  AND privacy_domain_id=current_worker.privacy_domain_id AND receipt_id=event;
 PERFORM openpc.check_notification_completion_source_origin(event,original.receipt_digest);
 SELECT * INTO STRICT producer FROM control.installed_notification_worker WHERE participant_id=original.participant_id
  AND privacy_domain_id=original.privacy_domain_id AND installation_digest=original.worker_installation_digest;
 producer_profile:=openpc.business_cbor(decode(producer.installation->'signed'->>'payloadHex','hex'));
 IF producer_profile->'16' IS DISTINCT FROM openpc.business_bytes(decode(substr(current_worker.producer_trust_digest,8),'hex'))
 OR current_worker.installation->'pins'->>'environmentId' IS DISTINCT FROM producer.installation->'pins'->>'environmentId'
 OR original.transition->'receipt'->>'environmentId' IS DISTINCT FROM current_worker.installation->'pins'->>'environmentId'
 THEN RAISE EXCEPTION 'COMPLETION-PHASE-PRODUCER'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_shared_publication(event uuid)
 RETURNS control.notification_completion_disposition
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d control.notification_completion_disposition%ROWTYPE;s control.notification_completion_disposition_signing%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 SELECT * INTO STRICT d FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 PERFORM openpc.check_notification_completion_phase_source(event,'PUBLISH');
 PERFORM openpc.check_notification_completion_receipt_admission(event,'PUBLISH',s.observation);
 PERFORM openpc.check_notification_completion_disposition_signed(event,d.transition);
 RETURN d;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_signing_current(event uuid, preparation jsonb, phase text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s control.notification_completion_disposition_signer_installation%ROWTYPE;w control.installed_notification_completion_worker%ROWTYPE;c control.credential%ROWTYPE;m jsonb;n numeric;
BEGIN
 IF phase IS NULL OR phase NOT IN ('PREPARE','SIGN_CLAIM') THEN RAISE EXCEPTION 'COMPLETION-SIGNING-PHASE'; END IF;
 PERFORM openpc.check_notification_completion_signing_preparation(event,preparation);
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-completion-disposition-signer:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signer_installation WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND trust_digest=preparation->'request'->>'signerInstallationDigest' AND state='ACTIVE';
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND installation_digest=s.worker_installation_digest AND state='ACTIVE';
 SELECT * INTO STRICT c FROM control.credential WHERE participant_id=w.participant_id AND credential_id=w.workload_credential_id AND principal_id=w.principal_id;
 m:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));n:=floor(extract(epoch from clock_timestamp())*1000);
 IF c.state<>'ACTIVE' OR c.kind<>'WORKLOAD_MTLS' OR c.credential_epoch::text IS DISTINCT FROM w.installation->'pins'->>'workloadEpoch' OR c.valid_until IS NULL OR c.valid_from>clock_timestamp() OR c.valid_until<=clock_timestamp()
 OR n<(m->>'6')::numeric OR n>=(m->>'7')::numeric OR n*1000000<(s.trust->>'validFromNs')::numeric OR n*1000000>=(s.trust->>'validUntilNs')::numeric
 OR n<(preparation->'preparation'->'metadata'->>'recordedAtMs')::numeric
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-CURRENT'; END IF;
 PERFORM openpc.check_notification_completion_effect_binding(event,phase,w.installation_digest,preparation->'preparation'->'metadata'->>'authoritySnapshotDigest');
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_signing_observation(event uuid, ob jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s control.notification_completion_disposition_signing%ROWTYPE;q jsonb;signer control.notification_completion_disposition_signer_installation%ROWTYPE;w jsonb;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 q:=s.preparation->'request';PERFORM openpc.check_notification_completion_signing_preparation(event,s.preparation);
 SELECT * INTO STRICT signer FROM control.notification_completion_disposition_signer_installation WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND trust_digest=s.signer_installation_digest;
 SELECT openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex')) INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 IF s.state NOT IN ('DISPATCHED','OBSERVED') OR s.dispatched_at_ms IS NULL
 OR ob-ARRAY['schemaVersion','providerId','signingAttemptId','requestDigest','recordedAtMs','outcome','reason','coseHex'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(ob))<>8
 OR ob->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR ob->>'providerId' IS DISTINCT FROM q->>'providerId' OR ob->>'signingAttemptId' IS DISTINCT FROM s.signing_attempt_id::text OR ob->>'requestDigest' IS DISTINCT FROM s.request_digest
 OR (jsonb_typeof(ob->'recordedAtMs')='number' AND (ob->>'recordedAtMs') ~ '^(0|[1-9][0-9]*)$' AND (ob->>'recordedAtMs')::numeric<=9007199254740991) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION'; END IF;
 IF ob->>'outcome'='SIGNED' THEN
  IF ob->'reason' IS DISTINCT FROM 'null'::jsonb OR (ob->>'recordedAtMs')::numeric<s.dispatched_at_ms OR (ob->>'recordedAtMs')::numeric>=(w->>'7')::numeric OR (ob->>'recordedAtMs')::numeric*1000000>=(signer.trust->>'validUntilNs')::numeric
  THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION-TIME'; END IF;
  PERFORM openpc.archive_cose_binding(decode(q->>'payloadHex','hex'),decode(ob->>'coseHex','hex'),signer.signer_id,24031,368);
 ELSIF ob->>'outcome' IS DISTINCT FROM 'REJECTED' OR ob->'coseHex' IS DISTINCT FROM 'null'::jsonb OR (ob->>'reason' IN ('REVOKED','EXPIRED','WRONG_SCOPE','INVALID_REQUEST','ATTEMPT_CONFLICT','KEY_UNAVAILABLE')) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION-REJECTION'; END IF;
 IF s.state='OBSERVED' AND s.observation IS DISTINCT FROM ob THEN RAISE EXCEPTION 'COMPLETION-SIGNING-FIRST'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_signing_preparation(event uuid, preparation jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s control.notification_completion_source%ROWTYPE;signer control.notification_completion_disposition_signer_installation%ROWTYPE;w control.installed_notification_completion_worker%ROWTYPE;
 t jsonb:=preparation->'preparation';q jsonb:=preparation->'request';j jsonb;attempts jsonb;last_attempt jsonb;initial_profile jsonb;current_profile jsonb;m jsonb;r jsonb;before_state jsonb;after_state jsonb;expected_work text;expected_work_id text;expected_outcome text;counted integer;n numeric;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 PERFORM openpc.check_notification_completion_source_origin(event,s.source->'reference'->>'receiptDigest');
 SELECT jsonb_agg(attempt ORDER BY number),count(*) INTO attempts,counted FROM control.notification_completion_attempt WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND event_id=event;
 j:=jsonb_build_object('source',s.source->'reference','initialWorker',s.initial_worker,'effectiveLimit',s.effective_limit,'attempts',attempts);
 last_attempt:=attempts->(counted-1);initial_profile:=openpc.business_cbor(decode(s.initial_worker->'signed'->>'payloadHex','hex'));
 m:=openpc.business_cbor(decode(q->>'payloadHex','hex'));r:=jsonb_build_object('environmentId',m->'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'operationId',(m->'5'->>'bytes')::uuid::text,'sourceEventId',(m->'6'->>'bytes')::uuid::text,'sourceEnvelopeDigest','sha256:'||(m->'7'->>'bytes'),'sourceDataDigest','sha256:'||(m->'8'->>'bytes'),'sourcePartitionDigest','sha256:'||(m->'9'->>'bytes'),'producerTrustDigest','sha256:'||(m->'10'->>'bytes'),'sourceReceiptDigest','sha256:'||(m->'11'->>'bytes'),'initialWorkerInstallationDigest','sha256:'||(m->'12'->>'bytes'),'initialWorkerProfileDigest','sha256:'||(m->'13'->>'bytes'),'workerInstallationDigest','sha256:'||(m->'14'->>'bytes'),'workerProfileDigest','sha256:'||(m->'15'->>'bytes'),'authoritySnapshotDigest','sha256:'||(m->'16'->>'bytes'),'attemptChainDigest','sha256:'||(m->'17'->>'bytes'),'attemptCount',(m->>'18')::numeric,'attemptLimit',(m->>'19')::numeric,'initialAttemptLimit',(m->>'20')::numeric,'initialBackoffMs',(m->>'21')::numeric,'maximumBackoffMs',(m->>'22')::numeric,'signerInstallationDigest','sha256:'||(m->'23'->>'bytes'),'disposition',CASE m->>'24' WHEN '1' THEN 'ADMITTED' WHEN '2' THEN 'QUARANTINED' ELSE NULL END,'safeProblem',CASE m->>'25' WHEN '0' THEN 'NONE' WHEN '1' THEN 'PC-OPS-9001' ELSE NULL END,'workItemKind',CASE m->>'26' WHEN '0' THEN 'NONE' WHEN '1' THEN 'DELIVERY_FAILURE' WHEN '2' THEN 'REMEDIATION' ELSE NULL END,'workItemId',(m->'27'->>'bytes')::uuid::text,'beforeStateDigest','sha256:'||(m->'28'->>'bytes'),'afterStateDigest','sha256:'||(m->'29'->>'bytes'),'cursorMode',CASE m->>'30' WHEN '1' THEN 'ADVANCE' WHEN '2' THEN 'HOLD' ELSE NULL END,'recordedAtMs',(m->>'31')::numeric,'signerKeyId','sha256:'||(m->'32'->>'bytes'));
 SELECT * INTO STRICT signer FROM control.notification_completion_disposition_signer_installation WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND trust_digest=q->>'signerInstallationDigest';
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 current_profile:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));
 IF preparation-ARRAY['schema','preparation','request','requestDigest'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(preparation))<>4 OR preparation->>'schema' IS DISTINCT FROM 'pc.notification.completion-disposition-signing.v1'
 OR t-ARRAY['journal','workerInstallation','signerInstallation','metadata','disposition','producerOutcome','producerWorkItemId'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(t))<>7
 OR t->'journal' IS DISTINCT FROM j OR counted<1 OR counted>(initial_profile->>'17')::integer
 OR m->'0' IS DISTINCT FROM jsonb_build_object('bytes','b8af9858ca24f16a251e4e27875bded1d2b612a2cebba9cfa9901b43155fca7d') OR (SELECT count(*) FROM jsonb_object_keys(m))<>33
 OR r->>'sourceEventId' IS DISTINCT FROM event::text OR r->>'participantId' IS DISTINCT FROM s.participant_id::text OR r->>'privacyDomainId' IS DISTINCT FROM s.privacy_domain_id::text
 OR r->>'initialWorkerInstallationDigest' IS DISTINCT FROM s.initial_worker_installation_digest OR r->>'initialWorkerProfileDigest' IS DISTINCT FROM s.initial_worker->'pins'->>'signedProfileDigest'
 OR r->>'attemptChainDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(j||jsonb_build_object('schema','pc.notification.completion-attempt-chain.v1')),'UTF8')),'hex')
 OR r->'attemptCount' IS DISTINCT FROM to_jsonb(counted) OR r->'attemptLimit' IS DISTINCT FROM to_jsonb(s.effective_limit)
 OR s.effective_limit>(initial_profile->>'17')::numeric OR s.effective_limit>(current_profile->>'17')::numeric
 OR r->'initialAttemptLimit' IS DISTINCT FROM initial_profile->'17' OR r->'initialBackoffMs' IS DISTINCT FROM initial_profile->'18' OR r->'maximumBackoffMs' IS DISTINCT FROM initial_profile->'19'
 OR r->>'sourceEnvelopeDigest' IS DISTINCT FROM s.source->'reference'->>'envelopeDigest'
 OR r->>'sourceDataDigest' IS DISTINCT FROM s.source->'reference'->>'dataDigest'
 OR r->>'sourcePartitionDigest' IS DISTINCT FROM s.source->'reference'->>'partitionDigest'
 OR r->>'producerTrustDigest' IS DISTINCT FROM s.source->'reference'->>'producerTrustDigest'
 OR r->>'sourceReceiptDigest' IS DISTINCT FROM s.source->'reference'->>'receiptDigest'
 OR r->>'receiptId' IS DISTINCT FROM q->>'signingAttemptId' OR r->>'operationId' IS DISTINCT FROM q->>'operationId' OR r->>'receiptId'=r->>'operationId' OR event::text IN (r->>'receiptId',r->>'operationId')
 OR t->'metadata' IS DISTINCT FROM jsonb_build_object('receiptId',r->'receiptId','operationId',r->'operationId','authoritySnapshotDigest',r->'authoritySnapshotDigest','recordedAtMs',r->'recordedAtMs','beforeStateDigest',r->'beforeStateDigest','afterStateDigest',r->'afterStateDigest')
 OR t->>'disposition' IS DISTINCT FROM r->>'disposition' OR (r->>'recordedAtMs')::numeric<(last_attempt->>'finishedAtMs')::numeric
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-JOURNAL'; END IF;
 IF r->>'disposition'='ADMITTED' THEN
  IF last_attempt->>'state' IS DISTINCT FROM 'VALIDATED' OR r->>'safeProblem' IS DISTINCT FROM 'NONE' OR r->>'cursorMode' IS DISTINCT FROM 'ADVANCE' THEN RAISE EXCEPTION 'COMPLETION-SIGNING-ADMITTED'; END IF;
  PERFORM openpc.check_notification_completion_validated_source(event);
  SELECT transition->'receipt'->>'afterDeliveryState' INTO STRICT expected_outcome FROM control.notification_delivery_outcome WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND receipt_id=event;
  expected_work:=CASE expected_outcome WHEN 'FAILED' THEN 'DELIVERY_FAILURE' ELSE 'NONE' END;
  expected_work_id:=CASE expected_outcome WHEN 'FAILED' THEN event::text ELSE r->>'receiptId' END;
  IF t->>'producerOutcome' IS DISTINCT FROM expected_outcome OR t->'producerWorkItemId' IS DISTINCT FROM (CASE expected_outcome WHEN 'FAILED' THEN to_jsonb(event::text) ELSE 'null'::jsonb END) THEN RAISE EXCEPTION 'COMPLETION-SIGNING-PRODUCER'; END IF;
 ELSIF r->>'disposition'='QUARANTINED' THEN
  IF last_attempt->>'state' IS DISTINCT FROM 'FAILED' OR counted<s.effective_limit OR r->>'safeProblem' IS DISTINCT FROM 'PC-OPS-9001' OR r->>'cursorMode' IS DISTINCT FROM 'HOLD' OR t->'producerOutcome' IS DISTINCT FROM 'null'::jsonb OR t->'producerWorkItemId' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'COMPLETION-SIGNING-QUARANTINE'; END IF;
  expected_work:='REMEDIATION';expected_work_id:=r->>'receiptId';
 ELSE RAISE EXCEPTION 'COMPLETION-SIGNING-DISPOSITION';END IF;
 before_state:=jsonb_build_object('schema','pc.notification.completion-disposition-state.v1','journal',j,'disposition',NULL);
 after_state:=before_state||jsonb_build_object('disposition',r->'disposition','receiptId',r->'receiptId','operationId',r->'operationId','workItemKind',expected_work,'workItemId',expected_work_id,'cursorMode',r->'cursorMode');
 IF r->>'workItemKind' IS DISTINCT FROM expected_work OR r->>'workItemId' IS DISTINCT FROM expected_work_id OR r->>'beforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(before_state),'UTF8')),'hex') OR r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(after_state),'UTF8')),'hex')
 OR q-ARRAY['schemaVersion','method','purpose','signerInstallationDigest','providerId','secretClass','reference','version','keyEpoch','signerKeyId','environmentId','participantId','privacyDomainId','workloadCredentialId','workloadEpoch','workerInstallationDigest','workerProfileDigest','signingAttemptId','operationId','sourceEventId','attemptChainDigest','dispositionPreparationDigest','payloadHex'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(q))<>23
 OR q->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR q->>'method' IS DISTINCT FROM 'SIGN_NOTIFICATION_COMPLETION_DISPOSITION' OR q->>'purpose' IS DISTINCT FROM 'pc.cose.notification-completion-disposition-receipt.v1'
 OR q->>'dispositionPreparationDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(t),'UTF8')),'hex') OR preparation->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.notification.completion-disposition-provider-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(q),'UTF8')),'hex')
 OR t->'workerInstallation' IS DISTINCT FROM w.installation OR t->'signerInstallation' IS DISTINCT FROM signer.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId']
 OR signer.trust->>'purpose' IS DISTINCT FROM 'pc.cose.notification-completion-disposition-receipt.v1' OR signer.trust->>'owner' IS DISTINCT FROM 'LS-CONTROL-WORK'
 OR q->>'environmentId' IS DISTINCT FROM signer.trust->>'environmentId'
 OR q->>'participantId' IS DISTINCT FROM signer.trust->>'participantId'
 OR q->>'privacyDomainId' IS DISTINCT FROM signer.trust->>'privacyDomainId'
 OR q->>'workerInstallationDigest' IS DISTINCT FROM signer.trust->>'workerInstallationDigest'
 OR q->>'workerProfileDigest' IS DISTINCT FROM signer.trust->>'workerProfileDigest'
 OR q->>'signerKeyId' IS DISTINCT FROM signer.trust->>'signerKeyId'
 OR q->>'providerId' IS DISTINCT FROM signer.trust->>'providerId'
 OR q->>'secretClass' IS DISTINCT FROM signer.trust->>'secretClass'
 OR q->>'keyEpoch' IS DISTINCT FROM signer.trust->>'keyEpoch'
 OR q->>'workloadCredentialId' IS DISTINCT FROM signer.trust->>'workloadCredentialId'
 OR q->>'workloadEpoch' IS DISTINCT FROM signer.trust->>'workloadEpoch'
 OR q->>'reference' IS DISTINCT FROM signer.trust->>'secretReference' OR q->>'version' IS DISTINCT FROM signer.trust->>'secretVersion'
 OR r->>'environmentId' IS DISTINCT FROM q->>'environmentId'
 OR r->>'participantId' IS DISTINCT FROM q->>'participantId'
 OR r->>'privacyDomainId' IS DISTINCT FROM q->>'privacyDomainId'
 OR r->>'workerInstallationDigest' IS DISTINCT FROM q->>'workerInstallationDigest'
 OR r->>'workerProfileDigest' IS DISTINCT FROM q->>'workerProfileDigest'
 OR r->>'signerKeyId' IS DISTINCT FROM q->>'signerKeyId'
 OR r->>'signerInstallationDigest' IS DISTINCT FROM q->>'signerInstallationDigest'
