 OR (d.revision=c.delivery_revision+1 AND jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest) IS DISTINCT FROM c.transition->'after')
