 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);r:=o.transition->'receipt';
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',before_row.revision::text,'projection',jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested));digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex');
 IF digest IS DISTINCT FROM r->>'beforeStateDigest' OR after_row.revision<>before_row.revision+1
 OR to_jsonb(after_row)-ARRAY['state','attempt_limit','next_attempt_at_ms','revision'] IS DISTINCT FROM to_jsonb(before_row)-ARRAY['state','attempt_limit','next_attempt_at_ms','revision']
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PROJECTION-BEFORE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',after_row.revision::text,'projection',jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested));
 IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM r->>'afterStateDigest' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PROJECTION-AFTER'; END IF;
