CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_start_complete(operation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE start control.notification_delivery_start%ROWTYPE;a control.notification_delivery_attempt%ROWTYPE;d control.notification_delivery%ROWTYPE;i control.notification_delivery_dispatch_intent%ROWTYPE;
BEGIN
 -- Deferred checks run after the application restores its original action. All
 -- live admissions ran before mutation; this check grants no fresh authority.
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_start_original(start);
 SELECT * INTO STRICT a FROM control.notification_delivery_attempt WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND start_operation_id=start.operation_id;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND notification_occurrence_id=start.notification_occurrence_id;
 SELECT * INTO STRICT i FROM control.notification_delivery_dispatch_intent WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND operation_id=start.operation_id;
 IF a.attempt_id IS DISTINCT FROM start.attempt_id OR a.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR a.payload_digest IS DISTINCT FROM start.payload_digest
 OR to_jsonb(a.attempt_number) IS DISTINCT FROM start.transition->'attempt'->'attemptNumber' OR to_jsonb(a.started_at_ms) IS DISTINCT FROM start.transition->'attempt'->'startedAtMs'
 OR a.worker_credential_id::text IS DISTINCT FROM start.transition->'context'->>'authorizationContextId' OR a.worker_credential_epoch::numeric IS DISTINCT FROM (start.transition->'context'->>'authorizationContextEpoch')::numeric
 OR d.revision IS DISTINCT FROM start.delivery_revision+1 OR jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested) IS DISTINCT FROM start.transition->'after'
 OR i.attempt_id IS DISTINCT FROM start.attempt_id OR i.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR i.payload_digest IS DISTINCT FROM start.payload_digest
 OR i.delivery_revision IS DISTINCT FROM d.revision OR i.receipt_digest IS DISTINCT FROM start.receipt_digest
 THEN RAISE EXCEPTION 'NOTIFICATION-START-INCOMPLETE'; END IF;
 PERFORM openpc.check_notification_delivery_dispatch_intent_original(i);
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_start_projection(before_row control.notification_delivery, after_row control.notification_delivery)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE start control.notification_delivery_start%ROWTYPE;signing control.notification_delivery_signing%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_start_atomic_owner();
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_delivery_start_original(start);
 SELECT * INTO STRICT signing FROM control.notification_delivery_signing WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND operation_id=start.operation_id;
 PERFORM openpc.check_notification_delivery_signing_current(signing);
 IF jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested) IS DISTINCT FROM start.transition->'before' OR jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested) IS DISTINCT FROM start.transition->'after'
 OR after_row.revision IS DISTINCT FROM before_row.revision+1
 OR to_jsonb(after_row)-ARRAY['state','attempt_count','last_started_at_ms','next_attempt_at_ms','revision'] IS DISTINCT FROM to_jsonb(before_row)-ARRAY['state','attempt_count','last_started_at_ms','next_attempt_at_ms','revision']
 THEN RAISE EXCEPTION 'NOTIFICATION-START-PROJECTION'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_endpoint_effect_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE receipt control.audit_occurrence%ROWTYPE; prior jsonb;
BEGIN
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.aggregate_type='notification-endpoint' AND r.aggregate_id=NEW.endpoint_id AND r.after_revision=NEW.revision;
 IF TG_OP='INSERT' THEN prior:='{}'::jsonb; ELSE prior:=openpc.notification_endpoint_business_projection(OLD); END IF;
 IF openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM prior
  OR openpc.business_cbor(receipt.after_state_preimage)->8 IS DISTINCT FROM openpc.notification_endpoint_business_projection(NEW)
  OR receipt.before_revision IS DISTINCT FROM (CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.revision END)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-EFFECT-RECEIPT'; END IF;
 PERFORM openpc.assert_notification_endpoint_receipt(receipt);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_occurrence_effect_pair()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE signing_operation uuid; key_preparation uuid; event control.outbox_event%ROWTYPE; request_payload bytea; bound_claims jsonb;
BEGIN
 IF TG_TABLE_NAME IN ('notification_source_inbox','notification_source_cursor') THEN
  IF NEW.subscription_id='SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1' THEN
   IF TG_TABLE_NAME='notification_source_inbox' THEN
    PERFORM openpc.check_notification_completion_disposition_original(NEW.event_id);
   ELSE
    PERFORM openpc.check_notification_completion_disposition_original(NEW.last_event_id);
   END IF;
   RETURN NULL;
  END IF;
 END IF;
 IF TG_TABLE_NAME IN ('notification_payload_object','notification_occurrence') THEN
  signing_operation:=NEW.creation_operation_id;
 ELSIF TG_TABLE_NAME='notification_payload' THEN
  key_preparation:=NEW.key_preparation_id;
 ELSIF TG_TABLE_NAME='notification_source_inbox' THEN
  signing_operation:=NEW.admission_operation_id;
 ELSIF TG_TABLE_NAME='notification_source_cursor' THEN
  SELECT admission_operation_id INTO STRICT signing_operation FROM control.notification_source_inbox
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND subscription_id=NEW.subscription_id AND event_id=NEW.last_event_id
  AND source=NEW.source AND partition=NEW.partition AND source_sequence=NEW.last_sequence AND data_digest=NEW.last_data_digest;
 ELSE RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-EFFECT'; END IF;
 IF key_preparation IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM control.notification_key_preparation k WHERE k.participant_id=NEW.participant_id
   AND k.privacy_domain_id=NEW.privacy_domain_id AND k.preparation_id=key_preparation AND k.payload_object_id=NEW.payload_object_id)
  THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-EFFECT-IDENTITY'; END IF;
 END IF;
 IF key_preparation IS NULL THEN
  SELECT openpc.business_cbor(o.receipt_payload) INTO STRICT bound_claims FROM control.notification_occurrence_observation o
  WHERE o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id AND o.operation_id=signing_operation;
  IF TG_TABLE_NAME='notification_payload_object' THEN
   IF bound_claims->'8' IS DISTINCT FROM openpc.business_uuid(NEW.payload_object_id) THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-EFFECT-IDENTITY'; END IF;
  ELSIF TG_TABLE_NAME='notification_occurrence' THEN
   IF bound_claims->'7' IS DISTINCT FROM openpc.business_uuid(NEW.notification_occurrence_id) THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-EFFECT-IDENTITY'; END IF;
  ELSIF TG_TABLE_NAME='notification_source_inbox' THEN
   IF bound_claims->'10' IS DISTINCT FROM openpc.business_uuid(NEW.event_id) THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-EFFECT-IDENTITY'; END IF;
  END IF;
  SELECT p.key_preparation_id INTO STRICT key_preparation FROM control.notification_occurrence_preparation p
  JOIN control.notification_occurrence_observation o USING(participant_id,privacy_domain_id,preparation_id)
  WHERE p.participant_id=NEW.participant_id AND p.privacy_domain_id=NEW.privacy_domain_id AND o.operation_id=signing_operation;
 END IF;
 SELECT o.receipt_payload INTO STRICT request_payload FROM control.notification_occurrence_preparation p
 JOIN control.notification_occurrence_observation o USING(participant_id,privacy_domain_id,preparation_id)
 WHERE p.participant_id=NEW.participant_id AND p.privacy_domain_id=NEW.privacy_domain_id
 AND p.key_preparation_id=key_preparation AND p.family='NotificationDeliveryRequestedReceiptV1' AND p.state='OBSERVED';
 SELECT * INTO STRICT event FROM control.outbox_event
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
 AND event_id=(openpc.business_cbor(request_payload)->'26'->>'bytes')::uuid;
 PERFORM openpc.check_notification_delivery_requested_event(event);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_occurrence_metadata_effect(item control.notification)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE bound_preparation_id uuid; proof control.notification_occurrence_observation%ROWTYPE; event control.outbox_event%ROWTYPE;
BEGIN
 bound_preparation_id:=openpc.notification_occurrence_metadata_preparation(item);
 SELECT r.* INTO STRICT proof FROM control.notification_occurrence_observation r
 WHERE r.participant_id=item.participant_id AND r.privacy_domain_id=item.privacy_domain_id AND r.preparation_id=bound_preparation_id;
 SELECT e.* INTO STRICT event FROM control.outbox_event e WHERE e.participant_id=item.participant_id
 AND e.privacy_domain_id=item.privacy_domain_id AND e.event_id=(openpc.business_cbor(proof.receipt_payload)->'26'->>'bytes')::uuid;
 PERFORM openpc.check_notification_delivery_requested_event(event);
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_occurrence_observation_pair()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE prep control.notification_occurrence_preparation%ROWTYPE; observation control.notification_occurrence_observation%ROWTYPE;
BEGIN
 SELECT * INTO STRICT prep FROM control.notification_occurrence_preparation WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND preparation_id=NEW.preparation_id;
