 IF r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') OR r->>'beforeDeliveryState' IS DISTINCT FROM b->>'state' OR r->>'afterDeliveryState' IS DISTINCT FROM after_state
 OR r->'attemptCount' IS DISTINCT FROM b->'attemptCount' OR (r->>'attemptLimit')::integer IS DISTINCT FROM limit_count
 OR (r->>'nextAttemptAtMs')::numeric IS DISTINCT FROM coalesce(next_ms,0) OR coalesce(next_ms,0)>9007199254740991
 OR r->>'cancelRequested' IS DISTINCT FROM (CASE WHEN (b->>'cancelRequested')::boolean THEN 'YES' ELSE 'NO' END)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-AFTER'; END IF;
 SELECT * INTO STRICT signer FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));
 IF t->'workerInstallation' IS DISTINCT FROM w.installation OR t->'signerInstallation' IS DISTINCT FROM signer.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId']
 OR signer.trust->>'purpose' IS DISTINCT FROM 'pc.cose.notification-delivery-outcome-receipt.v1'
 OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
 OR r->>'workerProfileDigest' IS DISTINCT FROM signer.trust->>'workerProfileDigest' OR r->>'routingProfileDigest' IS DISTINCT FROM 'sha256:'||(wm->'17'->>'bytes')
 OR r->>'signerKeyId' IS DISTINCT FROM signer.signer_id OR q->>'signerKeyId' IS DISTINCT FROM signer.signer_id
 OR q->>'reference' IS DISTINCT FROM signer.trust->>'secretReference' OR q->>'version' IS DISTINCT FROM signer.trust->>'secretVersion'
 OR q->>'providerId' IS DISTINCT FROM signer.trust->>'providerId' OR q->>'keyEpoch' IS DISTINCT FROM signer.trust->>'keyEpoch'
 OR q->>'workloadCredentialId' IS DISTINCT FROM signer.trust->>'workloadCredentialId' OR q->>'workloadEpoch' IS DISTINCT FROM signer.trust->>'workloadEpoch'
 OR q->>'workerInstallationDigest' IS DISTINCT FROM signer.worker_installation_digest OR q->>'workerProfileDigest' IS DISTINCT FROM signer.trust->>'workerProfileDigest'
 OR q->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY' OR q->>'environmentId' IS DISTINCT FROM signer.trust->>'environmentId'
 OR r->>'environmentId' IS DISTINCT FROM q->>'environmentId'
 OR (r->>'recordedAtMs')::numeric<(wm->>'6')::numeric OR (r->>'recordedAtMs')::numeric>=(wm->>'7')::numeric
 OR (r->>'recordedAtMs')::numeric*1000000<(signer.trust->>'validFromNs')::numeric OR (r->>'recordedAtMs')::numeric*1000000>=(signer.trust->>'validUntilNs')::numeric
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-TRUST'; END IF;
 IF item.state<>'PREPARED' AND (item.dispatched_at_ms<(r->>'recordedAtMs')::numeric OR item.dispatched_at_ms*1000000>=(signer.trust->>'validUntilNs')::numeric OR item.dispatched_at_ms>=(wm->>'7')::numeric)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-TIME'; END IF;
 IF item.state='OBSERVED' THEN
  ob:=convert_from(item.observation_bytes,'UTF8')::jsonb;
  IF item.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(ob),'UTF8') OR item.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(ob),'UTF8')),'hex')
  OR ob-ARRAY['schemaVersion','providerId','signingAttemptId','requestDigest','recordedAtMs','outcome','reason','coseHex'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(ob))<>8
  OR ob->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR ob->>'providerId' IS DISTINCT FROM q->>'providerId' OR ob->>'signingAttemptId' IS DISTINCT FROM item.signing_attempt_id::text OR ob->>'requestDigest' IS DISTINCT FROM item.request_digest
  OR jsonb_typeof(ob->'recordedAtMs') IS DISTINCT FROM 'number' OR (ob->>'recordedAtMs')::numeric NOT BETWEEN 0 AND 9007199254740991 OR trunc((ob->>'recordedAtMs')::numeric)<>(ob->>'recordedAtMs')::numeric
  THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-OBSERVATION'; END IF;
  IF ob->>'outcome'='SIGNED' THEN
   IF ob->'reason' IS DISTINCT FROM 'null'::jsonb OR ob->>'coseHex' IS NULL OR (ob->>'recordedAtMs')::numeric<item.dispatched_at_ms
    OR (ob->>'recordedAtMs')::numeric>=(wm->>'7')::numeric OR (ob->>'recordedAtMs')::numeric*1000000>=(signer.trust->>'validUntilNs')::numeric
   THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-OBSERVATION'; END IF;
   PERFORM openpc.archive_cose_binding(decode(q->>'payloadHex','hex'),decode(ob->>'coseHex','hex'),signer.signer_id,24029,366);
  ELSIF ob->>'outcome' IS DISTINCT FROM 'REJECTED' OR ob->'coseHex' IS DISTINCT FROM 'null'::jsonb
   OR (ob->>'reason' IN ('REVOKED','EXPIRED','WRONG_SCOPE','INVALID_REQUEST','ATTEMPT_CONFLICT','KEY_UNAVAILABLE')) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-OBSERVATION'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_notification_verification_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE receipt control.audit_occurrence%ROWTYPE;
BEGIN
 IF NEW.state<>'ATTACHED' THEN RETURN NEW; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
   AND r.operation_id=NEW.attached_operation_id AND r.aggregate_id=NEW.endpoint_id AND r.catalog_operation_id='CFG-OP-VERIFY-NOTIFICATION-ENDPOINT';
 IF NOT EXISTS(SELECT 1 FROM control.notification_endpoint e WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.endpoint_id=NEW.endpoint_id AND e.verification_id=NEW.attempt_id AND e.state='ACTIVE' AND e.revision=NEW.predecessor_revision+1)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ATTACHMENT-EFFECT'; END IF;
 PERFORM openpc.assert_notification_endpoint_receipt(receipt);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_signing_rotation_event(event control.outbox_event, receipt control.audit_occurrence)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE state jsonb; expected_type text; expected_schema text; effects jsonb;
BEGIN
 state:=openpc.business_cbor(receipt.after_state_preimage)->8;
 effects:=openpc.signing_transition_effects(receipt.action_intent_id,openpc.business_cbor(receipt.before_state_preimage)->8->>'0',state->>'0');
 expected_type:=effects->>'eventType';
 expected_schema:=CASE expected_type WHEN 'io.openpc.ops.secret.revoked.v1' THEN 'SecretRevoked' WHEN 'io.openpc.ops.secret.rotated.v1' THEN 'SecretRotated' END;
 IF expected_type IS NULL OR receipt.catalog_operation_id<>'OPS-OP-ADVANCE-SIGNING-KEY-ROTATION'
  OR event.event_type IS DISTINCT FROM expected_type
  OR event.data_schema_uri IS DISTINCT FROM 'https://schemas.openpc.local/event-payloads.schema.json#/$defs/'||expected_schema
  OR event.aggregate_type<>receipt.aggregate_type OR event.aggregate_id<>receipt.aggregate_id
  OR event.payload_digest<>sha256(event.payload_cbor) OR state->>'5'<>'1'
  OR openpc.business_cbor(event.payload_cbor) IS DISTINCT FROM jsonb_build_object('0',openpc.business_uuid(receipt.aggregate_id),
    '1',state->>'3','2',state->'4','3',state->'6')
 THEN RAISE EXCEPTION 'DATA-6021-LIFECYCLE-STATE-EVENT'; END IF;
END $function$

CREATE OR REPLACE FUNCTION openpc.check_workload_renewal_policy_ancestors(policy control.workload_renewal_policy, receipt control.audit_occurrence)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE snapshot jsonb:=convert_from(receipt.authority_snapshot,'UTF8')::jsonb; ancestor jsonb; bound jsonb;
 grant_row jsonb; path jsonb; expected jsonb; assignment control.assignment%ROWTYPE; delegation control.delegation%ROWTYPE;
 root uuid; prior_delegation uuid; principal_ids uuid[]; delegation_ids uuid[]; path_role_id uuid; i integer:=0; id uuid;
BEGIN
 IF jsonb_array_length(policy.business_ancestors)<>jsonb_array_length(snapshot->'authorities') THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENTS'; END IF;
 FOR ancestor IN SELECT value FROM jsonb_array_elements(policy.business_ancestors) LOOP
  bound:=snapshot->'authorities'->i;i:=i+1;grant_row:=ancestor->'grant';path:=ancestor->'dependencies'->'path';
  IF ancestor IS DISTINCT FROM jsonb_build_object('grant',grant_row,'dependencies',ancestor->'dependencies')
   OR grant_row-'catalogOperationId' IS DISTINCT FROM bound-ARRAY['sessionId','sessionEpoch']
   OR (grant_row ? 'catalogOperationId' AND grant_row->>'catalogOperationId'<>receipt.catalog_operation_id)
   OR path IS DISTINCT FROM jsonb_build_object('delegationIds',path->'delegationIds','principalIds',path->'principalIds','roleId',path->'roleId')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-BINDING'; END IF;
  SELECT * INTO STRICT assignment FROM control.assignment a WHERE a.participant_id=policy.participant_id
   AND a.assignment_id=(grant_row->>'assignmentId')::uuid;
  root:=assignment.principal_id;principal_ids:=ARRAY[root];delegation_ids:=ARRAY[]::uuid[];prior_delegation:=NULL;
  IF jsonb_typeof(path->'delegationIds') IS DISTINCT FROM 'array' OR jsonb_array_length(path->'delegationIds')>32 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  FOR id IN SELECT value::uuid FROM jsonb_array_elements_text(path->'delegationIds') LOOP
   SELECT * INTO STRICT delegation FROM control.delegation d WHERE d.participant_id=policy.participant_id AND d.delegation_id=id;
   IF id=ANY(delegation_ids) OR delegation.grantor_principal_id<>root
    OR (prior_delegation IS NULL AND (delegation.parent_assignment_id IS DISTINCT FROM assignment.assignment_id OR delegation.parent_delegation_id IS NOT NULL))
    OR (prior_delegation IS NOT NULL AND delegation.parent_delegation_id IS DISTINCT FROM prior_delegation)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-PATH'; END IF;
   delegation_ids:=delegation_ids||id;root:=delegation.delegate_principal_id;principal_ids:=principal_ids||root;prior_delegation:=id;
  END LOOP;
  SELECT r.authority_role_id INTO path_role_id FROM control.authority_role r WHERE r.participant_id=policy.participant_id AND r.role_id=assignment.role_id;
  IF root IS DISTINCT FROM (grant_row->>'principalId')::uuid OR path IS DISTINCT FROM jsonb_build_object(
   'delegationIds',to_jsonb(delegation_ids),'principalIds',to_jsonb(principal_ids),'roleId',path_role_id) THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-PATH'; END IF;
  SELECT jsonb_build_object('path',path,
   'principals',(SELECT jsonb_agg(jsonb_build_array(principal_id,authority_epoch::text) ORDER BY principal_id)
    FROM control.principal WHERE participant_id=policy.participant_id AND principal_id=ANY(principal_ids)),
   'privacy',(SELECT row_version::text FROM control.privacy_domain WHERE participant_id=policy.participant_id AND privacy_domain_id=(grant_row->>'privacyDomainId')::uuid),
   'role',(SELECT row_version::text FROM control.authority_role WHERE participant_id=policy.participant_id AND authority_role_id=path_role_id),
   'delegations',(SELECT jsonb_agg(jsonb_build_array(delegation_id,delegation_epoch::text,row_version::text) ORDER BY delegation_id)
    FROM control.delegation WHERE participant_id=policy.participant_id AND delegation_id=ANY(delegation_ids))) INTO expected;
  IF ancestor->'dependencies' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-EPOCHS'; END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION openpc.cigl_subject_current(p_participant uuid, p_subject jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control'
AS $function$
DECLARE kind text:=p_subject->>'kind'; id text:=p_subject->>'id';
BEGIN
 IF jsonb_typeof(p_subject) IS DISTINCT FROM 'object' OR (p_subject-ARRAY['kind','id']) IS DISTINCT FROM '{}'::jsonb
  OR jsonb_typeof(p_subject->'kind') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 IF kind='ANY_AUTHENTICATED' THEN RETURN p_subject='{"kind":"ANY_AUTHENTICATED"}'::jsonb; END IF;
 IF jsonb_typeof(p_subject->'id') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 IF kind IN ('ROLE','WORKLOAD') THEN
  IF (id ~ ('^urn:openpc:'||lower(kind)||':[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) IS DISTINCT FROM true THEN RETURN false; END IF;
 ELSIF (id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') IS DISTINCT FROM true THEN RETURN false; END IF;
 CASE kind
 WHEN 'ANY_AUTHENTICATED' THEN RETURN p_subject='{"kind":"ANY_AUTHENTICATED"}'::jsonb;
 WHEN 'ROLE' THEN RETURN EXISTS(SELECT 1 FROM control.authority_role WHERE participant_id=p_participant AND role_id=id AND state='ACTIVE');
 WHEN 'WORKLOAD' THEN RETURN EXISTS(SELECT 1 FROM control.credential credential
  JOIN control.principal principal ON principal.participant_id=credential.participant_id AND principal.principal_id=credential.principal_id
  WHERE credential.participant_id=p_participant AND credential.audience=id AND credential.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC')
   AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
   AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp()) AND principal.kind='WORKLOAD' AND principal.state='ACTIVE');
 WHEN 'USER' THEN RETURN EXISTS(SELECT 1 FROM control.principal principal WHERE principal.participant_id=p_participant AND principal.principal_id=id::uuid AND principal.kind='USER' AND principal.state='ACTIVE');
 WHEN 'GROUP' THEN RETURN EXISTS(SELECT 1 FROM control.authority_group WHERE participant_id=p_participant AND authority_group_id=id::uuid AND state='ACTIVE');
 WHEN 'PARTICIPANT' THEN RETURN id=p_participant::text AND EXISTS(SELECT 1 FROM control.participant WHERE participant_id=p_participant AND state='ACTIVE' AND archived_at IS NULL);
 ELSE RETURN false;
 END CASE;
END $function$

CREATE OR REPLACE FUNCTION openpc.close_fleet_delivery_lease(wanted_event uuid, wanted_lease uuid, result text, problem text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d control.fleet_fact_delivery; a control.fleet_fact_delivery_attempt; now_ms numeric; failures integer; next_state text;
BEGIN
 SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=wanted_event FOR UPDATE;
 SELECT * INTO STRICT a FROM control.fleet_fact_delivery_attempt WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id AND lease_id=wanted_lease;
 IF a.outcome<>'ACTIVE' THEN
  IF a.outcome IS DISTINCT FROM result OR a.problem IS DISTINCT FROM problem THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN d.state;
 END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF d.state<>'LEASED' OR d.lease_id IS DISTINCT FROM wanted_lease
  OR result NOT IN ('FAILED','LEASE_EXPIRED','CAPACITY_RELEASE','UNAVAILABLE_RELEASE','COMMITTED')
  OR (result='LEASE_EXPIRED' AND d.lease_until_ms>now_ms)
  OR (result<>'LEASE_EXPIRED' AND d.lease_until_ms<=now_ms)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 failures:=d.failed_attempts+CASE WHEN result IN ('FAILED','LEASE_EXPIRED') THEN 1 ELSE 0 END;
 next_state:=CASE WHEN result='COMMITTED' THEN 'COMMITTED' WHEN failures>=d.maximum_attempts THEN 'EXHAUSTED' ELSE 'WAITING' END;
 UPDATE control.fleet_fact_delivery_attempt SET outcome=result,ended_at_ms=now_ms,problem=close_fleet_delivery_lease.problem
  WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id AND lease_id=wanted_lease;
 UPDATE control.fleet_fact_delivery SET failed_attempts=failures,state=next_state,lease_id=NULL,lease_until_ms=NULL,
  next_attempt_ms=now_ms+openpc.fleet_delivery_retry_delay(failures,d.initial_backoff_ms,d.maximum_backoff_ms),last_problem=problem
  WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 RETURN next_state;
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_fleet_fact_admission(material bytea, nonce bytea, mac bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE m jsonb; e jsonb; p uuid; d uuid; c uuid; g uuid; event uuid; kind text; n numeric;
 secret bytea; expected bytea; different integer:=0; prior bytea; head numeric;

BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL
  OR current_setting('openpc.action_intent_id')<>'ACT-OPERATIONS_READ_OPERATION-V1'
  OR octet_length(material) NOT BETWEEN 1 AND 16384 OR octet_length(nonce)<>32 OR octet_length(mac)<>32

 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_FLEET_FACT_ADMISSION_V1','UTF8')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 m:=convert_from(material,'UTF8')::jsonb;
 p:=(m->>'participantId')::uuid; d:=(m->>'privacyDomainId')::uuid;
 c:=(m->>'candidateId')::uuid; g:=(m->>'generationId')::uuid;
 e:=m->'envelope'; event:=(e->>'id')::uuid; kind:=m->>'factType'; n:=(m->>'sequence')::numeric;
 IF p IS DISTINCT FROM openpc.current_participant_id() OR d IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR m IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
    'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'envelope',e,
    'factDigest',m->>'factDigest','signedFactDigest',m->>'signedFactDigest','consumerId','LS-FLEET-CONTROL')
  OR convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(m)
  OR e->>'subject' IS DISTINCT FROM 'urn:openpc:resource:'||c::text
  OR e->>'participantid' IS DISTINCT FROM 'urn:openpc:participant:'||p::text
  OR e->>'privacydomainid' IS DISTINCT FROM 'urn:openpc:privacy-domain:'||d::text
  OR e->>'source' IS DISTINCT FROM 'urn:openpc:service:LS-FACT-BRIDGE'
  OR e->>'type' IS DISTINCT FROM 'io.openpc.fact.candidate.admitted.v1'
  OR e->>'sequence' IS DISTINCT FROM n::text
 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-BINDING'; END IF;

 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type)
  VALUES(p,d,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor
  WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind FOR UPDATE;
 SELECT i.material INTO prior FROM control.fleet_fact_admission_inbox i
  WHERE i.participant_id=p AND i.privacy_domain_id=d AND i.event_id=event;
 IF FOUND THEN
  IF prior<>material THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
  RETURN false;
 END IF;
 RAISE EXCEPTION 'PC-AUTH-0005'; -- V1 remains exact historical replay only.
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 INSERT INTO control.fleet_fact_admission_inbox(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,
  fact_type,sequence,fact_digest,signed_fact_digest,material,material_digest,commit_nonce,consumer_profile_digest)
 VALUES(p,d,event,c,g,kind,n,m->>'factDigest',m->>'signedFactDigest',material,sha256(material),nonce,NULL);
 UPDATE control.fleet_fact_admission_cursor SET sequence=n WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_fleet_fact_admission_v2(material bytea, nonce bytea, mac bytea, wanted_profile text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE m jsonb; e jsonb; p uuid; d uuid; c uuid; g uuid; event uuid; kind text; n numeric;
 secret bytea; expected bytea; different integer:=0; prior bytea; head numeric;
 installed control.fact_consumer_profile; pending control.fleet_fact_delivery; expected_pending jsonb; lease uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL
  OR current_setting('openpc.action_intent_id')<>'ACT-OPERATIONS_READ_OPERATION-V1'
  OR octet_length(material) NOT BETWEEN 1 AND 16384 OR octet_length(nonce)<>32 OR octet_length(mac)<>32
  OR coalesce(wanted_profile,'')!~'^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_FLEET_FACT_ADMISSION_V2','UTF8')||decode(substring(wanted_profile from 8),'hex')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 m:=convert_from(material,'UTF8')::jsonb;
 p:=(m->>'participantId')::uuid; d:=(m->>'privacyDomainId')::uuid;
 c:=(m->>'candidateId')::uuid; g:=(m->>'generationId')::uuid;
 e:=m->'envelope'; event:=(e->>'id')::uuid; kind:=m->>'factType'; n:=(m->>'sequence')::numeric;
 IF p IS DISTINCT FROM openpc.current_participant_id() OR d IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR m IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
    'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'envelope',e,
    'factDigest',m->>'factDigest','signedFactDigest',m->>'signedFactDigest','consumerId','LS-FLEET-CONTROL')
  OR convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(m)
  OR e->>'subject' IS DISTINCT FROM 'urn:openpc:resource:'||c::text
  OR e->>'participantid' IS DISTINCT FROM 'urn:openpc:participant:'||p::text
  OR e->>'privacydomainid' IS DISTINCT FROM 'urn:openpc:privacy-domain:'||d::text
  OR e->>'source' IS DISTINCT FROM 'urn:openpc:service:LS-FACT-BRIDGE'
  OR e->>'type' IS DISTINCT FROM 'io.openpc.fact.candidate.admitted.v1'
  OR e->>'sequence' IS DISTINCT FROM n::text
 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-BINDING'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('fact-consumer-profile:'||p::text||':'||d::text||':LS-FLEET-CONTROL',0));
 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type)
  VALUES(p,d,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor
  WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind FOR UPDATE;
 SELECT i.material INTO prior FROM control.fleet_fact_admission_inbox i
  WHERE i.participant_id=p AND i.privacy_domain_id=d AND i.event_id=event;
 IF FOUND THEN
  IF prior<>material THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
  RETURN false;
 END IF;
 installed:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF installed.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 lease:=encode(substring(nonce from 1 for 16),'hex')::uuid;
 SELECT * INTO STRICT pending FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=d AND event_id=event FOR UPDATE;
 expected_pending:=jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,'eventId',event::text,
  'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'consumerId','LS-FLEET-CONTROL',
  'envelope',e,'envelopeDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e),'UTF8')),'hex'),
  'dataDigest',e->>'datadigest');
 IF pending.state<>'LEASED' OR pending.lease_id IS DISTINCT FROM lease
  OR convert_from(pending.material,'UTF8')::jsonb IS DISTINCT FROM expected_pending
  OR NOT EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=p AND a.privacy_domain_id=d
   AND a.event_id=event AND a.lease_id=lease AND a.profile_digest=wanted_profile AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.close_fleet_delivery_lease(event,lease,'COMMITTED',NULL);
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 INSERT INTO control.fleet_fact_admission_inbox(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,
  fact_type,sequence,fact_digest,signed_fact_digest,material,material_digest,commit_nonce,consumer_profile_digest)
 VALUES(p,d,event,c,g,kind,n,m->>'factDigest',m->>'signedFactDigest',material,sha256(material),nonce,wanted_profile);
 UPDATE control.fleet_fact_admission_cursor SET sequence=n WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_fleet_fact_quarantine(material bytea, nonce bytea, mac bytea, wanted_profile text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE request jsonb; q control.fleet_fact_quarantine; d control.fleet_fact_delivery;
 profile control.fact_consumer_profile; signer control.fact_consumer_failure_signer;
 c jsonb; expected jsonb; signed_payload bytea; signed_cose bytea; now_ms numeric;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_FAILURE_COMMIT_V1');
 IF request IS DISTINCT FROM jsonb_build_object('participantId',openpc.current_participant_id()::text,
  'privacyDomainId',openpc.current_privacy_domain_id()::text,'eventId',(request->>'eventId')::uuid::text,
  'payload',request->>'payload','cose',request->>'cose')
  OR coalesce(request->>'payload','')!~'^[0-9a-f]+$' OR coalesce(request->>'cose','')!~'^[0-9a-f]+$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 signed_payload:=decode(request->>'payload','hex'); signed_cose:=decode(request->>'cose','hex');
 SELECT * INTO d FROM control.fleet_fact_delivery WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=(request->>'eventId')::uuid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO q FROM control.fleet_fact_quarantine WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF q.state='COMMITTED' THEN
  IF d.state<>'QUARANTINED' OR q.payload IS DISTINCT FROM signed_payload OR q.cose IS DISTINCT FROM signed_cose
   OR q.claims->>'currentProfileDigest' IS DISTINCT FROM wanted_profile
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN q.work_item_id;
 END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 c:=q.claims; signer:=openpc.require_fact_failure_signer(profile,c->>'signerKeyId');
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF q.state<>'PREPARED' OR d.state<>'EXHAUSTED' OR q.material_digest<>d.material_digest
  OR profile.profile_digest IS DISTINCT FROM wanted_profile OR c->>'currentProfileDigest' IS DISTINCT FROM wanted_profile
  OR c->>'workloadCredentialId' IS DISTINCT FROM profile.workload_credential_id::text
  OR c->>'workloadCredentialEpoch' IS DISTINCT FROM profile.workload_credential_epoch::text
  OR c->>'failedAttempts' IS DISTINCT FROM d.failed_attempts::text OR c->>'maximumAttempts' IS DISTINCT FROM d.maximum_attempts::text
  OR c->>'leaseGeneration' IS DISTINCT FROM d.lease_generation::text OR d.lease_id IS NOT NULL
  OR d.failed_attempts<>d.maximum_attempts OR d.last_problem IS DISTINCT FROM 'PC-DATA-6005'
  OR (c->>'recordedAtMs')::numeric>now_ms OR now_ms-(c->>'recordedAtMs')::numeric>30000
  OR (c->>'recordedAtMs')::numeric<signer.valid_from_ms
  OR EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=d.participant_id
   AND a.privacy_domain_id=d.privacy_domain_id AND a.event_id=d.event_id AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object(
  '0',openpc.business_bytes(decode('b9d6f05813ff518d1cbc05ff0cd9a55c9729035bce9f9f8446a914d2098bfbea','hex')),
  '1',c->'environmentId',
  '2',openpc.business_uuid(q.participant_id),
  '3',openpc.business_uuid(q.privacy_domain_id),
  '4',c->'consumerId',
  '5',c->'subscriptionId',
  '6',openpc.business_uuid((c->>'eventId')::uuid),
  '7',openpc.business_uuid((c->>'candidateId')::uuid),
  '8',openpc.business_uuid((c->>'generationId')::uuid),
  '9',c->'factType',
  '10',(c->>'sequence')::numeric,
  '11',openpc.business_bytes(decode(substring(c->>'envelopeDigest' from 8),'hex')),
  '12',openpc.business_bytes(decode(substring(c->>'dataDigest' from 8),'hex')),
  '13',openpc.business_bytes(decode(substring(c->>'materialDigest' from 8),'hex')),
  '14',openpc.business_bytes(decode(substring(c->>'initialProfileDigest' from 8),'hex')),
  '15',openpc.business_bytes(decode(substring(c->>'currentProfileDigest' from 8),'hex')),
  '16',(c->>'failedAttempts')::numeric,
  '17',(c->>'maximumAttempts')::numeric,
  '18',(c->>'leaseGeneration')::numeric,
  '19',openpc.business_uuid((c->>'workloadCredentialId')::uuid),
  '20',(c->>'workloadCredentialEpoch')::numeric,
  '21',openpc.business_uuid((c->>'workloadPrincipalId')::uuid),
  '22',openpc.business_uuid(q.work_item_id),
  '23','PC-DATA-6005',
  '24',(c->>'recordedAtMs')::numeric,
  '25',openpc.business_bytes(sha256(signer.public_key_spki)),
  '26',openpc.business_uuid(q.receipt_id));
 IF openpc.business_cbor(signed_payload) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(signed_payload,signed_cose,signer.signer_key_id,24007,344);
 INSERT INTO control.work_item(work_item_id,participant_id,privacy_domain_id,kind,state,resource_ref,payload_digest,reason,created_by_principal_id,row_version)
 VALUES(q.work_item_id,q.participant_id,q.privacy_domain_id,'FLEET_FAILURE','OPEN','urn:openpc:resource:'||d.candidate_id::text,
   d.material_digest,'Fact delivery quarantined (PC-DATA-6005).',(c->>'workloadPrincipalId')::uuid,1);
 UPDATE control.fleet_fact_quarantine SET state='COMMITTED',payload=signed_payload,
  cose=signed_cose,receipt_digest='sha256:'||encode(sha256(signed_cose),'hex'),
  signer_key_id=signer.signer_key_id,committed_at_ms=now_ms
 WHERE participant_id=q.participant_id AND privacy_domain_id=q.privacy_domain_id AND event_id=q.event_id;
 INSERT INTO control.fleet_fact_failure_outbox(participant_id,privacy_domain_id,receipt_id,receipt_digest)
 VALUES(q.participant_id,q.privacy_domain_id,q.receipt_id,'sha256:'||encode(sha256(signed_cose),'hex'));
 UPDATE control.fleet_fact_delivery SET state='QUARANTINED' WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 -- Time can expire while signing; the same current workload/profile and signer
 -- are checked after effects and before this atomic transaction can succeed.
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 PERFORM openpc.require_fact_failure_signer(profile,signer.signer_key_id);
 RETURN q.work_item_id;
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_platform_scope_replacement(document jsonb, candidate_id uuid, approval_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE r control.platform_scope_replacement; initial control.platform_envelope_scope; current_root control.platform_context; readiness jsonb; queued record;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||(document->>'platformContextId'),0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=(document->>'replacementId')::uuid
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() FOR UPDATE;
 SELECT * INTO STRICT current_root FROM control.platform_context p WHERE p.platform_context_id=r.platform_context_id
  AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE' FOR UPDATE;
 FOR queued IN SELECT q.runtime_target_id FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
  AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id ORDER BY q.runtime_target_id LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||r.participant_id::text||':'||r.privacy_domain_id::text||':'||queued.runtime_target_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 readiness:=openpc.read_platform_scope_replacement_readiness(r.replacement_id);
 IF coalesce((document->>'platformContextId'<>readiness->>'platformContextId'
   OR document->>'expectedRootRevision'<>readiness->>'rootRevision'
   OR document->>'expectedReplacementRevision'<>readiness->>'replacementRevision'
   OR document->>'predecessorEpoch'<>readiness->>'predecessorEpoch'
   OR document->>'predecessorDigest'<>readiness->>'predecessorDigest'
   OR document->>'successorDigest'<>readiness->>'successorDigest' OR document->>'readinessDigest'<>readiness->>'readinessDigest'
   OR readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
   OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric),true)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
 SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=r.platform_context_id;
 UPDATE control.platform_scope_replacement SET state='COMMITTED',row_version=2,commit_operation_id=openpc.current_operation_id(),
  commit_candidate_id=candidate_id,commit_approval_id=approval_id,readiness_digest=decode(substring(document->>'readinessDigest' from 8),'hex'),
  committed_at=clock_timestamp() WHERE replacement_id=r.replacement_id;
 INSERT INTO control.platform_envelope_scope_successor(platform_context_id,platform_authority_epoch,owner_participant_id,installation_privacy_domain_id,
  replacement_id,preparation_operation_id,predecessor_epoch,predecessor_digest,environment_id,installation_digest,scope_cbor,admission_preimage,admission_digest)
 VALUES(r.platform_context_id,r.predecessor_epoch+1,r.participant_id,r.privacy_domain_id,r.replacement_id,r.prepare_operation_id,
  r.predecessor_epoch,r.predecessor_digest,initial.environment_id,initial.installation_digest,r.successor_scope_cbor,r.successor_preimage,r.successor_digest);
 UPDATE control.platform_context SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE platform_context_id=r.platform_context_id AND authority_epoch=r.predecessor_epoch AND row_version=r.expected_root_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
 RETURN jsonb_build_object('replacementId',r.replacement_id::text,'successorDigest','sha256:'||encode(r.successor_digest,'hex'),
  'state','COMMITTED','revision','2','operationId',openpc.current_operation_id()::text,'platformAuthorityEpoch',(r.predecessor_epoch+1)::text);
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_root_expiry_recovery(p_recovery uuid, p_activation uuid, p_scope bytea, p_preimage bytea, p_evidence bytea, p_digest bytea, p_cose bytea, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'control'
 SET row_security TO 'on'
AS $function$
DECLARE c control.root_expiry_recovery_case; e control.root_expiry_recovery_enrollment; root control.platform_context;
 original_scope bytea; original_digest bytea; original jsonb; successor jsonb; base jsonb; expected jsonb; actual_result jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 PERFORM 1 FROM control.participant WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 SELECT * INTO STRICT c FROM control.root_expiry_recovery_case WHERE recovery_id=p_recovery
  AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) FOR UPDATE;
 SELECT * INTO STRICT e FROM openpc.lock_root_expiry_recovery_enrollment(c.enrollment_id);
 SELECT * INTO STRICT root FROM control.platform_context WHERE platform_context_id=e.platform_context_id FOR UPDATE;
 IF c.state<>'REQUESTED' OR c.valid_until<=clock_timestamp() OR NOT openpc.root_expiry_recovery_source_current(e.enrollment_id)
  OR NOT openpc.root_expiry_recovery_proofs_current(c,p_activation) OR openpc.root_expiry_recovery_executor_has_grants(e.enrollment_id)
  OR root.authority_epoch::text<>c.intent->>'predecessorEpoch' OR root.row_version::text<>c.intent->>'predecessorRevision'
  OR p_digest IS DISTINCT FROM sha256(p_evidence) OR octet_length(p_cose)=0 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 SELECT s.scope_cbor,s.admission_digest INTO STRICT original_scope,original_digest FROM (
  SELECT platform_context_id,platform_authority_epoch,scope_cbor,admission_digest FROM control.platform_envelope_scope
  UNION ALL SELECT platform_context_id,platform_authority_epoch,scope_cbor,admission_digest FROM control.platform_envelope_scope_successor
  UNION ALL SELECT platform_context_id,platform_authority_epoch,scope_cbor,admission_digest FROM control.root_expiry_recovery_scope
 ) s WHERE s.platform_context_id=root.platform_context_id AND s.platform_authority_epoch=root.authority_epoch;
 original:=openpc.business_cbor(original_scope); successor:=openpc.business_cbor(p_scope);
 IF NOT openpc.identity_envelope_scope_valid(p_scope) OR (successor-ARRAY['3','4']) IS DISTINCT FROM (original-ARRAY['3','4'])
  OR (original->>'4')::numeric>floor(extract(epoch from clock_timestamp())*1000000000)
  OR (successor->>'3')::numeric<(original->>'4')::numeric
  OR (successor->>'3')::numeric>floor(extract(epoch from clock_timestamp())*1000000000)
  OR (successor->>'4')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)
  OR (successor->>'4')::numeric-(successor->>'3')::numeric>((original->>'4')::numeric-(original->>'3')::numeric)*(CASE WHEN e.document->>'qaDurationProfile'='LOCAL_QA_10X' THEN 10 ELSE 1 END)
  OR (successor->>'4')::numeric-(successor->>'3')::numeric>86400000000000*(CASE WHEN e.document->>'qaDurationProfile'='LOCAL_QA_10X' THEN 10 ELSE 1 END)
  OR (successor->>'3')::numeric<>extract(epoch from (e.document->>'successorValidFrom')::timestamptz)*1000000000
  OR (successor->>'4')::numeric<>extract(epoch from (e.document->>'successorValidUntil')::timestamptz)*1000000000
  OR c.intent->'successorScope' IS DISTINCT FROM openpc.platform_scope_document(p_scope)
  OR 'sha256:'||encode(original_digest,'hex')<>c.intent->>'predecessorDigest'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-BOUNDS'; END IF;
 base:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
  openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
  openpc.business_uuid(root.platform_context_id),openpc.business_uuid(root.owner_participant_id),
  openpc.business_uuid(e.privacy_domain_id),root.authority_epoch+1,e.document->>'installationEnvironmentId',
  openpc.business_bytes(decode(substring(e.document->>'installationDigest' from 8),'hex')),openpc.business_bytes(p_scope));
 expected:=openpc.business_cbor(p_preimage);
 IF jsonb_typeof(expected) IS DISTINCT FROM 'array' OR jsonb_array_length(expected)<>9
  OR expected->>0 IS DISTINCT FROM 'pc.identity.platform-envelope-scope.local-expiry-recovery.v1' OR expected->>1 IS DISTINCT FROM '1'
  OR expected->2 IS DISTINCT FROM openpc.business_uuid(c.recovery_id)
  OR expected->3 IS DISTINCT FROM openpc.business_uuid(openpc.current_operation_id())
  OR expected->4 IS DISTINCT FROM openpc.business_bytes(c.enrollment_digest)
  OR expected->5 IS DISTINCT FROM openpc.business_bytes(c.intent_digest)
  OR expected->>6 IS DISTINCT FROM root.authority_epoch::text
  OR expected->7 IS DISTINCT FROM openpc.business_bytes(original_digest)
  OR openpc.business_cbor(decode(expected#>>'{8,bytes}','hex')) IS DISTINCT FROM base
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-BYTES'; END IF;
 actual_result:=jsonb_build_object('rootEpoch',(root.authority_epoch+1)::text,'rootRevision',(root.row_version+1)::text,
  'rootDigest','sha256:'||encode(sha256(p_preimage),'hex'),'operationId',openpc.current_operation_id()::text);
 IF p_result IS DISTINCT FROM actual_result THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-RESULT'; END IF;
 INSERT INTO control.root_expiry_recovery_scope(platform_context_id,platform_authority_epoch,recovery_id,activation_operation_id,
  enrollment_digest,intent_digest,predecessor_epoch,predecessor_digest,owner_participant_id,installation_privacy_domain_id,
  environment_id,installation_digest,scope_cbor,admission_preimage,admission_digest)
 VALUES(root.platform_context_id,root.authority_epoch+1,c.recovery_id,openpc.current_operation_id(),c.enrollment_digest,c.intent_digest,
  root.authority_epoch,original_digest,root.owner_participant_id,e.privacy_domain_id,e.document->>'installationEnvironmentId',e.document->>'installationDigest',
  p_scope,p_preimage,sha256(p_preimage));
 UPDATE control.platform_context SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE platform_context_id=root.platform_context_id AND authority_epoch=root.authority_epoch AND row_version=root.row_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-FENCE'; END IF;
 UPDATE control.root_expiry_recovery_case SET state='COMPLETED',row_version=row_version+1,updated_at=clock_timestamp(),
  result=actual_result,operation_id=openpc.current_operation_id(),evidence_cbor=p_evidence,evidence_digest=p_digest,evidence_cose=p_cose
 WHERE recovery_id=c.recovery_id AND state='REQUESTED';
 INSERT INTO control.outbox_aggregate_head(participant_id,aggregate_type,aggregate_id,last_sequence) VALUES(c.participant_id,'local-root-expiry-recovery',c.recovery_id,1);
 INSERT INTO control.outbox_event(participant_id,privacy_domain_id,aggregate_type,aggregate_id,aggregate_sequence,event_id,event_type,
  payload_cbor,payload_digest,cose_sign1,occurred_at) VALUES(c.participant_id,c.privacy_domain_id,'local-root-expiry-recovery',c.recovery_id,1,
  openpc.current_operation_id(),'openpc.identity.local-root-expiry-recovery.completed.v1',p_evidence,p_digest,p_cose,clock_timestamp());
 RETURN actual_result;
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_runtime_artifact_source_denial(wanted uuid, wire bytea, nonce bytea, mac bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a control.runtime_artifact_source_disposition; retained bytea; claims jsonb;
BEGIN
 PERFORM openpc.lock_runtime_artifact_source_custody();
 SELECT * INTO STRICT a FROM control.runtime_artifact_source_disposition WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND disposition_id=wanted AND xmin<>pg_current_xact_id()::xid;
 PERFORM openpc.runtime_artifact_source_admission(a);
 PERFORM openpc.verify_runtime_artifact_source_commit(a.source_owner_id,wire,nonce,mac);
 SELECT signed_denial INTO retained FROM control.runtime_artifact_source_denial WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND disposition_id=a.disposition_id;
 IF FOUND THEN
  IF retained IS DISTINCT FROM wire THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-CUSTODY'; END IF;
  RETURN;
 END IF;
 claims:=convert_from(wire,'UTF8')::jsonb->'claims';
 INSERT INTO control.runtime_artifact_source_denial(participant_id,privacy_domain_id,source_owner_id,disposition_id,
  sequence,previous_denial_digest,signed_denial,denial_digest,verification_nonce,verification_mac)
 VALUES(a.participant_id,a.privacy_domain_id,a.source_owner_id,a.disposition_id,(claims->>'sequence')::numeric,
  decode(claims->>'previous_denial_digest','hex'),wire,sha256(wire),nonce,mac);
END $function$

CREATE OR REPLACE FUNCTION openpc.commit_runtime_target_disposition(kind text, wire bytea, nonce bytea, mac bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE envelope jsonb; receipt_claims jsonb; identity jsonb; pid uuid; privacy uuid; target uuid; principal uuid;
 secret bytea; expected bytea; different integer:=0; wire_digest text; prior bytea; wanted_revision bigint;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 authority record; previous_sequence numeric;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR kind IS NULL OR kind NOT IN ('DELIVERY','ACK') OR wire IS NULL OR octet_length(wire) NOT BETWEEN 1 AND 16384
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_'||kind||'_V1','UTF8')||sha256(wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 envelope:=convert_from(wire,'UTF8')::jsonb; receipt_claims:=envelope->'claims'; identity:=receipt_claims->'target';
 IF envelope->>'purpose' IS DISTINCT FROM (CASE kind WHEN 'DELIVERY' THEN 'openpc:target-disposition-delivery:v1'
   ELSE 'openpc:target-disposition-acknowledgement:v1' END)
  OR envelope IS DISTINCT FROM jsonb_build_object('purpose',envelope->'purpose','claims',receipt_claims,
   'claims_digest',envelope->'claims_digest','signature_p1363_hex',envelope->'signature_p1363_hex')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 pid:=(identity->>'participant_id')::uuid; privacy:=(identity->>'privacy_domain_id')::uuid; target:=(identity->>'target_id')::uuid;
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR target IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,'sha256:'||(identity->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF identity IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,'target_id',target::text,
  'credential_id',authority.credential_id::text,'principal_id',principal::text,'credential_epoch',authority.credential_epoch,
  'principal_epoch',authority.principal_epoch,'certificate_digest',identity->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 wire_digest:='sha256:'||encode(sha256(wire),'hex');
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF kind='DELIVERY' THEN
  wanted_revision:=(receipt_claims->>'revision')::bigint;
  SELECT d.signed_delivery INTO prior FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=wanted_revision;
  IF FOUND THEN
   IF prior IS DISTINCT FROM wire THEN RAISE EXCEPTION 'TARGET-DISPOSITION-REPLAY-CONFLICT'; END IF;
   RETURN false;
  END IF;
  IF wanted_revision<>head.revision OR receipt_claims IS DISTINCT FROM
   head.binding||jsonb_build_object('committed_admission_digest',substring(head.admission_digest from 8))
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ADMISSION'; END IF;
  INSERT INTO control.runtime_target_disposition_delivery(participant_id,privacy_domain_id,runtime_target_id,revision,
   predecessor_digest,claims,signed_delivery,delivery_digest)
  VALUES(pid,privacy,target,wanted_revision,CASE WHEN receipt_claims->>'previous_delivery_digest' IS NULL THEN NULL
   ELSE 'sha256:'||(receipt_claims->>'previous_delivery_digest') END,receipt_claims,wire,wire_digest);
 ELSE
  wanted_revision:=(receipt_claims->>'disposition_revision')::bigint;
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
    AND d.delivery_digest='sha256:'||(receipt_claims->>'delivery_digest') AND d.revision=wanted_revision;
  IF receipt_claims IS DISTINCT FROM jsonb_build_object('version',1,'target',delivery.claims->'target',
   'delivery_digest',substring(delivery.delivery_digest from 8),'disposition_revision',delivery.revision,
   'journal_sequence',receipt_claims->'journal_sequence','installed_state',(CASE delivery.claims->>'action'
    WHEN 'Withdraw' THEN 'NewUseDenied' WHEN 'Restore' THEN 'SuspensionCleared' WHEN 'ConfirmActivation' THEN 'ActivationConfirmed' END))
   OR jsonb_typeof(receipt_claims->'journal_sequence') IS DISTINCT FROM 'number'
   OR (receipt_claims->>'journal_sequence')::numeric NOT BETWEEN 1 AND 9223372036854775807
   OR (receipt_claims->>'journal_sequence')::numeric<>trunc((receipt_claims->>'journal_sequence')::numeric)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-BINDING'; END IF;
  SELECT a.signed_acknowledgement INTO prior FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest;
  IF FOUND THEN
   IF prior IS DISTINCT FROM wire THEN RAISE EXCEPTION 'TARGET-DISPOSITION-REPLAY-CONFLICT'; END IF;
   RETURN false;
  END IF;
  IF wanted_revision<>head.revision THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
  SELECT max((a.claims->>'journal_sequence')::numeric) INTO previous_sequence
   FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target;
  IF (receipt_claims->>'journal_sequence')::numeric<=coalesce(previous_sequence,0)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-JOURNAL-ROLLBACK'; END IF;
  INSERT INTO control.runtime_target_disposition_acknowledgement(participant_id,privacy_domain_id,runtime_target_id,
   delivery_digest,claims,signed_acknowledgement,acknowledgement_digest)
  VALUES(pid,privacy,target,delivery.delivery_digest,receipt_claims,wire,wire_digest);
 END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION openpc.complete_archive_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE receipt control.evidence_archive_receipt;
BEGIN
 SELECT * INTO STRICT receipt FROM control.evidence_archive_receipt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 PERFORM openpc.require_archive_profile(receipt.profile_digest,openpc.business_cbor(receipt.payload)->>'19');
 PERFORM openpc.require_archive_commit_nonce(receipt);
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_outbox o WHERE o.participant_id=receipt.participant_id
  AND o.privacy_domain_id=receipt.privacy_domain_id AND o.receipt_id=receipt.receipt_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.complete_notification_completion_remediation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE event uuid;
BEGIN
 SELECT event_id INTO STRICT event FROM control.notification_completion_disposition WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.work_item_id;
 PERFORM openpc.check_notification_completion_disposition_original(event);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.complete_notification_completion_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c integer;first_attempt jsonb;
BEGIN
 SELECT count(*) INTO c FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT attempt INTO STRICT first_attempt FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id AND number=1;
 IF c<1 OR first_attempt->>'workerInstallationDigest' IS DISTINCT FROM NEW.initial_worker_installation_digest THEN RAISE EXCEPTION 'COMPLETION-SOURCE-FIRST-ATTEMPT'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.configuration_policy_provenance(pid uuid, privacy uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE selected text; cardinality bigint;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'DATA-6001-CONTEXT-INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0));
 SELECT count(*),min('sha256:'||encode(generation_digest,'hex')) INTO cardinality,selected
 FROM control.policy_generation WHERE participant_id=pid AND privacy_domain_id=privacy AND active AND state='ACTIVE';
 IF cardinality=1 THEN RETURN selected; END IF;
 IF cardinality<>0 THEN RAISE EXCEPTION 'DATA-6007-CONFIGURATION-POLICY-UNAVAILABLE'; END IF;
 -- A published generation can require fresh provider preparation before its
 -- first activation. Bind that preparation to the sole approved generation,
 -- never to an arbitrary or failed generation.
 SELECT count(*),min('sha256:'||encode(g.generation_digest,'hex')) INTO cardinality,selected
 FROM control.policy_generation g
 JOIN control.policy_release_bundle r ON r.participant_id=g.participant_id
  AND r.privacy_domain_id=g.privacy_domain_id
  AND r.policy_version_id=g.policy_version_id
  AND r.approval_request_id=g.approval_request_id
  AND r.manifest_digest=g.generation_digest
  AND r.state IN ('PUBLISHED','STAGED')
 WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
  AND g.state='PREPARED' AND NOT g.active;
 IF cardinality=1 THEN RETURN selected; END IF;
 IF cardinality<>0 OR EXISTS(SELECT 1 FROM control.policy_generation WHERE participant_id=pid AND privacy_domain_id=privacy)
 THEN RAISE EXCEPTION 'DATA-6007-CONFIGURATION-POLICY-UNAVAILABLE'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.current_action_intent_id()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE value text;
BEGIN
  value := current_setting('openpc.action_intent_id', true);
  IF value IS NULL OR value !~ '^ACT-[A-Z][A-Z0-9_]*-V[1-9][0-9]*$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6001-CONTEXT-INVALID', DETAIL = 'openpc.action_intent_id';
  END IF;
  RETURN value;
END $function$

CREATE OR REPLACE FUNCTION openpc.current_notification_delivery_limit(p_environment text)
 RETURNS TABLE(generation_id uuid, effective_digest text, configured_limit integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE installed control.operations_installation%ROWTYPE; accepted control.operations_generation_commit%ROWTYPE;
 candidate control.operations_generation%ROWTYPE;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('operations-generation:'||p_environment,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO installed FROM control.operations_installation i WHERE i.environment_id=p_environment FOR SHARE;
 IF installed.environment_id IS NULL OR installed.state<>'ACTIVE' THEN RAISE EXCEPTION 'OPS_CONFIG_UNREADY'; END IF;
 SELECT * INTO accepted FROM control.operations_generation_commit c WHERE c.environment_id=p_environment ORDER BY c.sequence DESC LIMIT 1;
 IF accepted.generation_id IS NULL THEN RAISE EXCEPTION 'OPS_CONFIG_UNREADY'; END IF;
 SELECT * INTO STRICT candidate FROM control.operations_generation g WHERE g.environment_id=p_environment AND g.generation_id=accepted.generation_id FOR SHARE;
 IF candidate.state<>'STAGED' OR openpc.operations_generation_missing(p_environment,accepted.generation_id)<>'[]'::jsonb
 THEN RAISE EXCEPTION 'OPS_CONFIG_UNREADY'; END IF;
 generation_id:=accepted.generation_id; effective_digest:=accepted.effective_digest;
 configured_limit:=(candidate.candidate->'configuration'->'settings'->>'operations.notification_delivery_limit')::integer;
 IF configured_limit IS NULL OR configured_limit<0 OR configured_limit>100 THEN RAISE EXCEPTION 'OPS_CONFIG_INVALID'; END IF;
 RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION openpc.discovery_approval_resume_enrollments_compatible(p_old uuid, p_new uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'control'
 SET row_security TO 'on'
AS $function$
DECLARE old_e control.platform_recovery_enrollment; new_e control.platform_recovery_enrollment;
 old_source jsonb; new_source jsonb; old_refs jsonb; new_refs jsonb; suffix jsonb; reference jsonb;
 delta integer; i integer; receipt record; previous_document jsonb; runtime_scope jsonb;
BEGIN
 SELECT * INTO old_e FROM control.platform_recovery_enrollment WHERE enrollment_id=p_old;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO new_e FROM control.platform_recovery_enrollment WHERE enrollment_id=p_new;
 IF NOT FOUND THEN RETURN false; END IF;
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NOT openpc.matches_participant(new_e.participant_id) OR NOT openpc.matches_privacy(new_e.privacy_domain_id)
  OR row(new_e.participant_id,new_e.privacy_domain_id,new_e.platform_context_id,new_e.source_purpose)
    IS DISTINCT FROM row(old_e.participant_id,old_e.privacy_domain_id,old_e.platform_context_id,old_e.source_purpose)
  OR old_e.source_purpose IS DISTINCT FROM 'ROOT_EXPIRY_RECOVERY'
  OR old_e.document->>'schema' IS DISTINCT FROM 'pc.identity.discovery-certificate-recovery-enrollment'
  OR new_e.document->>'schema' IS DISTINCT FROM old_e.document->>'schema'
  OR old_e.document->>'schemaVersion' IS DISTINCT FROM '2' OR new_e.document->>'schemaVersion' IS DISTINCT FROM '2'
  OR old_e.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  OR new_e.document->>'assurance' IS DISTINCT FROM old_e.document->>'assurance'
  OR new_e.document->'certificateRecovery' IS DISTINCT FROM old_e.document->'certificateRecovery'
  OR new_e.document->'administratorPrincipalIds' IS DISTINCT FROM old_e.document->'administratorPrincipalIds'
  OR new_e.document_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(new_e.document),'UTF8'))
  OR old_e.document_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(old_e.document),'UTF8'))
  OR new_e.state IS DISTINCT FROM 'ACTIVE' OR new_e.row_version<>1
  OR new_e.valid_from>clock_timestamp() OR new_e.valid_until<=clock_timestamp()
  OR openpc.platform_recovery_source_root_current(new_e) IS DISTINCT FROM true
 THEN RETURN false; END IF;
 old_source:=old_e.document->'source'; new_source:=new_e.document->'source';
 IF row(new_e.root_epoch,new_e.root_revision,new_e.root_digest)=row(old_e.root_epoch,old_e.root_revision,old_e.root_digest)
 THEN RETURN openpc.discovery_approval_resume_source_compatible(old_source,new_source); END IF;
 IF new_e.root_epoch<=old_e.root_epoch OR new_e.root_epoch-old_e.root_epoch>31
  OR new_e.root_revision-old_e.root_revision IS DISTINCT FROM new_e.root_epoch-old_e.root_epoch
  OR jsonb_typeof(old_source) IS DISTINCT FROM 'object' OR jsonb_typeof(new_source) IS DISTINCT FROM 'object'
  OR old_source->>'kind' IS DISTINCT FROM 'ROOT_EXPIRY_RECOVERY' OR new_source->>'kind' IS DISTINCT FROM old_source->>'kind'
  OR (new_source-ARRAY['recoveryId','enrollmentId','activationOperationId','receiptDigest','ancestorReceipts','originalAdministrators'])
    IS DISTINCT FROM (old_source-ARRAY['recoveryId','enrollmentId','activationOperationId','receiptDigest','ancestorReceipts','originalAdministrators'])
  OR openpc.discovery_approval_resume_source_compatible(old_source,
    old_source||jsonb_build_object('originalAdministrators',new_source->'originalAdministrators')) IS DISTINCT FROM true
 THEN RETURN false; END IF;
 delta:=(new_e.root_epoch-old_e.root_epoch)::integer;
 old_refs:=jsonb_build_array(old_source-ARRAY['kind','originalAdministrators','ancestorReceipts'])||coalesce(old_source->'ancestorReceipts','[]'::jsonb);
 new_refs:=jsonb_build_array(new_source-ARRAY['kind','originalAdministrators','ancestorReceipts'])||coalesce(new_source->'ancestorReceipts','[]'::jsonb);
 IF jsonb_typeof(old_refs) IS DISTINCT FROM 'array' OR jsonb_typeof(new_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(new_refs)>32 OR jsonb_array_length(new_refs)<>jsonb_array_length(old_refs)+delta
 THEN RETURN false; END IF;
 SELECT jsonb_agg(value ORDER BY ordinality) INTO suffix FROM jsonb_array_elements(new_refs) WITH ORDINALITY WHERE ordinality>delta;
 IF suffix IS DISTINCT FROM old_refs THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(new_refs)-1 LOOP
  reference:=new_refs->i;
  SELECT recovery.result,recovery.intent,original.document,scope.admission_digest INTO receipt
   FROM control.root_expiry_recovery_case recovery
   JOIN control.root_expiry_recovery_enrollment original ON original.enrollment_id=recovery.enrollment_id
    AND original.participant_id=recovery.participant_id AND original.privacy_domain_id=recovery.privacy_domain_id
    AND original.row_version=recovery.enrollment_revision AND original.document_digest=recovery.enrollment_digest
   JOIN control.root_expiry_recovery_scope scope ON scope.recovery_id=recovery.recovery_id
    AND scope.platform_context_id=new_e.platform_context_id AND scope.owner_participant_id=recovery.participant_id
    AND scope.installation_privacy_domain_id=recovery.privacy_domain_id AND scope.activation_operation_id=recovery.operation_id
    AND scope.platform_authority_epoch=new_e.root_epoch-i
   WHERE recovery.recovery_id::text=reference->>'recoveryId' AND recovery.enrollment_id::text=reference->>'enrollmentId'
    AND recovery.operation_id::text=reference->>'activationOperationId'
    AND 'sha256:'||encode(recovery.evidence_digest,'hex')=reference->>'receiptDigest'
    AND recovery.participant_id=new_e.participant_id AND recovery.privacy_domain_id=new_e.privacy_domain_id
    AND recovery.state='COMPLETED' AND recovery.evidence_digest=sha256(recovery.evidence_cbor)
    AND recovery.intent_digest=sha256(convert_to(openpc.signing_canonical_json(recovery.intent),'UTF8'))
    AND original.document_digest=sha256(convert_to(openpc.signing_canonical_json(original.document),'UTF8'));
  IF NOT FOUND THEN RETURN false; END IF;
  IF receipt.result->>'rootEpoch' IS DISTINCT FROM (new_e.root_epoch-i)::text
   OR receipt.result->>'rootRevision' IS DISTINCT FROM (new_e.root_revision-i)::text
   OR receipt.result->>'rootDigest' IS DISTINCT FROM 'sha256:'||encode(receipt.admission_digest,'hex')
   OR receipt.document->>'rootEpoch' IS DISTINCT FROM (new_e.root_epoch-i-1)::text
   OR receipt.document->>'rootRevision' IS DISTINCT FROM (new_e.root_revision-i-1)::text
   OR receipt.document->>'platformContextId' IS DISTINCT FROM new_e.platform_context_id::text
   OR receipt.document->'administratorPrincipalIds' IS DISTINCT FROM new_e.document->'administratorPrincipalIds'
  THEN RETURN false; END IF;
  IF i=0 THEN
   IF receipt.admission_digest IS DISTINCT FROM new_e.root_digest THEN RETURN false; END IF;
   runtime_scope:=receipt.intent#>'{successorScope,runtime}';
  ELSE
   IF previous_document->>'rootDigest' IS DISTINCT FROM receipt.result->>'rootDigest'
    OR previous_document->>'installationDigest' IS DISTINCT FROM receipt.document->>'installationDigest'
    OR previous_document->>'installationEnvironmentId' IS DISTINCT FROM receipt.document->>'installationEnvironmentId'
    OR receipt.intent#>'{successorScope,runtime}' IS DISTINCT FROM runtime_scope
   THEN RETURN false; END IF;
  END IF;
  IF i=delta AND receipt.admission_digest IS DISTINCT FROM old_e.root_digest THEN RETURN false; END IF;
  previous_document:=receipt.document;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION openpc.discovery_approval_resume_source_compatible(old_source jsonb, new_source jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE expected jsonb:=old_source; actions jsonb; i integer; scope text; old_actions jsonb;
BEGIN
 IF jsonb_typeof(old_source) IS DISTINCT FROM 'object' OR jsonb_typeof(new_source) IS DISTINCT FROM 'object'
  OR jsonb_typeof(old_source->'originalAdministrators') IS DISTINCT FROM 'array'
  OR jsonb_typeof(new_source->'originalAdministrators') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF jsonb_array_length(old_source->'originalAdministrators')<>2
  OR jsonb_array_length(new_source->'originalAdministrators')<>2 THEN RETURN false; END IF;
 actions:=jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1');
 old_actions:=old_source#>'{originalAdministrators,0,usable,administration,actionIntentIds}';
 IF old_actions IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1') AND old_actions IS DISTINCT FROM actions THEN RETURN false; END IF;
 FOR i IN 0..1 LOOP
  FOREACH scope IN ARRAY ARRAY['usable','grantable'] LOOP
   IF old_source#>ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'] IS DISTINCT FROM old_actions
    OR new_source#>ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'] IS DISTINCT FROM actions
   THEN RETURN false; END IF;
   expected:=jsonb_set(expected,ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'],actions,false);
  END LOOP;
 END LOOP;
 RETURN expected=new_source;
END $function$

CREATE OR REPLACE FUNCTION openpc.enforce_pending_delivery_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE captured_now timestamptz := clock_timestamp();
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.pending_delivery';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."state" <> 'PENDING' OR NEW."lease_owner" IS NOT NULL
       OR NEW."lease_expires_at" IS NOT NULL OR NEW."next_retry_at" IS NOT NULL
       OR NEW."safe_reason" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery initial state';
    END IF;
    NEW."first_observed_at" := captured_now;
    NEW."last_observed_at" := captured_now;
    RETURN NEW;
  END IF;
  IF NEW."pending_delivery_id" is distinct from OLD."pending_delivery_id"
     OR row(NEW."participant_id",NEW."privacy_domain_id",NEW."chain_id",NEW."profile_id",NEW."profile_version",NEW."correlated_log_identity_hmac",NEW."entity_hmac",NEW."entity_scope_digest",NEW."delivery_surface",NEW."protected_delivery_reference_digest",NEW."subscription_reference_digest",NEW."session_reference_digest") is distinct from row(OLD."participant_id",OLD."privacy_domain_id",OLD."chain_id",OLD."profile_id",OLD."profile_version",OLD."correlated_log_identity_hmac",OLD."entity_hmac",OLD."entity_scope_digest",OLD."delivery_surface",OLD."protected_delivery_reference_digest",OLD."subscription_reference_digest",OLD."session_reference_digest") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'pending delivery identity';
  END IF;
  IF NOT ((OLD."state" = 'PENDING' and NEW."state" = 'LEASED') or (OLD."state" = 'LEASED' and NEW."state" = 'DELIVERED') or (OLD."state" = 'LEASED' and NEW."state" = 'RETRY_WAIT') or (OLD."state" = 'RETRY_WAIT' and NEW."state" = 'LEASED') or (OLD."state" = 'PENDING' and NEW."state" = 'QUARANTINED') or (OLD."state" = 'LEASED' and NEW."state" = 'QUARANTINED') or (OLD."state" = 'RETRY_WAIT' and NEW."state" = 'QUARANTINED'))
     AND NOT (OLD."state" = 'LEASED' AND NEW."state" = 'LEASED'
              AND OLD."lease_expires_at" <= captured_now) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6022-INVALID-STATE-TRANSITION', DETAIL = 'pending delivery lifecycle';
  END IF;
  NEW."first_observed_at" := OLD."first_observed_at";
  NEW."last_observed_at" := captured_now;
  IF NEW."state" = 'LEASED' THEN
    IF NEW."lease_owner" IS NULL OR NEW."lease_expires_at" IS NULL
       OR NEW."lease_expires_at" <= captured_now THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery lease';
    END IF;
    NEW."next_retry_at" := NULL;
    NEW."safe_reason" := NULL;
  ELSIF NEW."state" = 'RETRY_WAIT' THEN
    IF NEW."next_retry_at" IS NULL OR NEW."next_retry_at" <= captured_now THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery retry';
    END IF;
    NEW."lease_owner" := NULL;
    NEW."lease_expires_at" := NULL;
    NEW."safe_reason" := NULL;
  ELSIF NEW."state" = 'QUARANTINED' THEN
    IF NEW."safe_reason" IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery quarantine';
    END IF;
    NEW."lease_owner" := NULL;
    NEW."lease_expires_at" := NULL;
    NEW."next_retry_at" := NULL;
  ELSE
    NEW."lease_owner" := NULL;
    NEW."lease_expires_at" := NULL;
    NEW."next_retry_at" := NULL;
    NEW."safe_reason" := NULL;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.enforce_work_item_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."state" <> 'OPEN' OR NEW."row_version" <> 1
       OR NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item initial state';
    END IF;
    -- Public remediation creation keeps its business receipt owner. Every
    -- internal remediation insert must instead prove native completion custody;
    -- context chooses the checker, never supplies its authorization.
    IF openpc.current_action_intent_id()='ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
      OR (NEW.kind='REMEDIATION' AND openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-WORK_ITEMS_CREATE_RESOURCE-V1') THEN
      PERFORM openpc.check_notification_completion_remediation_effect(NEW);
    END IF;
    IF current_setting('openpc.action_intent_id',true)='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND NEW.kind='DELIVERY_FAILURE' THEN
      PERFORM openpc.check_notification_delivery_failure_work(NEW);
    END IF;
    RETURN NEW;
  END IF;
  IF row(NEW."work_item_id",NEW."participant_id",NEW."privacy_domain_id",NEW."kind",
         NEW."resource_ref",NEW."created_by_principal_id",NEW."created_at")
     IS DISTINCT FROM
     row(OLD."work_item_id",OLD."participant_id",OLD."privacy_domain_id",OLD."kind",
         OLD."resource_ref",OLD."created_by_principal_id",OLD."created_at") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item identity';
  END IF;
  IF NOT ((OLD."state" = 'OPEN' AND NEW."state" = 'OPEN')
          OR (OLD."state" = 'OPEN' AND NEW."state" = 'CLAIMED')
          OR (OLD."state" = 'CLAIMED' AND NEW."state" = 'COMPLETED')
          OR (OLD."state" IN ('OPEN','CLAIMED') AND NEW."state" = 'CANCELLED')) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6022-INVALID-STATE-TRANSITION', DETAIL = 'control.work_item lifecycle';
  END IF;
  IF NEW."assignee_principal_id" IS DISTINCT FROM OLD."assignee_principal_id"
     AND NOT (OLD."state" = 'OPEN' AND NEW."state" = 'CLAIMED'
              AND OLD."assignee_principal_id" IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item assignee';
  END IF;
  IF NEW."row_version" <> OLD."row_version" + 1 OR NEW."updated_at" <= OLD."updated_at" THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item revision';
  END IF;
  IF NEW."state" = 'OPEN' AND
     (NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item open actor';
  ELSIF NEW."state" = 'CLAIMED' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NOT NULL
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item claim actor';
  ELSIF NEW."state" = 'COMPLETED' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NULL
         OR NEW."completed_by_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id"
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."completed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item completion actor';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.evidence_deletion_selection_plan(selection jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF selection->>'version'='OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1' THEN
  RETURN openpc.runtime_artifact_retirement_plan(right(selection->>'retentionPolicyId',36)::uuid,
   right(selection->'priorCursor'->>'deletionJobId',36)::uuid);
 ELSIF selection->>'version'='OPENPC_PROJECTION_DELETION_BATCH_V1' THEN
  IF selection->'priorCursor'='null'::jsonb THEN
   RETURN openpc.projection_deletion_batch_plan(right(selection->>'evidenceId',36)::uuid,NULL,selection->>'dataClass');
  END IF;
  RETURN openpc.projection_deletion_batch_plan(NULL,right(selection->'priorCursor'->>'deletionJobId',36)::uuid,selection->>'dataClass');
 ELSIF selection->>'version'='OPENPC_RAW_PROOF_DELETION_BATCH_V1' THEN
  IF selection->'priorCursor'='null'::jsonb THEN
   RETURN openpc.raw_proof_deletion_batch_plan(right(selection->>'objectRef',36)::uuid,NULL);
  END IF;
  RETURN openpc.raw_proof_deletion_batch_plan(NULL,right(selection->'priorCursor'->>'deletionJobId',36)::uuid);
 ELSIF selection->>'version'='OPENPC_LOCAL_EVIDENCE_DELETION_V1' THEN
  RETURN openpc.local_evidence_deletion_plan(right(selection->>'evidenceId',36)::uuid);
 ELSIF selection->>'version'='OPENPC_LOCAL_EVIDENCE_DELETION_BATCH_V1' THEN
  IF selection->'priorCursor'='null'::jsonb THEN
   RETURN openpc.local_evidence_deletion_batch_plan(right(selection->>'evidenceId',36)::uuid,NULL);
  END IF;
  RETURN openpc.local_evidence_deletion_batch_plan(NULL,right(selection->'priorCursor'->>'deletionJobId',36)::uuid);
 END IF;
 RAISE EXCEPTION 'PC-DATA-6004';
END $function$

CREATE OR REPLACE FUNCTION openpc.evidence_fact_hold_metadata(source control.evidence_catalogue)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE original jsonb; queue jsonb; item jsonb; lineage jsonb; reference jsonb; candidates jsonb;
 seen text[]:=ARRAY[]::text[]; unresolved boolean:=false; steps integer:=0;
 projections jsonb:='[]'; facts jsonb:='[]'; blocks jsonb:='[]'; generations jsonb:='[]';
BEGIN
 -- The closure resolver reloads authoritative ancestors. First bind the caller's
 -- starting record itself, so a modified class/digest/sequence cannot borrow the
 -- lineage of an otherwise valid catalogue identity.
 IF (source).source_format IS DISTINCT FROM 'OPENPC_CANONICAL_FACT_V1'
  OR (source).evidence_class IS DISTINCT FROM 'EFFECT'
  OR NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c
   WHERE c.participant_id=(source).participant_id AND c.privacy_domain_id=(source).privacy_domain_id
    AND c.stream_id=(source).stream_id AND c.record_id=(source).record_id
    AND c IS NOT DISTINCT FROM source) THEN RETURN NULL; END IF;
 SELECT jsonb_agg(DISTINCT p.lineage) INTO candidates FROM openpc.evidence_fact_lineages((source).participant_id,(source).privacy_domain_id) p
  WHERE p.stream_id=(source).stream_id AND p.record_id=(source).record_id;
 IF candidates IS NULL OR jsonb_array_length(candidates)<>1 THEN RETURN NULL; END IF;
 original:=candidates->0;
 queue:=jsonb_build_array(jsonb_build_object('lineage',original,'path','[]'::jsonb));
 WHILE jsonb_array_length(queue)>0 AND steps<64 LOOP
  item:=queue->0; queue:=queue-0; lineage:=item->'lineage'; steps:=steps+1;
  IF item->'path' ? (lineage->>'factDigest') THEN unresolved:=true; CONTINUE; END IF;
  IF lineage->>'factDigest'=ANY(seen) THEN CONTINUE; END IF;
  seen:=array_append(seen,lineage->>'factDigest');
  projections:=projections||jsonb_build_array(lineage->>'projectionId');
  facts:=facts||jsonb_build_array(jsonb_build_object('factType',lineage->>'factType','factProfileId',lineage->>'factProfileId','factKeyDigest',lineage->>'factKeyDigest'));
  blocks:=blocks||jsonb_build_array(jsonb_build_object('chainId',lineage->>'chainId','genesisDigest',lineage->>'genesisDigest','blockNumber',lineage->>'blockNumber'));
  generations:=generations||jsonb_build_array(jsonb_build_object('kind','CANONICAL_FACT','factProfileId',lineage->>'factProfileId','canonicalGeneration',lineage->>'canonicalGeneration'));
  FOR reference IN SELECT value FROM jsonb_array_elements(jsonb_build_array(lineage->'predecessorDigest',lineage->'relationshipPredecessorDigest',lineage->'reorgReplacementOf')) WHERE value<>'null'::jsonb LOOP
   SELECT jsonb_agg(DISTINCT p.lineage) INTO candidates
    FROM openpc.evidence_fact_lineages((source).participant_id,(source).privacy_domain_id) p
    WHERE p.lineage->'factDigest'=reference OR p.lineage->'factId'=reference;
   IF candidates IS NULL OR jsonb_array_length(candidates)<>1 THEN unresolved:=true;
   -- Visit descendants before queued siblings. Breadth-first de-duplication can
   -- mark both ends of a shared-reference cycle seen before either back edge
   -- reaches its ancestor path, incorrectly reporting complete closure.
   ELSE queue:=jsonb_build_array(jsonb_build_object('lineage',candidates->0,'path',(item->'path')||jsonb_build_array(lineage->>'factDigest')))||queue; END IF;
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('projections',projections,'facts',facts,'blocks',blocks,
  'generations',jsonb_build_object('CANONICAL_FACT',generations),'unresolvedReferences',unresolved OR jsonb_array_length(queue)>0);
EXCEPTION WHEN insufficient_privilege THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.evidence_hold_record_metadata(source control.evidence_catalogue)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE metadata jsonb; binding record; occurrence jsonb; invalidation jsonb;
BEGIN
 IF (source).source_format='OPENPC_AUTHENTICATION_OCCURRENCE_V1' THEN
  IF EXISTS(SELECT 1 FROM control.authentication_occurrence a WHERE a.participant_id=(source).participant_id
   AND a.privacy_domain_id=(source).privacy_domain_id AND a.occurrence_id::text=(source).record_id
   AND (source).receipt_digest='sha256:'||encode(a.receipt_digest,'hex') AND a.receipt_digest=sha256(a.receipt)
   AND a.occurred_at=(source).occurred_at) THEN
   RETURN jsonb_build_object('projections','[]'::jsonb,'facts','[]'::jsonb,'blocks','[]'::jsonb,'generations',jsonb_build_object('RUNTIME_CONFIGURATION','[]'::jsonb,'CANONICAL_FACT','[]'::jsonb));
  END IF;
 ELSIF (source).evidence_class='BUSINESS_TRANSITION' THEN
  RETURN openpc.retention_policy_receipt_hold_metadata(source);
 ELSIF (source).source_format='OPENPC_CANONICAL_FACT_V1' THEN
  RETURN openpc.evidence_fact_hold_metadata(source);
 ELSIF (source).source_format IN ('OPENPC_CANDIDATE_PROJECTION_CHUNK_V1','OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1') THEN
  RETURN openpc.candidate_archive_hold_metadata(source);
 ELSIF (source).source_format IN ('OPENPC_RUNTIME_ARTIFACT_CHUNK_V1','OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1') THEN
  RETURN openpc.runtime_artifact_archive_hold_metadata(source);
 ELSIF (source).source_format='PC-DEPLOYMENT-JOURNAL-PROJECTION-1' THEN
  SELECT p.projection INTO metadata FROM control.evidence_deployment_lineage p
   WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
    AND p.stream_id=(source).stream_id AND p.record_id=(source).record_id
    AND (source).evidence_class='EFFECT'
    AND p.projection=openpc.evidence_deployment_lineage_projection(source)
    AND p.projection->'historical'->>'receiptDigest'=(source).receipt_digest
    AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex');
  IF NOT FOUND THEN RETURN NULL; END IF;
  occurrence:=metadata->'historical'->'occurrence';
  invalidation:=metadata->'historical'->'invalidation';
  IF invalidation<>'null'::jsonb THEN
   -- A reorg invalidates authority, not the preservation duty for its original
   -- block. Require one exact, previously verified occurrence reference.
   SELECT p.projection->'historical'->'occurrence' INTO STRICT occurrence
    FROM control.evidence_deployment_lineage p
    WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
     AND p.stream_id=(source).stream_id AND split_part(p.record_id,':',2)=split_part((source).record_id,':',2)
     AND (p.projection->'historical'->>'sourceVersion')::numeric<(metadata->'historical'->>'sourceVersion')::numeric
     AND p.projection->>'chainId'=metadata->>'chainId' AND p.projection->>'genesisDigest'=metadata->>'genesisDigest'
     AND p.projection->'historical'->'occurrence'->>'occurrenceId'=invalidation->>'occurrenceId'
     AND p.projection->'historical'->'occurrence'->>'occurrenceDigest'=invalidation->>'occurrenceDigest'
     AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex')
    GROUP BY p.projection->'historical'->'occurrence';
   IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  IF occurrence IS NULL OR occurrence='null'::jsonb THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('blocks',jsonb_build_array(jsonb_build_object('chainId',metadata->>'chainId',
   'genesisDigest',metadata->>'genesisDigest','blockNumber',occurrence->>'blockNumber')));
 ELSIF (source).source_format='OPENPC_RPC_DECISION_TRANSITION_V1' THEN
  SELECT r.preservation_metadata INTO metadata FROM control.evidence_projection_retirement r
   JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
   WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
    AND r.evidence_id=(source).evidence_id AND r.stream_id=(source).stream_id AND r.record_id=(source).record_id
    AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.source_receipt_digest=(source).receipt_digest
    AND r.retirement_digest=openpc.projection_retirement_digest(r) AND j.state='SUCCEEDED';
  IF FOUND THEN RETURN metadata; END IF;
  SELECT p.projection,g.projection_plan_id,g.runtime_configuration_generation_id INTO binding
   FROM control.evidence_rpc_provenance p JOIN control.runtime_configuration_generation g
    ON g.participant_id=p.participant_id AND g.privacy_domain_id=p.privacy_domain_id
     AND g.runtime_configuration_generation_id::text=p.projection->'activation'->>'generationId'
     AND g.generation_digest=p.projection->'activation'->>'generationDigest'
   WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
    AND p.stream_id=(source).stream_id AND p.record_id=(source).record_id
    AND (source).evidence_class='EFFECT' AND p.projection->>'sourceDigest'=(source).receipt_digest
    AND p.projection->>'sourceSequence'=(source).sequence::text
    AND extract(epoch FROM (source).occurred_at)*1000000=floor((p.projection->>'occurredAtNs')::numeric/1000)
    AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex');
  IF FOUND THEN
   RETURN jsonb_build_object('projections',jsonb_build_array('urn:openpc:resource:'||binding.projection_plan_id::text),
    'generations',jsonb_build_object('RUNTIME_CONFIGURATION',jsonb_build_array(jsonb_build_object('kind','RUNTIME_CONFIGURATION',
      'generationId','urn:openpc:resource:'||binding.runtime_configuration_generation_id::text))));
  END IF;
 END IF;
 RETURN NULL;
EXCEPTION WHEN insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.evidence_hold_selector_encoding(selector jsonb, participant uuid, privacy uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE kind text:=selector->>'type'; expected jsonb:=jsonb_build_object('type',kind);
 encoded jsonb:=jsonb_build_object('0','pc.evidence.hold-selector.v1','1',openpc.business_uuid(participant),
 '2',openpc.business_uuid(privacy),'3',kind); first_value numeric; last_value numeric; generation jsonb;
 resource_pattern text:='^urn:openpc:resource:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
 profile_pattern text:=replace(resource_pattern,':resource:',':fact-profile:');
BEGIN
 IF participant IS NULL OR privacy IS NULL OR jsonb_typeof(selector) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF kind='SEQUENCE_RANGE' THEN
  IF coalesce(selector->>'streamId','')!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
   OR coalesce(selector->>'fromSequence','')!~'^[1-9][0-9]{0,19}$' OR NOT(selector ? 'throughSequence') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  first_value:=(selector->>'fromSequence')::numeric;
  encoded:=encoded||jsonb_build_object('4',selector->>'streamId','5',first_value,'6',CASE WHEN selector->'throughSequence'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'throughSequence'<>'null'::jsonb THEN
   IF coalesce(selector->>'throughSequence','')!~'^[1-9][0-9]{0,19}$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   last_value:=(selector->>'throughSequence')::numeric; encoded:=encoded||jsonb_build_object('7',last_value);
  END IF;
  expected:=expected||jsonb_build_object('streamId',selector->>'streamId','fromSequence',first_value::text,'throughSequence',last_value::text);
 ELSIF kind='DIGEST' THEN
  IF coalesce(selector->>'recordDigest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('recordDigest',selector->>'recordDigest');
  encoded:=encoded||jsonb_build_object('4',openpc.business_bytes(decode(substring(selector->>'recordDigest' from 8),'hex')));
 ELSIF kind='PROJECTION' THEN
  IF coalesce(selector->>'projectionId','')!~resource_pattern THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('projectionId',selector->>'projectionId');
  encoded:=encoded||jsonb_build_object('4',openpc.business_uuid(right(selector->>'projectionId',36)::uuid));
 ELSIF kind='FACT_TYPE_KEY' THEN
  IF coalesce(selector->>'factType','') NOT IN ('CONTRACT_STATE_CALL','RELATIONSHIP','EXTERNAL_DECISION')
   OR coalesce(selector->>'factProfileId','')!~profile_pattern OR NOT(selector ? 'factKeyDigest')
   OR (selector->'factKeyDigest'<>'null'::jsonb AND coalesce(selector->>'factKeyDigest','')!~'^sha256:[0-9a-f]{64}$') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('factType',selector->>'factType','factProfileId',selector->>'factProfileId','factKeyDigest',selector->'factKeyDigest');
  encoded:=encoded||jsonb_build_object('4',selector->>'factType','5',selector->>'factProfileId','6',CASE WHEN selector->'factKeyDigest'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'factKeyDigest'<>'null'::jsonb THEN encoded:=encoded||jsonb_build_object('7',openpc.business_bytes(decode(substring(selector->>'factKeyDigest' from 8),'hex'))); END IF;
 ELSIF kind='BLOCK_RANGE' THEN
  IF coalesce(selector->>'chainId','')!~'^(0|[1-9][0-9]{0,77})$' OR (selector->>'chainId')::numeric>=power(2::numeric,256)
   OR coalesce(selector->>'genesisDigest','')!~'^sha256:[0-9a-f]{64}$'
   OR coalesce(selector->>'fromBlock','')!~'^(0|[1-9][0-9]{0,19})$' OR NOT(selector ? 'throughBlock') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  first_value:=(selector->>'fromBlock')::numeric;
  encoded:=encoded||jsonb_build_object('4',selector->>'chainId','5',openpc.business_bytes(decode(substring(selector->>'genesisDigest' from 8),'hex')),
   '6',first_value,'7',CASE WHEN selector->'throughBlock'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'throughBlock'<>'null'::jsonb THEN
   IF coalesce(selector->>'throughBlock','')!~'^(0|[1-9][0-9]{0,19})$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   last_value:=(selector->>'throughBlock')::numeric; encoded:=encoded||jsonb_build_object('8',last_value);
  END IF;
  expected:=expected||jsonb_build_object('chainId',selector->>'chainId','genesisDigest',selector->>'genesisDigest','fromBlock',first_value::text,'throughBlock',last_value::text);
 ELSIF kind='GENERATION' THEN
  generation:=selector->'generation';
  IF generation->>'kind'='RUNTIME_CONFIGURATION' THEN
   IF coalesce(generation->>'generationId','')!~resource_pattern OR generation IS DISTINCT FROM jsonb_build_object('kind','RUNTIME_CONFIGURATION','generationId',generation->>'generationId') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   encoded:=encoded||jsonb_build_object('4','RUNTIME_CONFIGURATION','5',openpc.business_uuid(right(generation->>'generationId',36)::uuid));
  ELSIF generation->>'kind'='CANONICAL_FACT' THEN
   IF coalesce(generation->>'factProfileId','')!~profile_pattern OR coalesce(generation->>'canonicalGeneration','')!~'^[1-9][0-9]{0,19}$'
    OR (generation->>'canonicalGeneration')::numeric>18446744073709551615
    OR generation IS DISTINCT FROM jsonb_build_object('kind','CANONICAL_FACT','factProfileId',generation->>'factProfileId','canonicalGeneration',generation->>'canonicalGeneration') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   encoded:=encoded||jsonb_build_object('4','CANONICAL_FACT','5',generation->>'factProfileId','6',(generation->>'canonicalGeneration')::numeric);
  ELSE RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('generation',generation);
 ELSIF kind NOT IN ('PARTICIPANT','PRIVACY_DOMAIN') OR kind IS NULL THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF first_value>18446744073709551615 OR last_value>18446744073709551615 OR last_value<first_value
  OR selector IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 RETURN encoded;
END $function$

CREATE OR REPLACE FUNCTION openpc.evidence_hold_source_match(selector jsonb, metadata jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE entries jsonb; dimension text; entry jsonb; check_selector jsonb; matched boolean;
BEGIN
 IF metadata ? 'unresolvedReferences' AND jsonb_typeof(metadata->'unresolvedReferences') IS DISTINCT FROM 'boolean' THEN RETURN NULL; END IF;
 dimension:=CASE selector->>'type' WHEN 'PROJECTION' THEN 'projections' WHEN 'FACT_TYPE_KEY' THEN 'facts'
  WHEN 'BLOCK_RANGE' THEN 'blocks' WHEN 'GENERATION' THEN 'generations' END;
 -- Generation namespaces have independent completeness. A known runtime UUID
 -- never proves that a record references no canonical Fact generation.
 entries:=CASE WHEN dimension='generations' THEN metadata->dimension->(selector->'generation'->>'kind') ELSE metadata->dimension END;
 IF dimension IS NULL OR jsonb_typeof(entries) IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;
 -- Validate every source item before proving absence. A malformed sibling must
 -- not silently become a non-match, even when another item is well formed.
 FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
  IF dimension='projections' THEN
   check_selector:=jsonb_build_object('type','PROJECTION','projectionId',entry);
  ELSIF dimension='facts' THEN
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry->'factKeyDigest' IS NOT DISTINCT FROM 'null'::jsonb THEN RETURN NULL; END IF;
   check_selector:=entry||jsonb_build_object('type','FACT_TYPE_KEY');
  ELSIF dimension='blocks' THEN
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry-ARRAY['chainId','genesisDigest','blockNumber']<>'{}'::jsonb THEN RETURN NULL; END IF;
   check_selector:=jsonb_build_object('type','BLOCK_RANGE','chainId',entry->'chainId','genesisDigest',entry->'genesisDigest',
    'fromBlock',entry->'blockNumber','throughBlock',entry->'blockNumber');
  ELSE
   IF entry->>'kind' IS DISTINCT FROM selector->'generation'->>'kind' THEN RETURN NULL; END IF;
   check_selector:=jsonb_build_object('type','GENERATION','generation',entry);
  END IF;
  BEGIN
   PERFORM openpc.evidence_hold_selector_encoding(check_selector,'00000000-0000-0000-0000-000000000000'::uuid,'00000000-0000-0000-0000-000000000000'::uuid);
  EXCEPTION WHEN raise_exception OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
  END;
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(entries) e WHERE
  (dimension='projections' AND e=selector->'projectionId')
  OR (dimension='facts' AND e->>'factType'=selector->>'factType' AND e->>'factProfileId'=selector->>'factProfileId'
   AND (selector->'factKeyDigest'='null'::jsonb OR e->>'factKeyDigest'=selector->>'factKeyDigest'))
  OR (dimension='blocks' AND e->>'chainId'=selector->>'chainId' AND e->>'genesisDigest'=selector->>'genesisDigest'
   AND (e->>'blockNumber')::numeric>=(selector->>'fromBlock')::numeric
   AND (selector->'throughBlock'='null'::jsonb OR (e->>'blockNumber')::numeric<=(selector->>'throughBlock')::numeric))
  OR (dimension='generations' AND e=selector->'generation')) INTO matched;
 -- A verified positive remains a preservation duty. Missing reference closure
 -- prevents a negative result from being used as permission to delete.
 IF NOT matched AND metadata->'unresolvedReferences'='true'::jsonb THEN RETURN NULL; END IF;
 RETURN matched;
END $function$

CREATE OR REPLACE FUNCTION openpc.evidence_kms_cose_binding(payload bytea, cose bytea, family text, signer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE m jsonb; c jsonb; h jsonb; parsed jsonb; wanted_schema integer; wanted_purpose integer; wanted_digest text; wanted_fields integer;
BEGIN
 CASE family
 WHEN 'EvidenceKmsProfileV1' THEN wanted_schema:=24015; wanted_purpose:=352; wanted_digest:='0c1c466ce7dc697f151bfb0d574a8837d11ae52b6c94d7f454b29120546376fe'; wanted_fields:=28;
WHEN 'EvidenceWrappedKeyRecordV1' THEN wanted_schema:=24016; wanted_purpose:=353; wanted_digest:='b69bd016306d45d700e68aea1ce41225a774556df3070dbfea71d762cde3b700'; wanted_fields:=20;
WHEN 'EvidenceKmsReceiptV1' THEN wanted_schema:=24017; wanted_purpose:=354; wanted_digest:='2de3abbbc13222bd7473f0aa11d9dcbfb1bb9b538f0e426259d276c17b5d8ad2'; wanted_fields:=31;
 ELSE RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-FAMILY'; END CASE;
 IF octet_length(payload) NOT BETWEEN 1 AND 65536 OR octet_length(cose) NOT BETWEEN 1 AND 131072 OR get_byte(cose,0)<>210
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-COSE'; END IF;
 parsed:=openpc.business_cbor_item(cose,1,0); c:=parsed->'value';
 IF (parsed->>'next')::integer<>octet_length(cose) OR jsonb_typeof(c) IS DISTINCT FROM 'array'
 OR jsonb_array_length(c)<>4 OR c->1 IS DISTINCT FROM '{}'::jsonb
 OR c->2 IS DISTINCT FROM jsonb_build_object('bytes',encode(payload,'hex'))
 OR length(c->3->>'bytes') IS DISTINCT FROM 128 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-COSE'; END IF;
 h:=openpc.business_cbor(decode(c->0->>'bytes','hex'));
 IF h IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),'3','application/pc+cbor',
 '4',jsonb_build_object('bytes',encode(convert_to(signer,'UTF8'),'hex')),'100',wanted_schema,'101',1,'102',wanted_purpose,'103',2)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ROLE'; END IF;
 m:=openpc.business_cbor(payload);
 IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(m))<>wanted_fields
 OR m->'0' IS DISTINCT FROM jsonb_build_object('bytes',wanted_digest)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-DEFINITION'; END IF;
 CASE family
 WHEN 'EvidenceKmsProfileV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'profileId',(m->'4'->>'bytes')::uuid::text,'revision',m->>'5','producerTrustDigest','sha256:'||(m->'6'->>'bytes'),'owner',m->>'7','secretClass',m->>'8','providerId',m->>'9','reference',m->>'10','version',m->>'11','providerKeyId',m->>'12','providerKeyVersion',m->>'13','keyEpoch',m->>'14','wrapProfileDigest','sha256:'||(m->'15'->>'bytes'),'policyDigest','sha256:'||(m->'16'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'17'->>'bytes'),'providerOrigin',m->>'18','providerTlsSpkiDigest','sha256:'||(m->'19'->>'bytes'),'receiptKeyId','sha256:'||(m->'20'->>'bytes'),'recoveryKeyId','sha256:'||(m->'21'->>'bytes'),'permissions',m->>'22','kekExportPolicy',m->>'23','recoveryMode',m->>'24','validFromMs',m->>'25','validUntilMs',m->>'26','issuerKeyId','sha256:'||(m->'27'->>'bytes'));
WHEN 'EvidenceWrappedKeyRecordV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'attemptId',(m->'4'->>'bytes')::uuid::text,'originalRequestDigest','sha256:'||(m->'5'->>'bytes'),'objectIntentDigest','sha256:'||(m->'6'->>'bytes'),'profileDigest','sha256:'||(m->'7'->>'bytes'),'providerId',m->>'8','reference',m->>'9','version',m->>'10','providerKeyId',m->>'11','providerKeyVersion',m->>'12','keyEpoch',m->>'13','wrapProfileDigest','sha256:'||(m->'14'->>'bytes'),'policyDigest','sha256:'||(m->'15'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'16'->>'bytes'),'wrappedKey',m->'17'->>'bytes','createdAtMs',m->>'18','signerKeyId','sha256:'||(m->'19'->>'bytes'));
WHEN 'EvidenceKmsReceiptV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'profileDigest','sha256:'||(m->'5'->>'bytes'),'operation',m->>'6','attemptId',(m->'7'->>'bytes')::uuid::text,'exchangeId',(m->'8'->>'bytes')::uuid::text,'requestDigest','sha256:'||(m->'9'->>'bytes'),'challenge',m->'10'->>'bytes','objectIntentDigest','sha256:'||(m->'11'->>'bytes'),'keyId','sha256:'||(m->'12'->>'bytes'),'keyUse',m->>'13','providerId',m->>'14','reference',m->>'15','version',m->>'16','providerKeyId',m->>'17','providerKeyVersion',m->>'18','keyEpoch',m->>'19','wrapProfileDigest','sha256:'||(m->'20'->>'bytes'),'policyDigest','sha256:'||(m->'21'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'22'->>'bytes'),'outcome',m->>'23','keyState',m->>'24','providerSequence',m->>'25','recoveryFloor',m->>'26','materialDigest','sha256:'||(m->'27'->>'bytes'),'observedAtMs',m->>'28','validUntilMs',m->>'29','signerKeyId','sha256:'||(m->'30'->>'bytes'));
 END CASE;
END $function$

