CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_completion_preparation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb; source jsonb; installed control.evidence_export_producer_installation; expected jsonb; now_ns numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='UPDATE' THEN
  IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
   OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
   OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
   OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
   OR NOT ((OLD.state='PREPARED' AND NEW.state='OBSERVED' AND OLD.cose_sign1 IS NULL AND NEW.cose_sign1 IS NOT NULL)
    OR (OLD.state='OBSERVED' AND NEW.state='PUBLISHED' AND OLD.cose_sign1 IS NOT NULL AND NEW.cose_sign1=OLD.cose_sign1))
   OR to_jsonb(NEW)-ARRAY['state','cose_sign1'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','cose_sign1']
  THEN RAISE EXCEPTION 'DATA-6020-EXPORT-COMPLETION-IMMUTABLE'; END IF;
  -- A direct UPDATE already owns a row lock. Never wait in reverse order.
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF NEW.authority_snapshot IS DISTINCT FROM convert_to(openpc.signing_canonical_json(openpc.evidence_export_producer_authority(NEW.trust_digest)),'UTF8')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-COMPLETION-AUTHORITY'; END IF;
  source:=openpc.evidence_export_completion_source(NEW.evidence_export_id);
  IF source->>'streamId' IS DISTINCT FROM NEW.stream_id OR
   source-'streamId' IS DISTINCT FROM NEW.claims-ARRAY['environmentId','eventId','sourceId','sequence','recordedAtNs','dataDigest','authoritySnapshotDigest','signerTrustSnapshotDigest','signerKeyId']
  THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-BINDING'; END IF;
  PERFORM openpc.archive_cose_binding(NEW.receipt_payload,NEW.cose_sign1,NEW.claims->>'signerKeyId',24013,350);
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-EXPORT-COMPLETION-IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 OR NEW.state<>'PREPARED' OR NEW.cose_sign1 IS NOT NULL
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT installed FROM control.evidence_export_producer_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND trust_digest=NEW.trust_digest AND state='ACTIVE';
 IF NEW.authority_snapshot IS DISTINCT FROM convert_to(openpc.signing_canonical_json(openpc.evidence_export_producer_authority(NEW.trust_digest)),'UTF8')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-COMPLETION-AUTHORITY'; END IF;
 source:=openpc.evidence_export_completion_source(NEW.evidence_export_id);
 c:=NEW.claims;
 expected:=(source-'streamId')||jsonb_build_object(
  'environmentId',installed.environment_id,'eventId',NEW.event_id::text,'sourceId',installed.source_id::text,
  'sequence','1','recordedAtNs',c->>'recordedAtNs','dataDigest','sha256:'||encode(sha256(NEW.source_data),'hex'),
  'authoritySnapshotDigest','sha256:'||encode(sha256(NEW.authority_snapshot),'hex'),
  'signerTrustSnapshotDigest',installed.trust_digest,'signerKeyId',installed.signer_id);
 IF c IS DISTINCT FROM expected OR source->>'streamId' IS DISTINCT FROM NEW.stream_id
 OR coalesce(c->>'recordedAtNs','')!~'^[1-9][0-9]{0,19}$'
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-BINDING'; END IF;
 now_ns:=floor(extract(epoch from clock_timestamp())*1000000)*1000;
 IF (c->>'recordedAtNs')::numeric>now_ns OR (c->>'recordedAtNs')::numeric<now_ns-5000000000
 OR mod((c->>'recordedAtNs')::numeric,1000)<>0
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-TIME'; END IF;
 IF openpc.business_cbor(NEW.source_data) IS DISTINCT FROM jsonb_build_object(
  '0','urn:openpc:resource:'||NEW.evidence_export_id::text,'1',(source->>'checkpoint')::numeric,
  '2',openpc.business_bytes(decode(substr(source->>'outputDigest',8),'hex')),'3',(source->>'recordCount')::numeric)
 OR openpc.business_cbor(NEW.receipt_payload) IS DISTINCT FROM jsonb_build_object('0',openpc.business_bytes(decode('ee72df3cca5024c26c52c5983b15087426b4faabeb511cace227b92a04d2eb8f','hex')),'1',c->>'environmentId','2',openpc.business_uuid((c->>'participantId')::uuid),'3',openpc.business_uuid((c->>'privacyDomainId')::uuid),'4',openpc.business_uuid((c->>'eventId')::uuid),'5',openpc.business_uuid((c->>'sourceId')::uuid),'6',openpc.business_uuid((c->>'evidenceExportId')::uuid),'7',openpc.business_uuid((c->>'startOperationId')::uuid),'8',openpc.business_uuid((c->>'causationId')::uuid),'9',(c->>'sequence')::numeric,'10',(c->>'recordedAtNs')::numeric,'11',openpc.business_bytes(decode(substr(c->>'requestDigest',8),'hex')),'12',(c->>'checkpoint')::numeric,'13',openpc.business_bytes(decode(substr(c->>'outputDigest',8),'hex')),'14',(c->>'recordCount')::numeric,'15',openpc.business_bytes(decode(substr(c->>'dataDigest',8),'hex')),'16',openpc.business_bytes(decode(substr(c->>'authoritySnapshotDigest',8),'hex')),'17',openpc.business_bytes(decode(substr(c->>'signerTrustSnapshotDigest',8),'hex')),'18',c->>'signerKeyId')
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-PAYLOAD'; END IF;
 expected:=jsonb_build_object('specversion','1.0','id',NEW.event_id::text,'source','urn:openpc:service:'||installed.source_id::text,
  'type','io.openpc.evidence.export.completed.v1','subject','urn:openpc:resource:'||NEW.evidence_export_id::text,
  'time',to_char(to_timestamp(floor((c->>'recordedAtNs')::numeric/1000000000)::double precision) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||'.'||lpad(mod((c->>'recordedAtNs')::numeric/1000,1000000)::bigint::text,6,'0')||'Z',
  'datacontenttype','application/json','dataschema','https://schemas.openpc.local/event-payloads.schema.json#/$defs/EvidenceExportCompleted',
  'participantid','urn:openpc:participant:'||NEW.participant_id::text,'privacydomainid','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
  'correlationid',source->>'startOperationId','causationid',source->>'causationId','sequence','1','datadigest',c->>'dataDigest',
  'data',jsonb_build_object('evidenceExportId','urn:openpc:resource:'||NEW.evidence_export_id::text,'checkpoint',source->>'checkpoint','outputDigest',source->>'outputDigest','recordCount',source->>'recordCount'));
 IF NEW.event_payload IS DISTINCT FROM convert_to(openpc.signing_canonical_json(expected),'UTF8')
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-EVENT'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_output()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE request control.evidence_export_request%ROWTYPE; v_selection jsonb; records jsonb; artifact jsonb; assurance text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT request FROM control.evidence_export_request WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND evidence_export_id=NEW.evidence_export_id FOR UPDATE;
 IF request.state NOT IN ('RUNNING','BACKLOGGED') OR request.start_operation_id<>current_setting('openpc.operation_id')::uuid
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT s.selection INTO STRICT v_selection FROM control.evidence_export_selection s WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND request_digest=request.request_digest;
 assurance:=CASE WHEN EXISTS(SELECT 1 FROM control.evidence_archive_trust t WHERE t.participant_id=NEW.participant_id
   AND t.privacy_domain_id=NEW.privacy_domain_id AND t.sink_id=NEW.sink_id)
   THEN 'REMOTE_INTERFACE_VERIFIED' ELSE 'LOCAL_FSYNC_READBACK' END;
 IF assurance='REMOTE_INTERFACE_VERIFIED' THEN
  PERFORM openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),NEW.stream_id);
 END IF;
 SELECT jsonb_agg(jsonb_build_object('evidenceId',r->>'evidenceId','sequence',r->>'sequence',
   'evidenceClass',r->>'evidenceClass','recordDigest',r->>'recordDigest','occurredAt',r->>'occurredAt',
   'segmentDigest',r->>'objectDigest','checkpointDigest',c.checkpoint_digest) ORDER BY (r->>'sequence')::numeric)
 INTO records FROM jsonb_array_elements(v_selection->'records') r JOIN control.evidence_checkpoint c
   ON c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id
    AND c.segment_id=(r->>'segmentId')::uuid AND c.object_digest=r->>'objectDigest' AND c.sink_id=NEW.sink_id
    AND c.receipt->>'assurance'=assurance
    AND (assurance='LOCAL_FSYNC_READBACK' OR (c.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1'
      AND openpc.remote_archive_covers(c.participant_id,c.privacy_domain_id,c.stream_id,c.segment_id,c.sink_id)
      AND EXISTS(SELECT 1 FROM control.evidence_archive_receipt ar JOIN control.evidence_archive_outbox ao
       USING(participant_id,privacy_domain_id,receipt_id) WHERE ar.participant_id=c.participant_id
        AND ar.privacy_domain_id=c.privacy_domain_id AND ar.receipt_digest=c.receipt_digest
        AND ar.receipt_id::text=c.receipt->>'receiptId' AND ar.profile_digest=c.receipt->>'profileDigest')));
 IF records IS NULL OR jsonb_array_length(records)<>jsonb_array_length(v_selection->'records')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 artifact:=jsonb_build_object('version','OPENPC_EVIDENCE_REDACTED_EXPORT_V1',
  'evidenceExportId','urn:openpc:resource:'||NEW.evidence_export_id::text,
  'participantId','urn:openpc:participant:'||NEW.participant_id::text,
  'privacyDomainId','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
  'requestDigest',request.request_digest,'range',v_selection->'range','sinkId',NEW.sink_id,
  'assurance',assurance,'records',records);
 IF assurance='REMOTE_INTERFACE_VERIFIED' THEN artifact:=artifact||jsonb_build_object('providerQualification','NOT_ESTABLISHED'); END IF;
 IF NEW.artifact<>convert_to(openpc.signing_canonical_json(artifact),'UTF8')
  OR NEW.output_digest<>'sha256:'||encode(sha256(NEW.artifact),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE action text; operation uuid; v_through_sequence numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 action:=current_setting('openpc.action_intent_id'); operation:=current_setting('openpc.operation_id')::uuid;
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF action<>'ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1' OR NEW.creation_operation_id<>operation
   OR NEW.last_operation_id<>operation OR NEW.state<>'REQUESTED' OR NEW.start_operation_id IS NOT NULL
   OR NEW.revision<>1 OR NEW.checkpoint<>0 OR NEW.output_digest IS NOT NULL OR NEW.last_error_code IS NOT NULL
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 ELSE
  IF NEW.revision<>OLD.revision+1 OR NEW.participant_id<>OLD.participant_id OR NEW.privacy_domain_id<>OLD.privacy_domain_id
   OR NEW.evidence_export_id<>OLD.evidence_export_id OR NEW.created_at<>OLD.created_at OR NEW.creation_operation_id<>OLD.creation_operation_id
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF action='ACT-EVIDENCE_EXPORTS_UPDATE_RESOURCE-V1' THEN
   IF OLD.state<>'REQUESTED' OR NEW.state<>'REQUESTED' OR NEW.request_digest=OLD.request_digest
    OR NEW.last_operation_id<>operation OR NEW.last_error_code IS NOT NULL
    OR (to_jsonb(NEW)-ARRAY['request_digest','stream_id','revision','updated_at','last_operation_id']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['request_digest','stream_id','revision','updated_at','last_operation_id'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF action='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND OLD.state='REQUESTED' THEN
   IF NEW.state<>'RUNNING' OR NEW.last_operation_id<>operation OR NEW.start_operation_id<>operation
    OR (to_jsonb(NEW)-ARRAY['state','revision','updated_at','last_operation_id','start_operation_id']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['state','revision','updated_at','last_operation_id','start_operation_id'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF action='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND pg_has_role(current_user,'openpc_control_worker','USAGE') THEN
   IF OLD.state NOT IN ('RUNNING','BACKLOGGED') OR NEW.state NOT IN ('SUCCEEDED','FAILED','BACKLOGGED')
    OR operation<>OLD.start_operation_id OR
    (to_jsonb(NEW)-ARRAY['state','revision','updated_at','checkpoint','output_digest','last_error_code']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['state','revision','updated_at','checkpoint','output_digest','last_error_code'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   IF NEW.state='SUCCEEDED' THEN
    SELECT (selection->'range'->>'throughSequence')::numeric INTO v_through_sequence FROM control.evidence_export_selection
     WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND request_digest=NEW.request_digest;
    IF NEW.checkpoint IS DISTINCT FROM v_through_sequence OR NEW.last_error_code IS NOT NULL OR NOT EXISTS
     (SELECT 1 FROM control.evidence_export_output WHERE evidence_export_id=NEW.evidence_export_id
       AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND output_digest=NEW.output_digest)
    THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   ELSIF NEW.last_error_code IS DISTINCT FROM 'PC-OPS-9002' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.updated_at:=clock_timestamp();
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actual jsonb; v_first_sequence numeric; v_last_sequence numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 v_first_sequence:=(NEW.selection->'range'->>'fromSequence')::numeric;
 v_last_sequence:=(NEW.selection->'range'->>'throughSequence')::numeric;
 IF v_first_sequence IS NULL OR v_last_sequence IS NULL OR v_first_sequence<1 OR v_last_sequence<v_first_sequence
  OR v_last_sequence>18446744073709551615 OR v_last_sequence-v_first_sequence>=128
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 SELECT jsonb_agg(jsonb_build_object('evidenceId','urn:openpc:resource:'||c.evidence_id::text,
  'sourceRecordId',c.record_id,'segmentId',c.segment_id::text,'objectDigest',s.object_digest,
  'sequence',c.sequence::text,'evidenceClass',c.evidence_class,'recordDigest',c.receipt_digest,
  'occurredAt',to_char(c.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY c.sequence)
 INTO actual FROM control.evidence_catalogue c JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
 WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id
  AND c.sequence BETWEEN v_first_sequence AND v_last_sequence;
 IF actual IS NULL OR jsonb_array_length(actual)<>v_last_sequence-v_first_sequence+1 OR
  NEW.selection IS DISTINCT FROM jsonb_build_object('version','OPENPC_EVIDENCE_EXPORT_SELECTION_V1',
   'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
   'range',jsonb_build_object('streamId',NEW.stream_id,'fromSequence',v_first_sequence::text,
    'throughSequence',v_last_sequence::text,'redactionProfileId','pc.evidence.minimized-audit.v1'),'records',actual)
  OR NEW.request_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.selection),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_fact_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p jsonb:=NEW.projection; l jsonb:=p->'lineage'; field text; deleted_source control.evidence_catalogue;
 resource_pattern text:='^urn:openpc:fact:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT deleted_source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id AND privacy_domain_id=OLD.privacy_domain_id
   AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(deleted_source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR jsonb_typeof(l) IS DISTINCT FROM 'object'
  OR p-ARRAY['candidateId','sourceSequence','receiptDigest','admittedAt','lineage','integrity','authority','currentReadiness','sourceProfileId','verificationKeyId','verificationKeyDigest']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(p))<>11
  OR l-ARRAY['factId','factDigest','factType','factProfileId','factKeyDigest','canonicalGeneration','projectionId','chainId','genesisDigest','blockNumber','blockHash','predecessorDigest','relationshipPredecessorDigest','reorgReplacementOf']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(l))<>14
  OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE e.key<>'lineage' AND jsonb_typeof(e.value)<>'string')
  OR EXISTS(SELECT 1 FROM jsonb_each(l) e WHERE jsonb_typeof(e.value)<>'string'
   AND NOT(e.key IN ('predecessorDigest','relationshipPredecessorDigest','reorgReplacementOf') AND e.value='null'::jsonb))
  OR p->>'integrity' IS DISTINCT FROM 'FACT_COSE_VERIFIED_AT_CUSTODY'
  OR p->>'authority' IS DISTINCT FROM 'NONE' OR p->>'currentReadiness' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR coalesce(l->>'factId','')!~resource_pattern
  OR coalesce('urn:openpc:fact:'||(p->>'candidateId'),'')!~resource_pattern
  OR coalesce('urn:openpc:fact:'||(p->>'sourceProfileId'),'')!~resource_pattern
  OR coalesce(p->>'sourceSequence','')!~'^[1-9][0-9]{0,18}$'
  OR (p->>'sourceSequence')::numeric>9223372036854775807
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR NEW.record_id<>'fact:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(NEW.participant_id::text,NEW.privacy_domain_id::text,p->>'sourceProfileId')),'UTF8')),'hex')||':'||(p->>'sourceSequence')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOREACH field IN ARRAY ARRAY['verificationKeyId','verificationKeyDigest','receiptDigest'] LOOP
  IF coalesce(p->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['factDigest','blockHash'] LOOP
  IF coalesce(l->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['predecessorDigest','relationshipPredecessorDigest'] LOOP
  IF l->field<>'null'::jsonb AND coalesce(l->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 IF l->'reorgReplacementOf'<>'null'::jsonb AND coalesce(l->>'reorgReplacementOf','')!~resource_pattern THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','FACT_TYPE_KEY','factType',l->>'factType','factProfileId',l->>'factProfileId','factKeyDigest',l->>'factKeyDigest'),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','PROJECTION','projectionId',l->>'projectionId'),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','GENERATION','generation',jsonb_build_object('kind','CANONICAL_FACT','factProfileId',l->>'factProfileId','canonicalGeneration',l->>'canonicalGeneration')),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','BLOCK_RANGE','chainId',l->>'chainId','genesisDigest',l->>'genesisDigest','fromBlock',l->>'blockNumber','throughBlock',l->>'blockNumber'),NEW.participant_id,NEW.privacy_domain_id);
 IF NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c WHERE c.participant_id=NEW.participant_id
  AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND c.receipt_digest=p->>'receiptDigest' AND c.sequence::text=p->>'sourceSequence'
  AND c.occurred_at=(p->>'admittedAt')::timestamptz) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE encoded jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 encoded:=openpc.evidence_hold_selector_encoding(NEW.selector,NEW.participant_id,NEW.privacy_domain_id);
 IF NEW.selector_type IS DISTINCT FROM NEW.selector->>'type'
  OR openpc.business_cbor(NEW.selector_cbor) IS DISTINCT FROM encoded THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF NEW.selector_type='PARTICIPANT' AND NOT EXISTS(SELECT 1 FROM control.participant p
  WHERE p.participant_id=NEW.participant_id AND p.root_privacy_domain_id=NEW.privacy_domain_id)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACTIVE' OR NEW.revision<>1 OR NEW.creation_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>(CASE WHEN NEW.selector_type='PARTICIPANT' THEN 'ACT-EVIDENCE_HOLDS_CREATE_PARTICIPANT-V1' ELSE 'ACT-EVIDENCE_HOLDS_CREATE_RESOURCE-V1' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.effective_at:=NEW.created_at;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','revision','release_operation_id','release_approval_request_id','updated_at']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','revision','release_operation_id','release_approval_request_id','updated_at'])
   OR OLD.state<>'ACTIVE' OR NEW.state<>'RELEASED' OR NEW.revision<>2
   OR NEW.release_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>(CASE WHEN NEW.selector_type='PARTICIPANT' THEN 'ACT-EVIDENCE_HOLDS_RELEASE_PARTICIPANT-V1' ELSE 'ACT-EVIDENCE_HOLDS_RELEASE_RESOURCE-V1' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_hold_coverage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE hold control.retention_hold%ROWTYPE; segment control.evidence_segment%ROWTYPE; expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT hold FROM control.retention_hold WHERE participant_id=NEW.participant_id
  AND (selector_type='PARTICIPANT' OR privacy_domain_id=NEW.privacy_domain_id) AND retention_hold_id=NEW.retention_hold_id;
 SELECT * INTO STRICT segment FROM control.evidence_segment WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND segment_id=NEW.segment_id;
 IF hold.revision<>NEW.hold_revision OR segment.object_digest<>NEW.object_digest
  OR NOT openpc.evidence_hold_requires_coverage(hold,NEW.stream_id,NEW.segment_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('version','OPENPC_EVIDENCE_HOLD_ACK_V1','object',jsonb_build_object(
  'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'streamId',NEW.stream_id,
  'sinkId',NEW.sink_id,'segmentId',NEW.segment_id::text,'objectDigest',NEW.object_digest,
  'firstSequence',segment.first_sequence::text,'throughSequence',segment.through_sequence::text,
  'previousSegmentDigest',segment.previous_segment_digest,'keyId',segment.key_id,
  'retentionUntil',to_char(segment.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'holdId',hold.retention_hold_id::text,'selectorDigest',hold.selector_digest,'revision',hold.revision::text,
  'state',hold.state,'operationId',coalesce(hold.release_operation_id,hold.creation_operation_id)::text,
  'assurance','LOCAL_FSYNC_READBACK');
 IF NEW.receipt-'receiptDigest' IS DISTINCT FROM expected OR NEW.receipt->>'receiptDigest' IS DISTINCT FROM NEW.receipt_digest
  OR NEW.receipt_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.acknowledged_at:=clock_timestamp(); RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_kms_exchange()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a control.evidence_kms_attempt; i control.evidence_kms_installation; request jsonb; pack jsonb;
 p jsonb; r jsonb; f jsonb; k jsonb; item text; now_ms numeric; original_key text; original_use text; fields text[];
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.evidence_kms_attempt WHERE participant_id=NEW.participant_id
 AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id FOR UPDATE;
 SELECT * INTO STRICT i FROM control.evidence_kms_installation WHERE participant_id=a.participant_id
 AND privacy_domain_id=a.privacy_domain_id AND installation_digest=a.installation_digest;
 PERFORM openpc.evidence_export_producer_authority(i.producer_trust_digest);
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||i.installation_id::text,0));
 SELECT * INTO STRICT i FROM control.evidence_kms_installation WHERE participant_id=a.participant_id
 AND privacy_domain_id=a.privacy_domain_id AND installation_digest=a.installation_digest;
 request:=convert_from(NEW.request_bytes,'UTF8')::jsonb;
 IF NEW.request_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(request),'UTF8')
 OR request->>'operation' IS DISTINCT FROM NEW.kind OR request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
 OR request->>'challenge' IS DISTINCT FROM NEW.challenge
 OR request->'recipient' IS DISTINCT FROM jsonb_build_object('participantId',a.participant_id::text,
 'privacyDomainId',a.privacy_domain_id::text,'installationDigest',a.installation_digest,'producerTrustDigest',i.producer_trust_digest)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE'; END IF;
 IF NEW.kind='PREPARE' THEN
  IF NEW.exchange_id<>NEW.attempt_id OR NEW.request_bytes<>a.request_bytes THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ORIGINAL'; END IF;
  original_key:='sha256:'||repeat('0',64); original_use:='NONE';
 ELSE
  fields:=ARRAY['operation','exchangeId','attemptId','recipient','originalRequestDigest','objectIntentDigest','keyId','keyUse','challenge'];
  IF NEW.kind='READ_ATTEMPT' THEN fields:=fields||ARRAY['readExchangeId','readRequestDigest']; END IF;
  IF jsonb_typeof(request) IS DISTINCT FROM 'object' OR request-fields IS DISTINCT FROM '{}'::jsonb OR NOT request ?& fields
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-SHAPE'; END IF;
  IF request->>'exchangeId' IS DISTINCT FROM NEW.exchange_id::text
  OR request->>'originalRequestDigest' IS DISTINCT FROM a.request_digest
  OR request->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ORIGINAL'; END IF;
  original_key:=request->>'keyId'; original_use:=request->>'keyUse';
  IF NEW.kind='READ_ATTEMPT' AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange target
   WHERE target.participant_id=a.participant_id AND target.privacy_domain_id=a.privacy_domain_id
   AND target.attempt_id=a.attempt_id AND target.exchange_id::text=request->>'readExchangeId'
   AND target.request_digest=request->>'readRequestDigest' AND target.kind IN ('PREPARE','UNWRAP'))
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-READBACK-TARGET'; END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' OR NEW.receipt_bytes IS NOT NULL THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE'; END IF;
  IF NEW.kind='UNWRAP' THEN
   IF a.state<>'PROVED' OR original_use NOT IN ('ENCRYPT','DECRYPT') OR NOT EXISTS(SELECT 1 FROM control.evidence_wrapped_key
    WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND key_id=original_key)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-UNWRAP'; END IF;
   IF original_use='ENCRYPT' AND EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=a.participant_id
     AND e.privacy_domain_id=a.privacy_domain_id AND e.attempt_id=a.attempt_id AND e.kind='UNWRAP'
     AND convert_from(e.request_bytes,'UTF8')::jsonb->>'keyUse'='ENCRYPT')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-NO-RESEAL'; END IF;
   IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=a.participant_id
    AND e.privacy_domain_id=a.privacy_domain_id AND e.attempt_id=a.attempt_id AND e.kind='UNWRAP'
    AND e.state IN ('PREPARED','DISPATCHED','UNKNOWN') AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange done
      WHERE done.participant_id=e.participant_id AND done.privacy_domain_id=e.privacy_domain_id AND done.attempt_id=e.attempt_id
      AND done.kind='READ_ATTEMPT' AND done.state='PROVED' AND openpc.evidence_kms_stored_outcome(done.receipt_bytes) IN ('1','2')
      AND convert_from(done.request_bytes,'UTF8')::jsonb->>'readExchangeId'=e.exchange_id::text
      AND convert_from(done.request_bytes,'UTF8')::jsonb->>'readRequestDigest'=e.request_digest))
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-UNKNOWN'; END IF;
  ELSIF original_use IS DISTINCT FROM 'NONE' THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-KEY-USE'; END IF;
  IF NEW.kind<>'READ_ATTEMPT' AND (i.state<>'ACTIVE' OR NOT i.pins->'permissions' ? CASE WHEN original_use='DECRYPT' THEN 'DECRYPT' ELSE 'ENCRYPT' END)
  THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
  RETURN NEW;
 END IF;
 IF to_jsonb(OLD)-ARRAY['state','receipt_bytes','receipt_digest','provider_sequence','recovery_floor'] IS DISTINCT FROM
 to_jsonb(NEW)-ARRAY['state','receipt_bytes','receipt_digest','provider_sequence','recovery_floor']
 THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.state IN ('DISPATCHED','UNKNOWN') THEN
  IF NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state IN ('DISPATCHED','UNKNOWN') AND NEW.state='UNKNOWN'))
  OR NEW.receipt_bytes IS NOT NULL OR NEW.provider_sequence IS NOT NULL OR NEW.recovery_floor IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-TRANSITION'; END IF;
  IF NEW.state='DISPATCHED' AND NEW.kind<>'READ_ATTEMPT' AND (i.state<>'ACTIVE'
   OR NOT i.pins->'permissions' ? CASE WHEN original_use='DECRYPT' THEN 'DECRYPT' ELSE 'ENCRYPT' END
   OR floor(extract(epoch from clock_timestamp())*1000)<(i.pins->>'validFromMs')::numeric
   OR floor(extract(epoch from clock_timestamp())*1000)>=(i.pins->>'validUntilMs')::numeric)
   THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.state NOT IN ('DISPATCHED','UNKNOWN') OR NEW.state<>'PROVED' THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-TRANSITION'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-kms-provider-key:'||jsonb_build_array(
  NEW.participant_id,NEW.privacy_domain_id,i.pins->>'providerId',i.pins->>'providerKeyId',i.pins->>'providerKeyVersion')::text,0));
 IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e
   JOIN control.evidence_kms_attempt prior USING(participant_id,privacy_domain_id,attempt_id)
   JOIN control.evidence_kms_installation prior_i USING(participant_id,privacy_domain_id,installation_digest)
   WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND prior_i.pins->>'providerId'=i.pins->>'providerId' AND prior_i.pins->>'providerKeyId'=i.pins->>'providerKeyId'
   AND prior_i.pins->>'providerKeyVersion'=i.pins->>'providerKeyVersion'
   AND (e.provider_sequence>NEW.provider_sequence OR e.recovery_floor>NEW.recovery_floor))
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECOVERY-FLOOR'; END IF;
 pack:=convert_from(NEW.receipt_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(pack) IS DISTINCT FROM 'object' OR pack-ARRAY['profile','receipt','record','recovery'] IS DISTINCT FROM '{}'::jsonb
 OR NOT pack ?& ARRAY['profile','receipt','record','recovery']
 OR NEW.receipt_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(pack),'UTF8') THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PACK'; END IF;
 FOREACH item IN ARRAY ARRAY['profile','receipt','record','recovery'] LOOP
  IF jsonb_typeof(pack->item) IS DISTINCT FROM 'object' OR (pack->item)-ARRAY['payloadHex','coseHex'] IS DISTINCT FROM '{}'::jsonb
  OR NOT (pack->item) ?& ARRAY['payloadHex','coseHex']
  OR NOT coalesce(pack->item->>'payloadHex' ~ '^([0-9a-f]{2})*$',false)
  OR NOT coalesce(pack->item->>'coseHex' ~ '^([0-9a-f]{2})*$',false) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PACK'; END IF;
 END LOOP;
 p:=openpc.evidence_kms_cose_binding(decode(pack->'profile'->>'payloadHex','hex'),decode(pack->'profile'->>'coseHex','hex'),
 'EvidenceKmsProfileV1','sha256:'||encode(sha256(decode(i.pins->>'profileIssuerSpkiHex','hex')),'hex'));
 IF 'sha256:'||encode(sha256(decode(pack->'profile'->>'coseHex','hex')),'hex') IS DISTINCT FROM i.pins->>'profileDigest'
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PROFILE'; END IF;
 r:=openpc.evidence_kms_cose_binding(decode(pack->'receipt'->>'payloadHex','hex'),decode(pack->'receipt'->>'coseHex','hex'),
 'EvidenceKmsReceiptV1','sha256:'||encode(sha256(decode(i.pins->>'providerReceiptSpkiHex','hex')),'hex'));
 f:=openpc.evidence_kms_cose_binding(decode(pack->'recovery'->>'payloadHex','hex'),decode(pack->'recovery'->>'coseHex','hex'),
 'EvidenceKmsReceiptV1','sha256:'||encode(sha256(decode(i.pins->>'recoveryAuthoritySpkiHex','hex')),'hex'));
 FOREACH item IN ARRAY ARRAY['environmentId','participantId','privacyDomainId','providerId','reference','version','providerKeyId','providerKeyVersion','keyEpoch','wrapProfileDigest','policyDigest','recoveryProfileDigest'] LOOP
  IF r->>item IS DISTINCT FROM i.pins->>item OR f->>item IS DISTINCT FROM i.pins->>item OR p->>item IS DISTINCT FROM i.pins->>item
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-SCOPE'; END IF;
 END LOOP;
 IF r->>'operation' IS DISTINCT FROM (CASE NEW.kind WHEN 'PREPARE' THEN '1' WHEN 'READ_ATTEMPT' THEN '2' WHEN 'STATUS' THEN '3' WHEN 'UNWRAP' THEN '4' END)
 OR r->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR r->>'exchangeId' IS DISTINCT FROM NEW.exchange_id::text
 OR r->>'requestDigest' IS DISTINCT FROM NEW.request_digest OR r->>'challenge' IS DISTINCT FROM NEW.challenge
 OR r->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest OR r->>'profileDigest' IS DISTINCT FROM i.pins->>'profileDigest'
 OR r->>'keyUse' IS DISTINCT FROM (CASE original_use WHEN 'NONE' THEN '1' WHEN 'ENCRYPT' THEN '2' WHEN 'DECRYPT' THEN '3' END)
 OR r->>'providerSequence' IS DISTINCT FROM NEW.provider_sequence::text OR r->>'recoveryFloor' IS DISTINCT FROM NEW.recovery_floor::text
 OR f->>'operation' IS DISTINCT FROM '5' OR f->>'keyUse' IS DISTINCT FROM '1' OR f->>'outcome' IS DISTINCT FROM '1'
 OR f-ARRAY['operation','keyUse','outcome','materialDigest','receiptId','signerKeyId','observedAtMs','validUntilMs'] IS DISTINCT FROM
 r-ARRAY['operation','keyUse','outcome','materialDigest','receiptId','signerKeyId','observedAtMs','validUntilMs']
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECEIPT'; END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF (r->>'observedAtMs')::numeric>now_ms OR (r->>'observedAtMs')::numeric<now_ms-5000 OR (r->>'validUntilMs')::numeric<=now_ms
 OR (r->>'validUntilMs')::numeric-(r->>'observedAtMs')::numeric NOT BETWEEN 1 AND 5000
 OR (f->>'observedAtMs')::numeric>now_ms OR (f->>'observedAtMs')::numeric<now_ms-5000 OR (f->>'validUntilMs')::numeric<=now_ms
 OR (f->>'validUntilMs')::numeric-(f->>'observedAtMs')::numeric NOT BETWEEN 1 AND 5000
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-STALE'; END IF;
 IF original_key<>'sha256:'||repeat('0',64) AND r->>'keyId' IS DISTINCT FROM original_key THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-KEY'; END IF;
 IF NEW.kind='UNWRAP' AND r->>'outcome'='1' THEN
  IF i.state<>'ACTIVE' OR NOT i.pins->'permissions' ? original_use OR r->>'keyState' NOT IN ('1','2')
  OR (original_use='ENCRYPT' AND r->>'keyState'<>'1') OR now_ms<(i.pins->>'validFromMs')::numeric
  OR now_ms>=(i.pins->>'validUntilMs')::numeric OR r->>'materialDigest'='sha256:'||repeat('0',64)
  THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
 ELSIF r->>'materialDigest' IS DISTINCT FROM 'sha256:'||repeat('0',64) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-MATERIAL'; END IF;
 IF pack->'record'->>'payloadHex'<>'' THEN
  k:=openpc.evidence_kms_cose_binding(decode(pack->'record'->>'payloadHex','hex'),decode(pack->'record'->>'coseHex','hex'),
   'EvidenceWrappedKeyRecordV1','sha256:'||encode(sha256(decode(i.pins->>'providerReceiptSpkiHex','hex')),'hex'));
  FOREACH item IN ARRAY ARRAY['environmentId','participantId','privacyDomainId','providerId','reference','version','providerKeyId','providerKeyVersion','keyEpoch','wrapProfileDigest','policyDigest','recoveryProfileDigest'] LOOP
   IF k->>item IS DISTINCT FROM i.pins->>item THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-SCOPE'; END IF;
  END LOOP;
  IF k->>'attemptId' IS DISTINCT FROM a.attempt_id::text OR k->>'originalRequestDigest' IS DISTINCT FROM a.request_digest
   OR k->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest OR k->>'profileDigest' IS DISTINCT FROM i.pins->>'profileDigest'
   OR r->>'keyId' IS DISTINCT FROM 'sha256:'||encode(sha256(decode(pack->'record'->>'payloadHex','hex')),'hex')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD'; END IF;
 ELSE
  IF pack->'record'->>'coseHex'<>'' OR (NEW.kind IN ('PREPARE','READ_ATTEMPT','UNWRAP') AND r->>'outcome'='1')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD'; END IF;
 END IF;
 RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005';
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_evidence_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE segment control.evidence_segment%ROWTYPE; envelope jsonb; expected jsonb; head numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  PERFORM openpc.record_evidence_payload_deletion(OLD);
  RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT segment FROM control.evidence_segment s WHERE s.participant_id=NEW.participant_id
  AND s.privacy_domain_id=NEW.privacy_domain_id AND s.stream_id=NEW.stream_id AND s.segment_id=NEW.segment_id;
 SELECT last_sequence INTO STRICT head FROM control.evidence_stream WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id FOR UPDATE;
 IF segment.first_sequence<=head THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF segment.object_digest<>'sha256:'||encode(sha256(NEW.encrypted_segment),'hex') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 envelope:=convert_from(NEW.encrypted_segment,'UTF8')::jsonb;
 expected:=jsonb_build_object('version','OPENPC_EVIDENCE_SEGMENT_V1','participantId',segment.participant_id::text,
  'privacyDomainId',segment.privacy_domain_id::text,'streamId',segment.stream_id,'segmentId',segment.segment_id::text,
  'firstSequence',segment.first_sequence::text,'throughSequence',segment.through_sequence::text,'previousSegmentDigest',segment.previous_segment_digest,
  'keyId',segment.key_id,'retentionUntil',to_char(segment.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 IF envelope->'header' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_explorer_custody()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' OR current_setting('openpc.action_intent_id')<>'ACT-PRIVACY_EXPLORER_READ_PROJECTION-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN
  RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-CUSTODY';
 END IF;
 IF TG_TABLE_NAME='privacy_explorer_execution' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.revision<>0 OR NEW.disposition<>'OPEN' OR NEW.evidence IS NOT NULL
    OR NEW.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   NEW.created_at:=clock_timestamp();
  ELSE
   IF OLD.disposition<>'OPEN' OR
    (to_jsonb(NEW)-ARRAY['snapshot','revision','disposition','evidence','evidence_digest','release_claim_id','release_authorized_at','updated_at'])
      IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['snapshot','revision','disposition','evidence','evidence_digest','release_claim_id','release_authorized_at','updated_at']) THEN
    RAISE EXCEPTION 'PC-DATA-6007';
   END IF;
   IF NEW.revision=OLD.revision THEN
    IF NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.evidence IS DISTINCT FROM OLD.evidence
     OR NEW.evidence_digest IS DISTINCT FROM OLD.evidence_digest
     OR NEW.disposition NOT IN ('RELEASE_AUTHORIZED','INTERRUPTED') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   ELSIF NEW.revision<>OLD.revision+1 OR NEW.disposition NOT IN ('OPEN','SUPPRESSED')
     OR OLD.evidence IS NOT NULL THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   IF NEW.disposition='RELEASE_AUTHORIZED' AND NEW.deadline_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'PC-OPS-9003';
   END IF;
  END IF;
  NEW.updated_at:=clock_timestamp();
 ELSE
  IF TG_OP='INSERT' AND NEW.consumed_by IS NOT NULL THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  IF TG_OP='UPDATE' AND (OLD.consumed_by IS NOT NULL OR NEW.consumed_by IS NULL
    OR (to_jsonb(NEW)-'consumed_by') IS DISTINCT FROM (to_jsonb(OLD)-'consumed_by')) THEN
    RAISE EXCEPTION 'PC-DATA-6007';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_explorer_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.profile_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.profile-'digest'),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'REGISTERED' OR NEW.revision<>1 OR NEW.revocation_operation_id IS NOT NULL
   OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-PRIVACY_EXPLORER_PROFILES_CREATE_RESOURCE-V1' THEN
   RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE';
  END IF;
  NEW.created_at:=clock_timestamp();
 ELSE
  PERFORM pg_advisory_xact_lock(hashtextextended('privacy-explorer-profile:'||OLD.registration_id::text,0));
  IF (to_jsonb(NEW)-ARRAY['state','revision','revocation_operation_id']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','revision','revocation_operation_id'])
   OR OLD.state<>'REGISTERED' OR NEW.state<>'REVOKED' OR NEW.revision<>OLD.revision+1
   OR NEW.revocation_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-PRIVACY_EXPLORER_PROFILES_REVOKE_RESOURCE-V1' THEN
   RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_fact_admission_cursor()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE amount bigint;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.sequence<>0 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CURSOR'; END IF;
 ELSE
  IF row(NEW.participant_id,NEW.privacy_domain_id,NEW.fact_type) IS DISTINCT FROM row(OLD.participant_id,OLD.privacy_domain_id,OLD.fact_type)
   OR NEW.sequence<=OLD.sequence OR NEW.sequence>OLD.sequence+256 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CURSOR'; END IF;
  SELECT count(*) INTO amount FROM control.evidence_fact_admission_inbox i WHERE i.participant_id=NEW.participant_id
   AND i.privacy_domain_id=NEW.privacy_domain_id AND i.fact_type=NEW.fact_type AND i.sequence>OLD.sequence AND i.sequence<=NEW.sequence;
  IF amount<>NEW.sequence-OLD.sequence THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-GAP'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_handover_admission_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control'
AS $function$
DECLARE candidate_row control.mutation_candidate;
BEGIN
 IF NEW.action_intent_id='ACT-WORKLOAD_SIGNING_HANDOVERS_ACTIVATE_RESOURCE-V1' THEN
  IF NEW.subject_type<>'CONFIGURATION_CANDIDATE' THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-APPROVAL-SUBJECT'; END IF;
  SELECT * INTO STRICT candidate_row FROM control.mutation_candidate WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND mutation_candidate_id=NEW.subject_id
    AND maker_principal_id=NEW.maker_principal_id AND candidate_digest=NEW.subject_digest;
  IF TG_OP='INSERT' OR (NEW.state='APPROVED' AND OLD.state IS DISTINCT FROM 'APPROVED') THEN
   PERFORM openpc.assert_handover_admission_candidate(candidate_row);
   IF NEW.expires_at>candidate_row.expires_at THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-APPROVAL-EXPIRY'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_handover_admission_candidate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control'
AS $function$
BEGIN
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-SIGNING-HANDOVER-ADMIT' THEN
  IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-WORKLOAD_SIGNING_HANDOVERS_ACTIVATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-ADMISSION-STAGING'; END IF;
  PERFORM openpc.assert_handover_admission_candidate(NEW);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_identity_runtime_scope_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'identity authority scope versions cannot be reset'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.version<>1 THEN RAISE EXCEPTION 'identity authority scopes start at version one'; END IF;
    RETURN NEW;
  END IF;
  IF (NEW.participant_id,NEW.domain_code,NEW.scope_digest,NEW.scope_cbor) IS DISTINCT FROM (OLD.participant_id,OLD.domain_code,OLD.scope_digest,OLD.scope_cbor)
    OR (NEW.source_state_digest=OLD.source_state_digest AND NEW.version<>OLD.version)
    OR (NEW.source_state_digest<>OLD.source_state_digest AND NEW.version<>OLD.version+1)
  THEN RAISE EXCEPTION 'identity authority scope version transition rejected'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_installed_secret_recipient()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'openpc', 'control'
AS $function$
BEGIN
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE') THEN
   RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('secret-recipient:'||coalesce(NEW.participant_id,OLD.participant_id)::text||':'||coalesce(NEW.privacy_domain_id,OLD.privacy_domain_id)::text,0));
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND
   (OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR
    (to_jsonb(OLD)-'state') IS DISTINCT FROM (to_jsonb(NEW)-'state'))) THEN
   RAISE EXCEPTION 'OPS-SECRET-INSTALLATION-IMMUTABLE';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_logical_contract_asset_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE expected text;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'logical_contract_asset' OR TG_OP NOT IN ('INSERT','UPDATE')
 THEN RAISE EXCEPTION 'DATA-6004-CONTRACT-REGISTRATION-OWNER'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'DATA-6001-CONTEXT-INVALID'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.participant_id IS DISTINCT FROM OLD.participant_id OR NEW.privacy_domain_id IS DISTINCT FROM OLD.privacy_domain_id
    OR NEW.policy_generation_digest IS DISTINCT FROM OLD.policy_generation_digest
  THEN RAISE EXCEPTION 'DATA-6007-CONTRACT-REGISTRATION-IMMUTABLE'; END IF;
 ELSE
  expected:=openpc.configuration_policy_provenance(NEW.participant_id,NEW.privacy_domain_id);
  IF NEW.policy_generation_digest IS DISTINCT FROM expected
  THEN RAISE EXCEPTION 'DATA-6007-CONTRACT-REGISTRATION-PROVENANCE'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_mfa_challenge_resource()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.verified_proof_max_age_ms=3000000 AND (
    NEW.consumed_at IS NOT NULL OR NEW.used_at IS NOT NULL
    OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
    OR current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X'
    OR NEW.action_intent_id IS DISTINCT FROM openpc.current_action_intent_id()
    OR NOT EXISTS (SELECT 1 FROM control.session session
      WHERE session.participant_id=NEW.participant_id AND session.session_id=NEW.session_id
        AND session.principal_id=NEW.principal_id AND session.duration_profile='LOCAL_QA_10X'
        AND session.state='ACTIVE' AND session.idle_expires_at>clock_timestamp()
        AND session.absolute_expires_at>clock_timestamp()
        AND NEW.expires_at<=session.idle_expires_at AND NEW.expires_at<=session.absolute_expires_at)
  ) THEN RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-DURATION-PROVENANCE'; END IF;
  RETURN NEW;
 END IF;
 IF (NEW.participant_id,NEW.session_id,NEW.principal_id,NEW.action_intent_id,NEW.resource_id,
     NEW.resource_digest,NEW.challenge_digest,NEW.rp_id_hash,NEW.created_at,NEW.verified_proof_max_age_ms)
 IS DISTINCT FROM
    (OLD.participant_id,OLD.session_id,OLD.principal_id,OLD.action_intent_id,OLD.resource_id,
     OLD.resource_digest,OLD.challenge_digest,OLD.rp_id_hash,OLD.created_at,OLD.verified_proof_max_age_ms) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-BINDING-IMMUTABLE';
 END IF;
 IF NEW.expires_at>OLD.expires_at THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-EXPIRY-EXTENSION';
 END IF;
 IF OLD.consumed_at IS NOT NULL AND
   (NEW.consumed_at,NEW.signer_credential_id,NEW.signer_credential_epoch)
   IS DISTINCT FROM (OLD.consumed_at,OLD.signer_credential_id,OLD.signer_credential_epoch) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-VERIFICATION-IMMUTABLE';
 END IF;
 IF OLD.used_at IS NOT NULL AND (NEW.used_at,NEW.used_operation_id) IS DISTINCT FROM (OLD.used_at,OLD.used_operation_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-CONSUMPTION-IMMUTABLE';
 END IF;
 IF OLD.consumed_at IS NULL AND NEW.consumed_at IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM control.credential credential WHERE credential.participant_id=NEW.participant_id
    AND credential.principal_id=NEW.principal_id AND credential.credential_id=NEW.signer_credential_id
    AND credential.credential_epoch=NEW.signer_credential_epoch AND credential.kind='WEBAUTHN'
    AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
    AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-VERIFICATION-SIGNER'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_module_reference_write_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'DATA-6020-MODULE-REFERENCE-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF TG_TABLE_NAME IN ('module_version','module_dependency','module_capability') AND
  NOT pg_try_advisory_xact_lock(hashtextextended('module-release-catalog',0)) THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6007';
 END IF;
 IF openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6001';
 END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||
  openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0)) THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6007';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_async_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE work control.notification_async_work%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_async_worker_owner();
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-TRANSITION-IMMUTABLE'; END IF;
 SELECT * INTO STRICT work FROM control.notification_async_work WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() OR NEW.revision<>work.revision
 OR NEW.proof_event_id IS DISTINCT FROM work.transition_event_id
 OR NEW.transition->>'proofEventId' IS DISTINCT FROM NEW.proof_event_id::text
 OR NEW.transition->'after' IS DISTINCT FROM to_jsonb(work)
 OR NEW.transition IS DISTINCT FROM convert_from(NEW.transition_bytes,'UTF8')::jsonb
 OR convert_to(openpc.signing_canonical_json(NEW.transition),'UTF8') IS DISTINCT FROM NEW.transition_bytes
 OR pg_trigger_depth()<2 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-TRANSITION'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_async_work()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE source control.outbox_event%ROWTYPE;now_ms numeric;lock_name text;pre_effect text;initial_reason text;
BEGIN
 PERFORM openpc.assert_notification_async_worker_owner();
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-SCOPE'; END IF;
 SELECT * INTO STRICT source FROM control.outbox_event WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 PERFORM openpc.check_notification_delivery_requested_event(source);
 IF source.aggregate_type<>'notification-occurrence' OR source.aggregate_id<>NEW.notification_occurrence_id
 OR source.sequence_namespace<>'NOTIFICATION_DELIVERY_REQUESTED_V1' OR source.business_sequence<>NEW.sequence
 OR NEW.partition<>source.aggregate_type||':'||source.aggregate_id::text
 OR NEW.payload_bytes IS DISTINCT FROM octet_length(source.payload_cbor)
 OR NEW.source_digest IS DISTINCT FROM 'sha256:'||encode(source.payload_digest,'hex')
 OR NEW.published_at_ms IS DISTINCT FROM floor(extract(epoch from source.occurred_at)*1000)
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-SOURCE'; END IF;
 -- The canonical native SQL owner verifies limits, original artifact custody,
 -- actual mounted process and issuer/reviewer/current source fences itself.
 -- payload_bytes is receipt-envelope queue occupancy, NOT delivered body size.
 -- For live PENDING only, native maximumPayloadBytes MUST compare the body from
 -- read_notification_delivery_payload_size(event_id,worker_installation_digest)
 -- at INSERT, and verified immutable preparation attempt.payloadBytes at effects.
 EXECUTE 'select openpc.assert_notification_async_work_current($1)' USING NEW;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF TG_OP='INSERT' THEN
  initial_reason:=openpc.notification_async_initial_disposition(NEW.event_id,NEW.worker_installation_digest,NEW.deadline_at_ms);
  IF NEW.revision<>1 OR NEW.lease_epoch<>0 OR NEW.lease_owner IS NOT NULL OR NEW.lease_until_ms IS NOT NULL
  OR NEW.charged OR NEW.effect_uncertain OR NEW.original IS NOT NULL OR NEW.next_at_ms IS NOT NULL
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-INITIAL'; END IF;
  IF initial_reason IS NOT NULL THEN
   IF NEW.state<>'QUARANTINED' OR NEW.reason IS DISTINCT FROM initial_reason
   THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION'; END IF;
  ELSE
   PERFORM openpc.read_notification_delivery_payload_size(NEW.event_id,NEW.worker_installation_digest);
   IF NEW.state<>'PENDING' OR NEW.reason IS NOT NULL OR NEW.deadline_at_ms<=now_ms
   THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-INITIAL'; END IF;
  END IF;
 ELSE
  IF NEW.reason IN ('INITIAL_DOMAIN_DEADLINE','INITIAL_SOURCE_WITHDRAWN')
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-INITIAL-ONLY'; END IF;
  IF OLD.state='QUARANTINED' AND OLD.revision=1 AND OLD.lease_epoch=0 AND NOT OLD.charged AND NOT OLD.effect_uncertain
   AND OLD.reason IN ('INITIAL_DOMAIN_DEADLINE','INITIAL_SOURCE_WITHDRAWN')
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-TERMINAL'; END IF;
  IF to_jsonb(NEW)-ARRAY['state','lease_owner','lease_epoch','lease_until_ms','charged','effect_uncertain','next_at_ms','original','reason','revision','transition_event_id']
   IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','lease_owner','lease_epoch','lease_until_ms','charged','effect_uncertain','next_at_ms','original','reason','revision','transition_event_id']
  OR NEW.revision<>OLD.revision+1 OR NEW.lease_epoch<OLD.lease_epoch OR NEW.lease_epoch>OLD.lease_epoch+1
  OR OLD.state IN ('DONE','CANCELLED') OR NEW.transition_event_id=OLD.transition_event_id
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-IMMUTABLE'; END IF;
  IF NEW.lease_epoch>OLD.lease_epoch THEN
   lock_name:='notification-work-effect:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.event_id::text;
   IF NOT pg_try_advisory_xact_lock(hashtextextended(lock_name,0)) THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-EFFECT-HELD'; END IF;
   pre_effect:=openpc.notification_async_pre_effect_phase(NEW.event_id);
   IF OLD.state NOT IN ('PENDING','RETRY_WAIT','LEASED','RECONCILING','QUARANTINED')
   OR (OLD.state='RETRY_WAIT' AND OLD.next_at_ms>now_ms) OR OLD.deadline_at_ms<=now_ms
   OR NEW.state IS DISTINCT FROM (CASE WHEN OLD.effect_uncertain AND pre_effect NOT IN ('UNPREPARED','PREPARED','SIGNING_PREPARED') THEN 'RECONCILING' ELSE 'LEASED' END)
   OR NOT NEW.charged OR NOT NEW.effect_uncertain OR NEW.next_at_ms IS NOT NULL
   OR OLD.lease_until_ms>now_ms OR NEW.lease_owner IS NULL OR NEW.lease_until_ms<=now_ms
   OR (OLD.effect_uncertain AND pre_effect NOT IN ('UNPREPARED','PREPARED','SIGNING_PREPARED') AND (NEW.state<>'RECONCILING' OR NOT NEW.charged OR NOT NEW.effect_uncertain))
   THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-TAKEOVER'; END IF;
  ELSIF NEW.lease_owner IS DISTINCT FROM OLD.lease_owner AND NEW.lease_owner IS NOT NULL
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-EPOCH';
  ELSIF NEW.lease_owner IS NOT NULL THEN
   -- Same-epoch heartbeat changes no business/effect/source custody.
   IF OLD.lease_until_ms<=now_ms OR NEW.lease_until_ms<OLD.lease_until_ms
   OR to_jsonb(NEW)-ARRAY['lease_until_ms','revision','transition_event_id'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['lease_until_ms','revision','transition_event_id']
   THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-HEARTBEAT'; END IF;
  ELSE
   IF NOT ((OLD.state IN ('LEASED','RECONCILING') AND OLD.lease_owner IS NOT NULL
     AND NEW.state IN ('RETRY_WAIT','DONE','CANCELLED','QUARANTINED'))
    OR (OLD.state IN ('PENDING','RETRY_WAIT','LEASED','RECONCILING','QUARANTINED') AND (OLD.lease_until_ms IS NULL OR OLD.lease_until_ms<=now_ms)
     AND NEW.state='QUARANTINED' AND NOT NEW.charged AND NOT NEW.effect_uncertain AND NEW.reason='PRE_EFFECT_STALE'
     AND openpc.notification_async_pre_effect_phase(NEW.event_id)='STALE_PREPARED')
    OR (OLD.state IN ('PENDING','RETRY_WAIT') AND OLD.deadline_at_ms<=now_ms AND NEW.state='QUARANTINED'
     AND NEW.charged=OLD.charged AND NEW.effect_uncertain=OLD.effect_uncertain AND NEW.reason='DOMAIN_DEADLINE'))
   THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-SETTLEMENT'; END IF;
   lock_name:='notification-work-effect:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.event_id::text;
   IF NOT pg_try_advisory_xact_lock(hashtextextended(lock_name,0)) THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-EFFECT-HELD'; END IF;
  END IF;
  IF NEW.reason='PRE_EFFECT_STALE' AND (NEW.state<>'QUARANTINED' OR NEW.charged OR NEW.effect_uncertain
   OR openpc.notification_async_pre_effect_phase(NEW.event_id)<>'STALE_PREPARED')
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-PRE-EFFECT-STALE'; END IF;
  IF OLD.effect_uncertain AND NOT NEW.effect_uncertain THEN
   -- This is not a caller boolean. Native proof derives whether the original
   -- effect has actually resolved, and rejects unknown/absent observations.
   IF NEW.state NOT IN ('RETRY_WAIT','DONE','CANCELLED','QUARANTINED')
   THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-UNCERTAINTY'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_cancellation_signing()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 PERFORM openpc.check_notification_cancellation_signing_original(NEW);
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-INITIAL'; END IF;
  PERFORM openpc.check_notification_cancellation_signing_current(NEW);
 ELSE
  IF to_jsonb(NEW)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest']
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-IMMUTABLE'; END IF;
  IF OLD.state='PREPARED' AND NEW.state='DISPATCHED' THEN
   PERFORM openpc.check_notification_cancellation_signing_current(NEW);
   IF NEW.dispatched_at_ms IS DISTINCT FROM floor(extract(epoch from statement_timestamp())*1000)
   THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-TIME'; END IF;
  ELSIF OLD.state='DISPATCHED' AND NEW.state='OBSERVED' THEN
   IF NEW.dispatch_token IS DISTINCT FROM OLD.dispatch_token OR NEW.dispatched_at_ms IS DISTINCT FROM OLD.dispatched_at_ms THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-CLAIM'; END IF;
  ELSE RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-ONE-SHOT'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb;p jsonb;s control.notification_completion_source%ROWTYPE;previous control.notification_completion_attempt%ROWTYPE;n numeric;delay numeric;counted numeric;source_valid boolean;failure text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-IMMUTABLE'; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'FINISH' END);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'FINISH' END);
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-completion-source:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.event_id::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF EXISTS(SELECT 1 FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id) THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-SEALED'; END IF;
 a:=NEW.attempt;n:=floor(extract(epoch from clock_timestamp())*1000);
 IF a-ARRAY['attemptId','number','workerInstallationDigest','authorityDigest','claimedAtMs','leaseUntilMs','state','finishedAtMs','nextAttemptAtMs'] IS DISTINCT FROM '{}'::jsonb
 OR NOT a ?& ARRAY['attemptId','number','workerInstallationDigest','authorityDigest','claimedAtMs','leaseUntilMs','state','finishedAtMs','nextAttemptAtMs']
 OR a->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR a->'number' IS DISTINCT FROM to_jsonb(NEW.number)
 OR NEW.attempt_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(a),'UTF8') OR NEW.attempt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.attempt_bytes),'hex')
 OR (a->>'authorityDigest' ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
 OR (a->>'workerInstallationDigest' ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
 OR (jsonb_typeof(a->'claimedAtMs')='number' AND (a->>'claimedAtMs') ~ '^(0|[1-9][0-9]*)$') IS DISTINCT FROM true
 OR (jsonb_typeof(a->'leaseUntilMs')='number' AND (a->>'leaseUntilMs') ~ '^(0|[1-9][0-9]*)$') IS DISTINCT FROM true
 OR (a->>'leaseUntilMs')::numeric<=(a->>'claimedAtMs')::numeric OR (a->>'leaseUntilMs')::numeric>(a->>'claimedAtMs')::numeric+30000
 THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-BINDING'; END IF;
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 p:=openpc.business_cbor(decode(s.initial_worker->'signed'->>'payloadHex','hex'));
 IF TG_OP='INSERT' THEN
  PERFORM openpc.check_notification_completion_effect_binding(NEW.event_id,'CLAIM',a->>'workerInstallationDigest',a->>'authorityDigest');
  SELECT count(*) INTO counted FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
  IF NEW.number<>counted+1 OR NEW.number>s.effective_limit OR a->>'state' IS DISTINCT FROM 'LEASED' OR a->'finishedAtMs' IS DISTINCT FROM 'null'::jsonb OR a->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb
   OR (a->>'claimedAtMs')::numeric>n OR (a->>'leaseUntilMs')::numeric<=n
  THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-ADMISSION'; END IF;
  IF NEW.number=1 THEN
   IF a->>'workerInstallationDigest' IS DISTINCT FROM s.initial_worker_installation_digest THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-FIRST'; END IF;
  ELSE
   SELECT * INTO STRICT previous FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id AND number=NEW.number-1;
   IF previous.attempt->>'state' NOT IN ('FAILED','RELEASED') OR (a->>'claimedAtMs')::numeric<(previous.attempt->>'nextAttemptAtMs')::numeric THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-BACKOFF'; END IF;
  END IF;
 ELSE
  IF to_jsonb(OLD)-ARRAY['attempt','attempt_bytes','attempt_digest'] IS DISTINCT FROM to_jsonb(NEW)-ARRAY['attempt','attempt_bytes','attempt_digest']
   OR OLD.attempt-ARRAY['state','finishedAtMs','nextAttemptAtMs'] IS DISTINCT FROM a-ARRAY['state','finishedAtMs','nextAttemptAtMs'] OR OLD.attempt->>'state' IS DISTINCT FROM 'LEASED'
   OR a->>'state' NOT IN ('VALIDATED','FAILED','RELEASED') OR (jsonb_typeof(a->'finishedAtMs')='number' AND (a->>'finishedAtMs') ~ '^(0|[1-9][0-9]*)$') IS DISTINCT FROM true
   OR (a->>'finishedAtMs')::numeric<(a->>'claimedAtMs')::numeric OR (a->>'finishedAtMs')::numeric>n
  THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-TRANSITION'; END IF;
  IF n<(OLD.attempt->>'leaseUntilMs')::numeric THEN
   PERFORM openpc.check_notification_completion_effect_binding(NEW.event_id,'FINISH',OLD.attempt->>'workerInstallationDigest',OLD.attempt->>'authorityDigest');
  END IF;
  IF a->>'state'='VALIDATED' THEN
   IF a->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb OR n>=(a->>'leaseUntilMs')::numeric OR (a->>'finishedAtMs')::numeric>=(a->>'leaseUntilMs')::numeric THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-EXPIRED'; END IF;
   PERFORM openpc.check_notification_completion_validated_source(NEW.event_id);
  ELSE
   IF a->>'state'='FAILED' AND (a->>'finishedAtMs')::numeric<(a->>'leaseUntilMs')::numeric THEN
    source_valid:=true;
    BEGIN
     PERFORM openpc.check_notification_completion_validated_source(NEW.event_id);
    EXCEPTION WHEN SQLSTATE 'P0001' THEN
     GET STACKED DIAGNOSTICS failure=MESSAGE_TEXT;
     IF failure NOT LIKE 'NOTIFICATION-OUTCOME-PUBLICATION-%' THEN RAISE; END IF;
     source_valid:=false;
    END;
    IF source_valid THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-FALSE-FAILURE'; END IF;
   END IF;
   delay:=least((p->>'19')::numeric,(p->>'18')::numeric*power(2,least(NEW.number-1,52)));
   IF a->'nextAttemptAtMs' IS DISTINCT FROM to_jsonb((a->>'finishedAtMs')::numeric+delay) THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-RETRY'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_disposition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'COMPLETION-DISPOSITION-IMMUTABLE'; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,'PUBLISH');
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,'PUBLISH');
 IF NEW.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.transition),'UTF8')
 OR NEW.transition->'receipt'->>'sourceEventId' IS DISTINCT FROM NEW.event_id::text
 OR NEW.transition->'receipt'->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR NEW.transition->'receipt'->>'receiptId' IS DISTINCT FROM NEW.receipt_id::text
 OR NEW.transition->'receipt'->>'disposition' IS DISTINCT FROM NEW.disposition
 OR NEW.receipt_payload IS DISTINCT FROM decode(NEW.transition->>'payloadHex','hex') OR NEW.cose_sign1 IS DISTINCT FROM decode(NEW.transition->>'coseHex','hex')
 THEN RAISE EXCEPTION 'COMPLETION-DISPOSITION-BINDING'; END IF;
 PERFORM openpc.check_notification_completion_disposition_signed(NEW.event_id,NEW.transition);
 PERFORM openpc.check_notification_completion_receipt_admission(NEW.event_id,'PUBLISH',
  (SELECT observation FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_signing()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE phase text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETION-SIGNING-IMMUTABLE'; END IF;
 phase:=CASE WHEN TG_OP='INSERT' THEN 'PREPARE' WHEN NEW.state='DISPATCHED' THEN 'SIGN_CLAIM' ELSE 'OBSERVE' END;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,phase);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,phase);
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' THEN RAISE EXCEPTION 'COMPLETION-SIGNING-INITIAL'; END IF;
  PERFORM openpc.check_notification_completion_signing_current(NEW.event_id,NEW.preparation,phase);
 ELSE
  IF to_jsonb(OLD)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest'] IS DISTINCT FROM to_jsonb(NEW)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest']
   OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state='DISPATCHED' AND NEW.state='OBSERVED' AND NEW.dispatch_token=OLD.dispatch_token AND NEW.dispatched_at_ms=OLD.dispatched_at_ms))
  THEN RAISE EXCEPTION 'COMPLETION-SIGNING-TRANSITION'; END IF;
  IF NEW.state='DISPATCHED' THEN
   PERFORM openpc.check_notification_completion_signing_current(NEW.event_id,NEW.preparation,phase);
   IF NEW.dispatched_at_ms IS DISTINCT FROM floor(extract(epoch from clock_timestamp())*1000) AND (NEW.dispatched_at_ms>(extract(epoch from clock_timestamp())*1000) OR NEW.dispatched_at_ms<(NEW.preparation->'preparation'->'metadata'->>'recordedAtMs')::numeric) THEN RAISE EXCEPTION 'COMPLETION-SIGNING-DISPATCH-TIME'; END IF;
  END IF;
  IF NEW.state='OBSERVED' THEN
   IF NEW.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.observation),'UTF8')
    OR NEW.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.observation_bytes),'hex') THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION'; END IF;
   PERFORM openpc.check_notification_completion_signing_observation(NEW.event_id,NEW.observation);
   IF NEW.observation->>'outcome'='SIGNED' THEN
    PERFORM openpc.check_notification_completion_receipt_admission(NEW.event_id,'OBSERVE',NEW.observation);
   END IF;
  END IF;
 END IF;
 IF NEW.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.preparation),'UTF8') OR NEW.request_digest IS DISTINCT FROM NEW.preparation->>'requestDigest'
 OR NEW.operation_id::text IS DISTINCT FROM NEW.preparation->'request'->>'operationId' OR NEW.signing_attempt_id::text IS DISTINCT FROM NEW.preparation->'request'->>'signingAttemptId'
 OR NEW.signer_installation_digest IS DISTINCT FROM NEW.preparation->'request'->>'signerInstallationDigest' OR NEW.event_id::text IS DISTINCT FROM NEW.preparation->'request'->>'sourceEventId'
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-BINDING'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p jsonb; m jsonb;e control.outbox_event%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;start_signer text;expected_selector jsonb;current_limit numeric;binding record;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETION-SOURCE-IMMUTABLE'; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'LIMIT' END);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'LIMIT' END);
 SELECT * INTO STRICT binding FROM openpc.notification_completion_phase_binding(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'LIMIT' END);
 IF TG_OP='INSERT' AND NEW.initial_worker_installation_digest IS DISTINCT FROM binding.installation_digest THEN RAISE EXCEPTION 'COMPLETION-SOURCE-WORKER'; END IF;
 IF TG_OP='UPDATE' THEN
  SELECT (openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex'))->>'17')::numeric INTO STRICT current_limit FROM control.installed_notification_completion_worker WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND state='ACTIVE' AND installation_digest=binding.installation_digest;
  IF to_jsonb(OLD)-'effective_limit' IS DISTINCT FROM to_jsonb(NEW)-'effective_limit' OR NEW.effective_limit IS DISTINCT FROM least(OLD.effective_limit,current_limit) OR NEW.effective_limit<1
   OR EXISTS(SELECT 1 FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id)
  THEN RAISE EXCEPTION 'COMPLETION-BUDGET-IMMUTABLE'; END IF;
  RETURN NEW;
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-completion-source:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.event_id::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 p:=NEW.source->'reference';
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.event_id AND operation_id=e.correlation_id;
 SELECT signer_installation_digest INTO STRICT start_signer FROM control.notification_delivery_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=o.start_operation_id;
 expected_selector:=jsonb_build_object('operationId',o.operation_id::text,'signerInstallationDigest',o.signer_installation_digest,
  'worker',jsonb_build_object('participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'installationDigest',o.worker_installation_digest),
  'original',jsonb_build_object('operationId',o.start_operation_id::text,'signerInstallationDigest',start_signer,
   'source',jsonb_build_object('notificationOccurrenceId',o.notification_occurrence_id::text,'eventId',o.transition->'input'->'observation'->'original'->'source'->>'eventId',
    'worker',jsonb_build_object('participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'installationDigest',o.transition->'input'->'observation'->'original'->>'workerInstallationDigest'))));
 IF NEW.source->'envelope' IS DISTINCT FROM openpc.notification_completion_source_envelope(e) OR NEW.original_selector IS DISTINCT FROM expected_selector
 OR p->>'dataDigest' IS DISTINCT FROM 'sha256:'||encode(e.payload_digest,'hex') OR p->>'receiptDigest' IS DISTINCT FROM o.receipt_digest
 OR p->>'partitionDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object('source','urn:openpc:service:LS-NOTIFICATION','notificationOccurrenceId',o.notification_occurrence_id::text)),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-ORIGINAL'; END IF;
 IF NEW.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.source),'UTF8')
 OR NEW.source_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.source_bytes),'hex')
 OR p->>'participantId' IS DISTINCT FROM NEW.participant_id::text OR p->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text OR p->>'eventId' IS DISTINCT FROM NEW.event_id::text
 OR NEW.source->'originalSelector' IS DISTINCT FROM NEW.original_selector
 OR p->>'envelopeDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.source->'envelope'),'UTF8')),'hex')
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_completion_worker w WHERE w.participant_id=NEW.participant_id AND w.privacy_domain_id=NEW.privacy_domain_id AND w.installation_digest=NEW.initial_worker_installation_digest AND w.installation=NEW.initial_worker AND w.state='ACTIVE')
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-BINDING'; END IF;
 m:=openpc.business_cbor(decode(NEW.initial_worker->'signed'->>'payloadHex','hex'));
 IF NEW.effective_limit IS DISTINCT FROM (m->>'17')::numeric
 OR p->>'producerTrustDigest' IS DISTINCT FROM NEW.initial_worker->'pins'->>'producerTrustDigest'
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_worker producer WHERE producer.participant_id=o.participant_id AND producer.privacy_domain_id=o.privacy_domain_id AND producer.installation_digest=o.worker_installation_digest AND openpc.business_cbor(decode(producer.installation->'signed'->>'payloadHex','hex'))->'16' IS NOT DISTINCT FROM openpc.business_bytes(decode(substr(p->>'producerTrustDigest',8),'hex')))
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-PROFILE'; END IF;
 PERFORM openpc.check_notification_completion_source_origin(NEW.event_id,p->>'receiptDigest');
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_attempt_atomic()
