 PERFORM openpc.check_notification_delivery_start_original(start);p:=start.transition;
 IF NEW.attempt_id IS DISTINCT FROM start.attempt_id OR NEW.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR NEW.payload_digest IS DISTINCT FROM start.payload_digest
 OR to_jsonb(NEW.attempt_number) IS DISTINCT FROM p->'attempt'->'attemptNumber' OR to_jsonb(NEW.started_at_ms) IS DISTINCT FROM p->'attempt'->'startedAtMs'
 OR NEW.worker_credential_id::text IS DISTINCT FROM p->'context'->>'authorizationContextId' OR NEW.worker_credential_epoch::numeric IS DISTINCT FROM (p->'context'->>'authorizationContextEpoch')::numeric
 THEN RAISE EXCEPTION 'NOTIFICATION-START-ATTEMPT'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_cancellation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d control.notification_delivery%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND notification_occurrence_id=NEW.notification_occurrence_id FOR UPDATE;
 IF jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest) IS DISTINCT FROM NEW.transition->'before' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STALE'; END IF;
 PERFORM openpc.check_notification_delivery_cancellation_original(NEW);
 IF to_regprocedure('openpc.check_notification_delivery_cancellation_signer(uuid,text)') IS NULL THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNER-UNBOUND'; END IF;
 EXECUTE 'select openpc.check_notification_delivery_cancellation_signer($1,$2)' USING NEW.operation_id,NEW.transition_digest;
 RETURN NEW;
END $function$

