 OR NEW.claim_token IS NULL OR NEW.claimed_at_ms IS NULL
 OR NEW.claimed_at_ms<floor(extract(epoch from transaction_timestamp())*1000) OR NEW.claimed_at_ms>floor(extract(epoch from clock_timestamp())*1000)
